INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u3-C1','sci',5,2,'u3',1,'열 변색 붙임딱지와 따뜻함 — 체온에서 변하는 열 변색 붙임딱지는 따뜻한 손을 대었다 떼면 색깔이 바뀌거나 투명해짐 · 문지르지 않고 대고 있기만 해도 변하고, 따뜻한 물이 든 컵에 대도 변함 · 손이 학용품보다 더 따뜻하기 때문이고, 따뜻함이 사라지면 서서히 원래대로 돌아옴 · 색이 바뀌는 컵·아기 숟가락처럼 따뜻한 정도를 눈으로 알려 주는 물건에 쓰임',ARRAY['[6과07-01] 온도를 측정하는 까닭을 알고, 온도계를 사용하여 여러 가지 물체의 온도를 측정할 수 있다.']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u3-C2','sci',5,2,'u3',2,'온도와 온도의 단위 — 물체의 따뜻하거나 차가운 정도를 온도로 나타냄 · 단위는 °C이고 「섭씨도」라고 읽음(19.8 °C — 섭씨 십구 점 팔 도) · 온도는 무게·부피·길이와 다른 것',ARRAY['[6과07-01] 온도를 측정하는 까닭을 알고, 온도계를 사용하여 여러 가지 물체의 온도를 측정할 수 있다.']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u3-C3','sci',5,2,'u3',2,'여러 가지 온도계 바르게 쓰기 — 탐침 온도계: 탐침을 액체나 물체 속에 넣고, 컵 벽·바닥에 닿지 않게 하며 숫자가 멈추면 읽음 · 알코올 온도계: 빨간 액체 기둥 끝을 눈높이에서 읽고 공기·액체 온도를 잼 · 적외선 온도계: 물체 표면을 겨누어 빠르게 재되 사람 눈을 향하지 않게 하고, 금속·거울처럼 빛을 반사하는 물체는 재기 어려움 · 상황에 맞는 온도계를 고름',ARRAY['[6과07-01] 온도를 측정하는 까닭을 알고, 온도계를 사용하여 여러 가지 물체의 온도를 측정할 수 있다.']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u3-C4','sci',5,2,'u3',2,'온도를 재는 까닭 — 손으로 느끼는 따뜻하고 차가운 정도는 사람마다·상황마다 달라 정확하지 않음 · 온도계로 재면 누구나 같게, 정확하게 알 수 있음 · 체온 재기·요리·온실 식물 기르기처럼 알맞은 온도를 맞추는 데 쓰임 · 열화상 사진기는 온도를 색깔로 보여 줌',ARRAY['[6과07-01] 온도를 측정하는 까닭을 알고, 온도계를 사용하여 여러 가지 물체의 온도를 측정할 수 있다.']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u3-C5','sci',5,2,'u3',3,'온도가 다른 두 물체의 온도 변화 — 따뜻한 물이 든 원통에 차가운 물이 든 캔을 넣고 1분마다 재면 따뜻한 물은 점점 낮아지고 차가운 물은 점점 높아짐 · 변화는 처음엔 크고 점점 작아지며, 시간이 충분히 지나면 두 물의 온도가 같아짐 · 차가운 물이 따뜻한 물보다 높아지지는 않음 · 꺾은선그래프로 나타내면 변화를 한눈에 봄',ARRAY['[6과07-02] 온도가 다른 두 물체가 접촉할 때 두 물체의 온도 변화를 관찰하고, 열의 이동을 설명할 수 있다.']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u3-C6','sci',5,2,'u3',3,'열의 이동 방향 — 온도가 다른 두 물체가 닿으면 온도가 높은 물체에서 온도가 낮은 물체로 열이 이동해 온도가 변함 · 얼음 위 생선(생선 → 얼음), 이마의 냉각 시트(이마 → 시트), 얼음물에 헹군 면(면 → 얼음물) · 얼음을 만질 때 차가운 기운이 손으로 오는 것이 아니라 손의 열이 얼음으로 가서 손의 온도가 낮아짐',ARRAY['[6과07-02] 온도가 다른 두 물체가 접촉할 때 두 물체의 온도 변화를 관찰하고, 열의 이동을 설명할 수 있다.']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u3-C7','sci',5,2,'u3',4,'고체에서 열의 이동 관찰 — 긴 구리판 한쪽 끝을 가열하면 가열한 곳에서 가까운 곳부터 붙임딱지 색깔이 차례로 변함 · ㄷ자 구리판에서도 열은 끊어진 틈을 건너뛰지 않고 구리판을 따라 돌아서 이동함 · 판 한가운데를 가열하면 가운데에서 바깥쪽으로 둥글게 퍼짐 · 붙임딱지는 열의 이동을 보여 주는 도우미',ARRAY['[6과07-03] 고체, 액체, 기체에서 열이 이동하는 방식과 빛에 의해 열이 이동하는 방식을 관찰하고 비교할 수 있다.']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u3-C8','sci',5,2,'u3',4,'전도 — 온도가 높은 부분에서 온도가 낮은 부분으로 고체 물질을 따라 열이 이동하는 방식 · 종류가 다른 고체라도 맞닿아 있거나 이어져 있으면 열이 이동함(금속 프라이팬 → 달걀, 손 → 차가운 금속 손잡이) · 석쇠에 닿지 않은 고기 윗부분도 고기를 따라 전도로 익음',ARRAY['[6과07-03] 고체, 액체, 기체에서 열이 이동하는 방식과 빛에 의해 열이 이동하는 방식을 관찰하고 비교할 수 있다.']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u3-C9','sci',5,2,'u3',4,'생활 속 전도 — 프라이팬·냄비는 열이 잘 이동하는 금속으로 만들어 바닥의 열이 음식까지 빨리 전해짐 · 손잡이는 나무·플라스틱으로 만들어 손이 데지 않게 함 · 뜨거운 국에 담근 금속 숟가락은 담긴 부분부터 손잡이 쪽으로 뜨거워짐 · 생활 도구는 전도를 이용하기도 막기도 함',ARRAY['[6과07-03] 고체, 액체, 기체에서 열이 이동하는 방식과 빛에 의해 열이 이동하는 방식을 관찰하고 비교할 수 있다.']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u3-C10','sci',5,2,'u3',5,'액체에서 열의 이동 관찰 — 물이 든 사각 통 바닥의 잉크 아래에 뜨거운 물 컵을 넣으면 잉크가 위로 올라갔다가 옆으로 퍼지며 내려옴 · 데워진 물이 위로 올라가고 위의 물이 내려오기 때문 · 잉크는 물의 움직임을 보여 주는 도우미이고 열 자체는 눈에 보이지 않음',ARRAY['[6과07-03] 고체, 액체, 기체에서 열이 이동하는 방식과 빛에 의해 열이 이동하는 방식을 관찰하고 비교할 수 있다.']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u3-C11','sci',5,2,'u3',5,'기체에서 열의 이동 관찰 — 아크릴 통 안 한가운데에 촛불을 두면 윗부분 붙임딱지 색깔이 먼저 변함 · 데워진 공기가 위로 올라가기 때문 · 찜기 맨 위 칸 만두까지 익는 것도 뜨거운 김이 위로 올라가기 때문',ARRAY['[6과07-03] 고체, 액체, 기체에서 열이 이동하는 방식과 빛에 의해 열이 이동하는 방식을 관찰하고 비교할 수 있다.']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u3-C12','sci',5,2,'u3',5,'대류 — 액체나 기체를 가열하면 온도가 높아진 물질이 위로 올라가고 온도가 낮은 물질이 아래로 내려오며 열이 이동하는 방식 · 물질이 직접 움직이며 열을 옮기고, 이렇게 돌며 전체가 데워짐 · 고체에서 일어나는 전도와 다름',ARRAY['[6과07-03] 고체, 액체, 기체에서 열이 이동하는 방식과 빛에 의해 열이 이동하는 방식을 관찰하고 비교할 수 있다.']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u3-C13','sci',5,2,'u3',5,'생활 속 대류 — 주전자 바닥만 가열해도 물이 위아래로 돌며 물 전체가 뜨거워짐 · 난방기는 방 아래쪽에 두면 데워진 공기가 올라가며 방 전체가 따뜻해짐 · 냉방기는 높은 곳에 달면 차가운 공기가 내려오며 방 전체가 시원해짐 · 기구의 자리를 정할 때 대류를 이용함',ARRAY['[6과07-03] 고체, 액체, 기체에서 열이 이동하는 방식과 빛에 의해 열이 이동하는 방식을 관찰하고 비교할 수 있다.']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u3-C14','sci',5,2,'u3',6,'햇빛과 그늘의 온도 견주기 — 같은 온도의 검은색 판 두 장을 햇빛과 그늘에 두고 일정 시간 뒤 적외선 온도계로 재면 햇빛을 받은 판의 온도가 더 높아짐 · 판의 색·크기·처음 온도·시간은 같게 하고 놓는 곳만 다르게 함 · 판은 해와 닿아 있지 않은데도 온도가 높아짐 · 그늘이 시원한 것은 햇빛이 가려지기 때문',ARRAY['[6과07-03] 고체, 액체, 기체에서 열이 이동하는 방식과 빛에 의해 열이 이동하는 방식을 관찰하고 비교할 수 있다.']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u3-C15','sci',5,2,'u3',6,'복사 — 빛에 의해 열이 이동하는 방식 · 물질이 닿거나 움직이지 않아도, 물질이 거의 없는 곳을 지나서도 열이 이동해 먼 해의 열이 지구까지 옴 · 난로 앞·보온 등 아래·모닥불 앞이 따뜻한 것도 복사 · 모닥불을 향한 얼굴만 뜨겁고 등은 차가움',ARRAY['[6과07-03] 고체, 액체, 기체에서 열이 이동하는 방식과 빛에 의해 열이 이동하는 방식을 관찰하고 비교할 수 있다.']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u3-C16','sci',5,2,'u3',7,'세 가지 열의 이동 방식 견주기 — 전도는 고체 물질을 따라, 대류는 액체·기체가 직접 움직이며, 복사는 빛에 의해 열이 이동함 · 프라이팬 볶음(전도), 전기 주전자 물(대류), 열 전구·난로(복사) · 화덕·오븐·모닥불 캠프처럼 한 상황에서 세 방식이 함께 일어나기도 함',ARRAY['[6과07-03] 고체, 액체, 기체에서 열이 이동하는 방식과 빛에 의해 열이 이동하는 방식을 관찰하고 비교할 수 있다.']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u3-C17','sci',5,2,'u3',8,'단열 — 열의 이동을 막는 것 · 보온병에 따뜻한 물을 담으면 오래 따뜻하게, 차가운 물이나 얼음을 담으면 오래 차갑게 지켜 줌 · 창문을 닫아 교실의 열을 지키는 것도 단열 · 단열이 잘되면 난방·냉방 에너지를 아낌',ARRAY['[6과07-04] 단열을 이용하여 온도를 일정하게 유지하는 장치를 설계하고 만들 수 있다.']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u3-C18','sci',5,2,'u3',8,'열의 이동 방식에 따라 막는 물건 — 주방 장갑·나무나 실리콘 냄비 받침(전도를 막음), 닫은 창문·문풍지(공기의 흐름, 곧 대류를 막음), 양산·그늘막(햇빛의 복사를 막음) · 아이스박스·보온 도시락·겹쳐 입은 옷·소방 보호 장비·집 벽 속 재료·이중창의 공기층도 단열 사례',ARRAY['[6과07-04] 단열을 이용하여 온도를 일정하게 유지하는 장치를 설계하고 만들 수 있다.']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u3-C19','sci',5,2,'u3',9,'단열재와 장치 설계 — 단열에 쓰는 재료를 단열재라고 함(뽁뽁이·스타이로폼·솜·이중 골판지, 주변 재료 재활용도 가능) · 단열재는 스스로 열을 만들거나 차갑게 하지 않고 열의 이동을 막아 처음 온도를 오래 지킴 · 따뜻한 것은 열이 빠져나가지 않게, 차가운 것은 열이 들어오지 않게 · 여러 겹 감싸고 틈 없이 뚜껑을 덮으며 쓰기 편한 점도 생각해 그림과 글로 설계함',ARRAY['[6과07-04] 단열을 이용하여 온도를 일정하게 유지하는 장치를 설계하고 만들 수 있다.']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u3-C20','sci',5,2,'u3',9,'장치 시험하고 고치기 — 장치에 물체를 넣고 시간 간격을 두고 온도를 재어 오랫동안 일정하게 유지되는지 확인함 · 같은 처음 온도·같은 시간이면 온도가 덜 변한 장치가 단열이 더 잘된 것 · 열이 새는 틈·얇은 곳을 찾아 막고 단열재를 더 겹쳐 고침 · 역할을 나누어 만들고 잘한 점을 나눔',ARRAY['[6과07-04] 단열을 이용하여 온도를 일정하게 유지하는 장치를 설계하고 만들 수 있다.']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u3-C21','sci',5,2,'u3',10,'첨단 단열 기술 — 아주 높은 온도를 유지해야 하는 인공 태양 연구 장치는 보온병과 비슷하게 단열함 · 이중벽 사이 공기를 빼고 단열재로 여러 번 감싸 전도와 대류를 막고, 이중벽 안쪽을 은으로 도금해 복사를 막음 · 단열 기술은 생활뿐 아니라 우주선·소방 장비 같은 첨단 기술에도 쓰임 · 공기가 거의 없는 우주에서는 태양의 복사를 가장 크게 막아야 함',ARRAY['[6과07-04] 단열을 이용하여 온도를 일정하게 유지하는 장치를 설계하고 만들 수 있다.']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SC5-2-u3-C22','sci',5,2,'u3',10,'열과 우리 생활 정리 — 온도는 온도계로 재고, 열은 온도가 높은 곳에서 낮은 곳으로 이동함 · 열은 전도·대류·복사로 이동하고 단열로 그 이동을 막음 · 상황을 보고 어디에서(고체·액체와 기체·빛) 어떤 방식으로 이동하는지 따진 뒤 막는 방법을 고름',ARRAY['[6과07-03] 고체, 액체, 기체에서 열이 이동하는 방식과 빛에 의해 열이 이동하는 방식을 관찰하고 비교할 수 있다.']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X01','sci',5,'u3',ARRAY['SC5-2-u3-C1']::text[],'열 변색 붙임딱지는 손으로 문지르거나 세게 눌러야만 변한다고 여긴다','대고 있기만 해도 변해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X02','sci',5,'u3',ARRAY['SC5-2-u3-C1']::text[],'한 번 변한 붙임딱지는 계속 그대로 남는다고 여긴다','서서히 원래대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X03','sci',5,'u3',ARRAY['SC5-2-u3-C1']::text[],'붙임딱지가 변한 까닭을 따뜻함이 아닌 엉뚱한 것(입김의 세기·펜 색·차가운 손)에서 찾는다','손의 따뜻함 때문') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X04','sci',5,'u3',ARRAY['SC5-2-u3-C4']::text[],'손으로 만져 보면 물체의 온도를 정확하게 알 수 있다고 여긴다','느낌은 사람마다 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X05','sci',5,'u3',ARRAY['SC5-2-u3-C2']::text[],'°C를 「도씨」로 읽거나 온도에 단위를 빠뜨린다','섭씨 ○ 도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X06','sci',5,'u3',ARRAY['SC5-2-u3-C3']::text[],'온도계 쓰는 법을 놓친다(탐침이 바닥에 닿음·기둥을 비스듬히 읽음·적외선을 눈에 겨눔)','가운데 · 눈높이 · 눈 피하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X07','sci',5,'u3',ARRAY['SC5-2-u3-C3']::text[],'상황에 맞지 않는 온도계를 고른다(반짝이는 금속을 적외선으로, 국 속을 겉면만)','무엇을 재나 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X08','sci',5,'u3',ARRAY['SC5-2-u3-C2']::text[],'온도를 무게·부피·길이 같은 다른 양과 헷갈린다','따뜻하거나 차가운 정도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X09','sci',5,'u3',ARRAY['SC5-2-u3-C5']::text[],'온도가 다른 두 물체가 닿으면 한쪽 온도만 변한다고 여긴다','둘 다 변해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X10','sci',5,'u3',ARRAY['SC5-2-u3-C5']::text[],'오래 두면 차가웠던 물이 따뜻했던 물보다 더 높아지거나, 두 온도가 끝내 같아지지 않는다고 여긴다','같아질 때까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X11','sci',5,'u3',ARRAY['SC5-2-u3-C6']::text[],'열이 온도가 낮은 물체에서 높은 물체로 이동한다고 여긴다','높음 → 낮음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X12','sci',5,'u3',ARRAY['SC5-2-u3-C6']::text[],'차가운 물체의 냉기(차가운 기운)가 옮겨 가서 다른 물체가 차가워진다고 여긴다','열이 빠져나가서 차가워져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X13','sci',5,'u3',ARRAY['SC5-2-u3-C5']::text[],'온도 변화 꺾은선그래프에서 선과 물을 바꾸어 읽거나 변화가 끝까지 같은 빠르기라고 읽는다','처음엔 크게 · 점점 작게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X14','sci',5,'u3',ARRAY['SC5-2-u3-C7']::text[],'고체를 가열하면 모든 곳이 한꺼번에, 또는 먼 곳부터 뜨거워진다고 여긴다','가까운 곳부터 차례로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X15','sci',5,'u3',ARRAY['SC5-2-u3-C7']::text[],'ㄷ자 구리판에서 열이 끊어진 틈을 건너뛰어 이동한다고 여긴다','판을 따라 돌아서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X16','sci',5,'u3',ARRAY['SC5-2-u3-C8']::text[],'종류가 다른 고체끼리는 맞닿아도 열이 이동하지 않는다고 여긴다','닿아 있으면 이동해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X17','sci',5,'u3',ARRAY['SC5-2-u3-C8','SC5-2-u3-C12']::text[],'전도와 대류를 헷갈린다(물이 도는 것을 전도로, 고체를 따라 가는 것을 대류로)','고체 따라 ↔ 물질이 움직이며') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X18','sci',5,'u3',ARRAY['SC5-2-u3-C9']::text[],'냄비 손잡이도 열이 잘 이동하는 금속이 좋다고 여기거나 손잡이 재료의 까닭을 거꾸로 안다','손잡이는 열이 잘 안 가게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X19','sci',5,'u3',ARRAY['SC5-2-u3-C10']::text[],'잉크나 붙임딱지의 움직임이 열 그 자체라고 여긴다(열이 눈에 보인다고)','잉크는 물의 움직임을 보여 줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X20','sci',5,'u3',ARRAY['SC5-2-u3-C10','SC5-2-u3-C11','SC5-2-u3-C12']::text[],'데워진 물이나 공기가 아래로 내려간다고 여긴다','데워지면 위로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X21','sci',5,'u3',ARRAY['SC5-2-u3-C11']::text[],'촛불을 둔 통에서 아랫부분이나 촛불 옆 붙임딱지부터 변한다고 여긴다','윗부분 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X22','sci',5,'u3',ARRAY['SC5-2-u3-C12']::text[],'대류에서 물질은 가만히 있고 열만 이동한다고 여긴다','물질이 직접 움직여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X23','sci',5,'u3',ARRAY['SC5-2-u3-C13']::text[],'난방기는 높은 곳에, 냉방기는 낮은 곳에 두어야 좋다고 여긴다','난방 아래 · 냉방 위') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X24','sci',5,'u3',ARRAY['SC5-2-u3-C14']::text[],'햇빛에 둔 판과 그늘에 둔 판의 온도가 같거나 그늘 판이 더 높아진다고 여긴다','햇빛을 받은 판이 더 높아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X25','sci',5,'u3',ARRAY['SC5-2-u3-C15']::text[],'열은 물질이 닿거나 움직여야만 이동한다고 여긴다(해의 열이 오는 길을 설명하지 못함)','빛에 의해서도 이동해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X26','sci',5,'u3',ARRAY['SC5-2-u3-C15','SC5-2-u3-C16']::text[],'복사의 예와 전도·대류의 예를 바꾸어 고른다(숟가락이 뜨거워지는 것을 복사로)','빛으로 오나, 닿아서 오나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X27','sci',5,'u3',ARRAY['SC5-2-u3-C16']::text[],'한 상황에서는 열이 한 가지 방식으로만 이동한다고 여긴다','여러 방식이 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X28','sci',5,'u3',ARRAY['SC5-2-u3-C16']::text[],'전도·대류·복사의 특징을 바꾸어 짝짓는다(복사는 물질이 닿아야, 대류는 고체에서)','고체 · 액체와 기체 · 빛') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X29','sci',5,'u3',ARRAY['SC5-2-u3-C17']::text[],'보온병은 따뜻한 것을 따뜻하게 지킬 때만 쓴다고 여긴다','차갑게도 지켜요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X30','sci',5,'u3',ARRAY['SC5-2-u3-C17']::text[],'단열을 열이 더 잘, 더 빨리 이동하게 하는 것으로 여긴다','단열은 막는 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X31','sci',5,'u3',ARRAY['SC5-2-u3-C18']::text[],'단열 물건과 그 물건이 막는 열의 이동 방식을 바꾸어 짝짓는다(양산이 전도를, 주방 장갑이 복사를)','장갑 전도 · 창문 대류 · 양산 복사') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X32','sci',5,'u3',ARRAY['SC5-2-u3-C19']::text[],'단열재가 스스로 물체를 따뜻하게(또는 차갑게) 만든다고 여긴다','막아서 지킬 뿐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X33','sci',5,'u3',ARRAY['SC5-2-u3-C19']::text[],'장치에 구멍·틈을 내거나 뚜껑을 열어 두어도 단열이 잘된다고 여긴다','틈이 열의 길') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X34','sci',5,'u3',ARRAY['SC5-2-u3-C20']::text[],'장치 성능을 온도가 아닌 색·무게·모양으로 따지거나, 온도가 더 많이 변한 쪽이 잘된 것이라고 여긴다','시간마다 온도 · 덜 변한 쪽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X35','sci',5,'u3',ARRAY['SC5-2-u3-C21']::text[],'단열 기술은 보온병이나 옷처럼 생활 속에서만 쓰인다고 여긴다','첨단 기술에도 써요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC5-2-u3-X36','sci',5,'u3',ARRAY['SC5-2-u3-C21']::text[],'첨단 단열 장치의 방법과 막는 방식을 바꾸어 짝짓는다(은 도금이 전도를, 공기를 뺀 것이 복사를)','공기 빼기 전도·대류 · 은 도금 복사') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L01_basic#1','sci',5,2,'u3','L01','g5_2_sci_u3_L01_basic','lesson_basic','SC5-2-u3-C1',1,'mc','auto','열 변색 붙임딱지에 따뜻한 손을 대었다 떼면 어떻게 되나요?',ARRAY['SC5-2-u3-X03']::text[],false,'{"seq":1,"concept":"SC5-2-u3-C1","difficulty":1,"kind":"mc","stem":"열 변색 붙임딱지에 따뜻한 손을 대었다 떼면 어떻게 되나요?","options":[{"t":"색깔이 바뀌거나 투명해진다","correct":true},{"t":"붙임딱지가 찢어진다","mis":"SC5-2-u3-X03"},{"t":"아무 변화가 없다","mis":"SC5-2-u3-X03"},{"t":"붙임딱지가 더 커진다","mis":"SC5-2-u3-X03"}],"explanation":["손을 대었다 뗐어요.","색이 바뀌었어요.","투명해지기도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L01_basic#2','sci',5,2,'u3','L01','g5_2_sci_u3_L01_basic','lesson_basic','SC5-2-u3-C1',1,'ox','auto','색깔이 변한 붙임딱지는 시간이 지나면 서서히 원래대로 돌아와요.',ARRAY['SC5-2-u3-X02']::text[],false,'{"seq":2,"concept":"SC5-2-u3-C1","difficulty":1,"kind":"ox","stem":"색깔이 변한 붙임딱지는 시간이 지나면 서서히 원래대로 돌아와요.","answer":"O","reason_options":[{"t":"손의 따뜻함이 사라지면 처음 색으로 돌아오기 때문에","correct":true},{"t":"한 번 변하면 계속 그대로 남기 때문에","mis":"SC5-2-u3-X02"}],"mis":"SC5-2-u3-X02","explanation":["손을 떼고 기다려요.","따뜻함이 사라져요.","원래대로 돌아와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L01_basic#3','sci',5,2,'u3','L01','g5_2_sci_u3_L01_basic','lesson_basic','SC5-2-u3-C1',1,'mc','auto','열 변색 붙임딱지의 색깔을 바꾸려면 무엇을 대면 되나요?',ARRAY['SC5-2-u3-X03']::text[],false,'{"seq":3,"concept":"SC5-2-u3-C1","difficulty":1,"kind":"mc","stem":"열 변색 붙임딱지의 색깔을 바꾸려면 무엇을 대면 되나요?","options":[{"t":"따뜻한 손바닥","correct":true},{"t":"얼음 조각","mis":"SC5-2-u3-X03"},{"t":"마른 지우개","mis":"SC5-2-u3-X03"},{"t":"차가운 자","mis":"SC5-2-u3-X03"}],"explanation":["따뜻함에 변해요.","손바닥이 따뜻해요.","손바닥을 대요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L01_basic#4','sci',5,2,'u3','L01','g5_2_sci_u3_L01_basic','lesson_basic','SC5-2-u3-C1',1,'sa','auto','비밀 단어 놀이에서 단어를 덮는 붙임딱지는 손을 대면 어떻게 되나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-2-u3-C1","difficulty":1,"kind":"sa","stem":"비밀 단어 놀이에서 단어를 덮는 붙임딱지는 손을 대면 어떻게 되나요? 네 글자로 쓰세요.","answer":["투명해짐","투명해져"],"explanation":["단어를 덮었어요.","손을 대면 보여요.","투명해져요."],"mis":"SC5-2-u3-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L01_basic#5','sci',5,2,'u3','L01','g5_2_sci_u3_L01_basic','lesson_basic','SC5-2-u3-C1',2,'mc','auto','두 가지 열 변색 붙임딱지에서 나 붙임딱지에 손을 대면 무엇을 볼 수 있나요?',ARRAY['SC5-2-u3-X03']::text[],false,'{"seq":5,"concept":"SC5-2-u3-C1","difficulty":2,"kind":"mc","stem":"두 가지 열 변색 붙임딱지에서 나 붙임딱지에 손을 대면 무엇을 볼 수 있나요?","options":[{"t":"아래에 있던 글씨","correct":true},{"t":"붙임딱지 뒷면의 풀","mis":"SC5-2-u3-X03"},{"t":"손바닥 무늬","mis":"SC5-2-u3-X03"},{"t":"새로 생긴 구멍","mis":"SC5-2-u3-X03"}],"explanation":["나는 투명해져요.","아래가 보여요.","글씨가 보여요."],"asset":{"type":"passage","lines":["가 붙임딱지 — 손을 대면 다른 색으로 바뀐다.","나 붙임딱지 — 손을 대면 투명해져 아래 글씨가 보인다.","두 붙임딱지 모두 손을 떼고 기다리면 처음처럼 돌아온다."],"title":"두 가지 열 변색 붙임딱지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L01_basic#6','sci',5,2,'u3','L01','g5_2_sci_u3_L01_basic','lesson_basic','SC5-2-u3-C1',2,'ox','auto','붙임딱지는 손으로 세게 문질러야만 색깔이 바뀌어요.',ARRAY['SC5-2-u3-X01']::text[],false,'{"seq":6,"concept":"SC5-2-u3-C1","difficulty":2,"kind":"ox","stem":"붙임딱지는 손으로 세게 문질러야만 색깔이 바뀌어요.","answer":"X","reason_options":[{"t":"문지르지 않고 따뜻한 손을 대고 있기만 해도 바뀌기 때문에","correct":true},{"t":"문지를 때 생기는 힘으로만 색이 바뀌기 때문에","mis":"SC5-2-u3-X01"}],"mis":"SC5-2-u3-X01","explanation":["대고 있기만 해요.","그래도 변해요.","따뜻함이 까닭이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L01_basic#7','sci',5,2,'u3','L01','g5_2_sci_u3_L01_basic','lesson_basic','SC5-2-u3-C1',2,'mc','auto','비밀 단어 놀이 차례에서 ③ 다음에 할 일은 무엇인가요?',ARRAY['SC5-2-u3-X03','SC5-2-u3-X02']::text[],false,'{"seq":7,"concept":"SC5-2-u3-C1","difficulty":2,"kind":"mc","stem":"비밀 단어 놀이 차례에서 ③ 다음에 할 일은 무엇인가요?","options":[{"t":"손바닥을 대고 기다려 단어를 맞힌다","correct":true},{"t":"유성펜으로 비밀 단어를 쓴다","mis":"SC5-2-u3-X03"},{"t":"단어를 소리 내어 알려 준다","mis":"SC5-2-u3-X03"},{"t":"붙임딱지를 떼어 버린다","mis":"SC5-2-u3-X02"}],"explanation":["짝과 바꿨어요.","손을 대요.","단어를 맞혀요."],"asset":{"type":"passage","lines":["① 연필에 유성펜으로 비밀 단어를 쓴다.","② 투명해지는 붙임딱지로 단어를 덮는다.","③ 짝과 연필을 바꾼다.","④ 손바닥을 대고 기다려 단어를 맞힌다."],"title":"비밀 단어 놀이 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L01_basic#8','sci',5,2,'u3','L01','g5_2_sci_u3_L01_basic','lesson_basic','SC5-2-u3-C1',2,'mc','auto','손을 대었을 때 붙임딱지 색깔이 바뀐 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X03','SC5-2-u3-X01']::text[],false,'{"seq":8,"concept":"SC5-2-u3-C1","difficulty":2,"kind":"mc","stem":"손을 대었을 때 붙임딱지 색깔이 바뀐 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"손이 학용품보다 더 따뜻해서","correct":true},{"t":"입김을 세게 불어서","mis":"SC5-2-u3-X03"},{"t":"펜 색이 번져서","mis":"SC5-2-u3-X03"},{"t":"손이 붙임딱지를 눌러서","mis":"SC5-2-u3-X01"}],"explanation":["손은 따뜻해요.","학용품보다 따뜻해요.","그래서 변해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L01_basic#9','sci',5,2,'u3','L01','g5_2_sci_u3_L01_basic','lesson_basic','SC5-2-u3-C1',2,'mc','auto','따뜻하고 차가운 정도를 눈으로 알려 주는 생활 속 물건은 어느 것인가요?',ARRAY['SC5-2-u3-X03']::text[],false,'{"seq":9,"concept":"SC5-2-u3-C1","difficulty":2,"kind":"mc","stem":"따뜻하고 차가운 정도를 눈으로 알려 주는 생활 속 물건은 어느 것인가요?","options":[{"t":"뜨거운 물을 부으면 그림이 나타나는 컵","correct":true},{"t":"색이 늘 같은 유리컵","mis":"SC5-2-u3-X03"},{"t":"무게를 재는 저울","mis":"SC5-2-u3-X03"},{"t":"길이를 재는 자","mis":"SC5-2-u3-X03"}],"explanation":["컵 겉면이 변해요.","따뜻하면 그림이 나와요.","눈으로 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L01_basic#10','sci',5,2,'u3','L01','g5_2_sci_u3_L01_basic','lesson_basic','SC5-2-u3-C1',3,'error','auto','붙임딱지 놀이를 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u3-X03','SC5-2-u3-X01','SC5-2-u3-X02']::text[],false,'{"seq":10,"concept":"SC5-2-u3-C1","difficulty":3,"kind":"error","stem":"붙임딱지 놀이를 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지안 — 「얼음물에 담갔다 꺼낸 손을 대야 더 빨리 변해.」","correct":true,"mis_target":"SC5-2-u3-X03"},{"t":"도현 — 「따뜻한 물이 든 컵에 대도 색이 바뀌어.」","mis":"SC5-2-u3-X01"},{"t":"수빈 — 「손을 떼면 천천히 원래 색으로 돌아와.」","mis":"SC5-2-u3-X02"}],"explanation":["붙임딱지는 따뜻함에 변해요.","차가운 손은 아니에요.","지안의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L01_challenge#1','sci',5,2,'u3','L01','g5_2_sci_u3_L01_challenge','lesson_challenge','SC5-2-u3-C1',2,'match','auto','붙임딱지 놀이 장면과 알맞은 변화를 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u3-C1","difficulty":2,"kind":"match","stem":"붙임딱지 놀이 장면과 알맞은 변화를 이으세요.","pairs":[{"l":"색이 바뀌는 붙임딱지에 손 대기","r":"다른 색으로 바뀜"},{"l":"투명해지는 붙임딱지에 손 대기","r":"아래 글씨가 보임"},{"l":"손을 떼고 기다리기","r":"원래대로 돌아옴"}],"mis":"SC5-2-u3-X02","explanation":["손을 대면 변해요.","두 가지로 변해요.","떼면 돌아와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L01_challenge#2','sci',5,2,'u3','L01','g5_2_sci_u3_L01_challenge','lesson_challenge','SC5-2-u3-C1',2,'mc','auto','같은 붙임딱지에 오래 손을 대고 있을수록 어떻게 되나요?',ARRAY['SC5-2-u3-X02','SC5-2-u3-X01','SC5-2-u3-X03']::text[],false,'{"seq":2,"concept":"SC5-2-u3-C1","difficulty":2,"kind":"mc","stem":"같은 붙임딱지에 오래 손을 대고 있을수록 어떻게 되나요?","options":[{"t":"변한 부분이 더 뚜렷해진다","correct":true},{"t":"색이 더 빨리 원래대로 돌아온다","mis":"SC5-2-u3-X02"},{"t":"대는 동안에는 전혀 변하지 않는다","mis":"SC5-2-u3-X01"},{"t":"붙임딱지가 녹아 없어진다","mis":"SC5-2-u3-X03"}],"explanation":["손의 따뜻함이 계속 와요.","더 많이 변해요.","더 뚜렷해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L01_challenge#3','sci',5,2,'u3','L01','g5_2_sci_u3_L01_challenge','lesson_challenge','SC5-2-u3-C1',3,'mc','auto','같은 붙임딱지를 붙인 자 두 개를 하나는 따뜻한 손, 하나는 얼음물에 담갔다 꺼낸 손으로 잡았어요. 붙임딱지가 더 빨리 변하는 자는 어느 것인가요?',ARRAY['SC5-2-u3-X03']::text[],false,'{"seq":3,"concept":"SC5-2-u3-C1","difficulty":3,"kind":"mc","stem":"같은 붙임딱지를 붙인 자 두 개를 하나는 따뜻한 손, 하나는 얼음물에 담갔다 꺼낸 손으로 잡았어요. 붙임딱지가 더 빨리 변하는 자는 어느 것인가요?","options":[{"t":"따뜻한 손으로 잡은 자","correct":true},{"t":"얼음물에 담갔던 손으로 잡은 자","mis":"SC5-2-u3-X03"},{"t":"두 자가 똑같이 변한다","mis":"SC5-2-u3-X03"},{"t":"두 자 모두 변하지 않는다","mis":"SC5-2-u3-X03"}],"explanation":["붙임딱지는 따뜻함에 변해요.","차가운 손은 덜 따뜻해요.","따뜻한 손 쪽이 빨라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L01_challenge#4','sci',5,2,'u3','L01','g5_2_sci_u3_L01_challenge','lesson_challenge','SC5-2-u3-C1',3,'mc','auto','손이 아닌 다른 방법으로 붙임딱지 색깔을 바꾸는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X03','SC5-2-u3-X01']::text[],false,'{"seq":4,"concept":"SC5-2-u3-C1","difficulty":3,"kind":"mc","stem":"손이 아닌 다른 방법으로 붙임딱지 색깔을 바꾸는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"따뜻한 물이 든 컵에 붙임딱지를 댄다","correct":true},{"t":"붙임딱지를 냉장고에 넣는다","mis":"SC5-2-u3-X03"},{"t":"붙임딱지에 부채질을 한다","mis":"SC5-2-u3-X03"},{"t":"붙임딱지를 연필로 톡톡 친다","mis":"SC5-2-u3-X01"}],"explanation":["따뜻한 것을 찾아요.","따뜻한 컵도 돼요.","컵에 대면 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L01_challenge#5','sci',5,2,'u3','L01','g5_2_sci_u3_L01_challenge','lesson_challenge','SC5-2-u3-C1',3,'ox','auto','붙임딱지 색깔이 바뀐 것을 보면 손이 붙임딱지보다 따뜻했다는 것을 알 수 있어요.',ARRAY['SC5-2-u3-X01']::text[],false,'{"seq":5,"concept":"SC5-2-u3-C1","difficulty":3,"kind":"ox","stem":"붙임딱지 색깔이 바뀐 것을 보면 손이 붙임딱지보다 따뜻했다는 것을 알 수 있어요.","answer":"O","reason_options":[{"t":"붙임딱지는 따뜻함이 전해질 때 색깔이 바뀌기 때문에","correct":true},{"t":"붙임딱지는 손의 힘이 셀수록 색깔이 바뀌기 때문에","mis":"SC5-2-u3-X01"}],"mis":"SC5-2-u3-X01","explanation":["따뜻함이 전해졌어요.","그래서 색이 바뀌어요.","손이 더 따뜻해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L01_challenge#6','sci',5,2,'u3','L01','g5_2_sci_u3_L01_challenge','lesson_challenge','SC5-2-u3-C1',3,'error','auto','꾸민 학용품을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u3-X02','SC5-2-u3-X03','SC5-2-u3-X01']::text[],false,'{"seq":6,"concept":"SC5-2-u3-C1","difficulty":3,"kind":"error","stem":"꾸민 학용품을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「한 번 색이 바뀐 자는 다시는 원래대로 안 돌아와.」","correct":true,"mis_target":"SC5-2-u3-X02"},{"t":"윤서 — 「손 댄 자리만 색이 바뀌었어.」","mis":"SC5-2-u3-X03"},{"t":"이준 — 「양손 사이에 끼우니 더 잘 바뀌었어.」","mis":"SC5-2-u3-X01"}],"explanation":["시간이 지나면 돌아와요.","그대로 남지 않아요.","하람의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L01_challenge#7','sci',5,2,'u3','L01','g5_2_sci_u3_L01_challenge','lesson_challenge','SC5-2-u3-C1',3,'mc','auto','아기 숟가락에 열 변색 물질을 칠해 두는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X03']::text[],false,'{"seq":7,"concept":"SC5-2-u3-C1","difficulty":3,"kind":"mc","stem":"아기 숟가락에 열 변색 물질을 칠해 두는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"음식이 너무 뜨거운지 색깔로 알려 주려고","correct":true},{"t":"숟가락을 더 무겁게 하려고","mis":"SC5-2-u3-X03"},{"t":"음식 맛을 좋게 하려고","mis":"SC5-2-u3-X03"},{"t":"숟가락이 차가워지게 하려고","mis":"SC5-2-u3-X03"}],"explanation":["뜨거우면 색이 바뀌어요.","눈으로 알 수 있어요.","아기를 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L01_challenge#8','sci',5,2,'u3','L01','g5_2_sci_u3_L01_challenge','lesson_challenge','SC5-2-u3-C1',4,'mc','auto','손을 대도 붙임딱지가 잘 변하지 않을 때 해 볼 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X01','SC5-2-u3-X03','SC5-2-u3-X02']::text[],false,'{"seq":8,"concept":"SC5-2-u3-C1","difficulty":4,"kind":"mc","stem":"손을 대도 붙임딱지가 잘 변하지 않을 때 해 볼 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"양손 사이에 끼워 지그시 누르고 조금 더 기다린다","correct":true},{"t":"붙임딱지를 세게 문질러 긁는다","mis":"SC5-2-u3-X01"},{"t":"붙임딱지에 차가운 물을 뿌린다","mis":"SC5-2-u3-X03"},{"t":"곧바로 다른 붙임딱지로 바꾼다","mis":"SC5-2-u3-X02"}],"explanation":["따뜻함을 더 전해요.","양손으로 감싸요.","조금 더 기다려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L01_challenge#9','sci',5,2,'u3','L01','g5_2_sci_u3_L01_challenge','lesson_challenge','SC5-2-u3-C1',4,'mc','auto','화덕 안 피자가 익는 것과 붙임딱지가 손에 변하는 것의 공통점을 가장 잘 말한 것은 어느 것인가요?',ARRAY['SC5-2-u3-X01','SC5-2-u3-X03']::text[],false,'{"seq":9,"concept":"SC5-2-u3-C1","difficulty":4,"kind":"mc","stem":"화덕 안 피자가 익는 것과 붙임딱지가 손에 변하는 것의 공통점을 가장 잘 말한 것은 어느 것인가요?","options":[{"t":"따뜻한 쪽의 따뜻함이 다른 물체로 전해져 변화가 생긴다","correct":true},{"t":"세게 누르는 힘 때문에 변화가 생긴다","mis":"SC5-2-u3-X01"},{"t":"차가운 기운이 빠져나가 변화가 생긴다","mis":"SC5-2-u3-X03"},{"t":"색깔이 서로 섞여 변화가 생긴다","mis":"SC5-2-u3-X03"}],"explanation":["화덕은 뜨거워요.","손도 따뜻해요.","따뜻함이 전해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L01_challenge#10','sci',5,2,'u3','L01','g5_2_sci_u3_L01_challenge','lesson_challenge','SC5-2-u3-C1',4,'essay','teacher','열 변색 붙임딱지를 생활 속 어디에 쓰면 좋을지 한 곳을 정하고, 어떻게 도움이 되는지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u3-C1","difficulty":4,"kind":"essay","stem":"열 변색 붙임딱지를 생활 속 어디에 쓰면 좋을지 한 곳을 정하고, 어떻게 도움이 되는지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 아기 젖병에 붙이면 좋겠다. 우유가 너무 뜨거우면 붙임딱지 색깔이 바뀌어 먹이기 전에 알 수 있기 때문이다.","scoring_points":["쓸 곳을 정했는가","붙임딱지가 따뜻함에 변한다는 점을 썼는가","어떤 도움이 되는지 까닭을 썼는가"]},"explanation":["쓸 곳을 정해요.","따뜻함에 변해요.","도움을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L02_basic#1','sci',5,2,'u3','L02','g5_2_sci_u3_L02_basic','lesson_basic','SC5-2-u3-C2',1,'mc','auto','물체의 따뜻하거나 차가운 정도를 나타내는 것은 어느 것인가요?',ARRAY['SC5-2-u3-X08']::text[],false,'{"seq":1,"concept":"SC5-2-u3-C2","difficulty":1,"kind":"mc","stem":"물체의 따뜻하거나 차가운 정도를 나타내는 것은 어느 것인가요?","options":[{"t":"온도","correct":true},{"t":"무게","mis":"SC5-2-u3-X08"},{"t":"부피","mis":"SC5-2-u3-X08"},{"t":"길이","mis":"SC5-2-u3-X08"}],"explanation":["따뜻한 정도를 나타내요.","숫자로 나타내요.","온도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L02_basic#2','sci',5,2,'u3','L02','g5_2_sci_u3_L02_basic','lesson_basic','SC5-2-u3-C2',1,'sa','auto','온도의 단위 °C는 어떻게 읽나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-2-u3-C2","difficulty":1,"kind":"sa","stem":"온도의 단위 °C는 어떻게 읽나요? 세 글자로 쓰세요.","answer":["섭씨도"],"explanation":["°C는 단위예요.","도씨가 아니에요.","섭씨도예요."],"mis":"SC5-2-u3-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L02_basic#3','sci',5,2,'u3','L02','g5_2_sci_u3_L02_basic','lesson_basic','SC5-2-u3-C3',1,'mc','auto','물체 표면을 겨누고 단추를 눌러 온도를 빠르게 재는 온도계는 어느 것인가요?',ARRAY['SC5-2-u3-X07','SC5-2-u3-X08']::text[],false,'{"seq":3,"concept":"SC5-2-u3-C3","difficulty":1,"kind":"mc","stem":"물체 표면을 겨누고 단추를 눌러 온도를 빠르게 재는 온도계는 어느 것인가요?","options":[{"t":"적외선 온도계","correct":true},{"t":"탐침 온도계","mis":"SC5-2-u3-X07"},{"t":"알코올 온도계","mis":"SC5-2-u3-X07"},{"t":"저울","mis":"SC5-2-u3-X08"}],"explanation":["겨누어요.","표면 온도를 재요.","적외선 온도계예요."],"asset":{"type":"passage","lines":["㉮ 탐침 온도계 — 탐침을 액체나 물체 속에 넣어 잰다.","㉯ 알코올 온도계 — 빨간 액체 기둥 끝을 읽는다.","㉰ 적외선 온도계 — 물체 표면을 겨누고 단추를 누른다."],"title":"세 가지 온도계"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L02_basic#4','sci',5,2,'u3','L02','g5_2_sci_u3_L02_basic','lesson_basic','SC5-2-u3-C4',1,'ox','auto','손으로 만져 보면 물체의 온도를 정확하게 알 수 있어요.',ARRAY['SC5-2-u3-X04']::text[],false,'{"seq":4,"concept":"SC5-2-u3-C4","difficulty":1,"kind":"ox","stem":"손으로 만져 보면 물체의 온도를 정확하게 알 수 있어요.","answer":"X","reason_options":[{"t":"손으로 느끼는 정도는 사람마다 달라 온도계로 재야 정확하기 때문에","correct":true},{"t":"손은 누구나 똑같이 느끼기 때문에","mis":"SC5-2-u3-X04"}],"mis":"SC5-2-u3-X04","explanation":["느낌은 사람마다 달라요.","정확하지 않아요.","온도계로 재요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L02_basic#5','sci',5,2,'u3','L02','g5_2_sci_u3_L02_basic','lesson_basic','SC5-2-u3-C2',2,'mc','auto','19.8 °C를 바르게 읽은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X05']::text[],false,'{"seq":5,"concept":"SC5-2-u3-C2","difficulty":2,"kind":"mc","stem":"19.8 °C를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"섭씨 십구 점 팔 도","correct":true},{"t":"십구 점 팔 도씨","mis":"SC5-2-u3-X05"},{"t":"십구 팔 씨","mis":"SC5-2-u3-X05"},{"t":"섭씨 백구십팔 도","mis":"SC5-2-u3-X05"}],"explanation":["°C는 섭씨도예요.","소수점은 점이에요.","섭씨 십구 점 팔 도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L02_basic#6','sci',5,2,'u3','L02','g5_2_sci_u3_L02_basic','lesson_basic','SC5-2-u3-C3',2,'mc','auto','탐침 온도계로 컵 속 물의 온도를 잴 때 바른 방법은 어느 것인가요?',ARRAY['SC5-2-u3-X06']::text[],false,'{"seq":6,"concept":"SC5-2-u3-C3","difficulty":2,"kind":"mc","stem":"탐침 온도계로 컵 속 물의 온도를 잴 때 바른 방법은 어느 것인가요?","options":[{"t":"탐침을 물 가운데에 넣고 컵 벽이나 바닥에 닿지 않게 한다","correct":true},{"t":"탐침 끝을 컵 바닥에 꾹 누른다","mis":"SC5-2-u3-X06"},{"t":"숫자가 바뀌는 동안 바로 읽는다","mis":"SC5-2-u3-X06"},{"t":"탐침의 뾰족한 끝을 친구 쪽으로 든다","mis":"SC5-2-u3-X06"}],"explanation":["물 가운데에 넣어요.","닿지 않게 해요.","숫자가 멈추면 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L02_basic#7','sci',5,2,'u3','L02','g5_2_sci_u3_L02_basic','lesson_basic','SC5-2-u3-C3',2,'mc','auto','알코올 온도계를 읽는 바른 방법은 어느 것인가요?',ARRAY['SC5-2-u3-X06']::text[],false,'{"seq":7,"concept":"SC5-2-u3-C3","difficulty":2,"kind":"mc","stem":"알코올 온도계를 읽는 바른 방법은 어느 것인가요?","options":[{"t":"빨간 액체 기둥 끝을 눈높이에서 읽는다","correct":true},{"t":"액체 기둥 끝을 위에서 내려다보고 읽는다","mis":"SC5-2-u3-X06"},{"t":"액체 기둥이 시작하는 아래 끝을 읽는다","mis":"SC5-2-u3-X06"},{"t":"온도계를 흔든 뒤 바로 읽는다","mis":"SC5-2-u3-X06"}],"explanation":["기둥 끝을 봐요.","눈높이를 맞춰요.","그때 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L02_basic#8','sci',5,2,'u3','L02','g5_2_sci_u3_L02_basic','lesson_basic','SC5-2-u3-C4',2,'mc','auto','온도계로 온도를 재면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X08','SC5-2-u3-X03','SC5-2-u3-X04']::text[],false,'{"seq":8,"concept":"SC5-2-u3-C4","difficulty":2,"kind":"mc","stem":"온도계로 온도를 재면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"누구나 같게, 정확하게 알 수 있다","correct":true},{"t":"물체가 더 따뜻해진다","mis":"SC5-2-u3-X08"},{"t":"물체의 색깔이 바뀐다","mis":"SC5-2-u3-X03"},{"t":"사람마다 다르게 알 수 있다","mis":"SC5-2-u3-X04"}],"explanation":["숫자로 나와요.","누구나 같아요.","정확해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L02_basic#9','sci',5,2,'u3','L02','g5_2_sci_u3_L02_basic','lesson_basic','SC5-2-u3-C3',2,'ox','auto','적외선 온도계를 쓸 때는 빛이 사람 눈을 향하지 않게 해요.',ARRAY['SC5-2-u3-X06']::text[],false,'{"seq":9,"concept":"SC5-2-u3-C3","difficulty":2,"kind":"ox","stem":"적외선 온도계를 쓸 때는 빛이 사람 눈을 향하지 않게 해요.","answer":"O","reason_options":[{"t":"눈을 다치지 않게 안전 수칙을 지켜야 하기 때문에","correct":true},{"t":"눈을 겨누어야 체온이 정확하게 나오기 때문에","mis":"SC5-2-u3-X06"}],"mis":"SC5-2-u3-X06","explanation":["빛이 나와요.","눈은 피해요.","안전하게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L02_basic#10','sci',5,2,'u3','L02','g5_2_sci_u3_L02_basic','lesson_basic','SC5-2-u3-C4',3,'error','auto','같은 교실에서 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u3-X04','SC5-2-u3-X05']::text[],false,'{"seq":10,"concept":"SC5-2-u3-C4","difficulty":3,"kind":"error","stem":"같은 교실에서 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「내가 춥다고 느꼈으니까 교실 온도는 낮은 게 맞아.」","correct":true,"mis_target":"SC5-2-u3-X04"},{"t":"아린 — 「느낌은 사람마다 다르니 온도계로 재 보자.」","mis":"SC5-2-u3-X05"},{"t":"민재 — 「온도계 숫자에 °C를 붙여 써야 해.」","mis":"SC5-2-u3-X05"}],"explanation":["느낌은 사람마다 달라요.","재 봐야 알아요.","태오의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L02_challenge#1','sci',5,2,'u3','L02','g5_2_sci_u3_L02_challenge','lesson_challenge','SC5-2-u3-C3',2,'match','auto','온도계와 알맞은 사용법을 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u3-C3","difficulty":2,"kind":"match","stem":"온도계와 알맞은 사용법을 이으세요.","pairs":[{"l":"탐침 온도계","r":"탐침을 액체 속에 넣는다"},{"l":"알코올 온도계","r":"기둥 끝을 눈높이에서 읽는다"},{"l":"적외선 온도계","r":"표면을 겨누고 단추를 누른다"}],"mis":"SC5-2-u3-X06","explanation":["탐침은 넣어요.","알코올은 기둥 끝이에요.","적외선은 겨누어요."],"asset":{"type":"passage","lines":["㉮ 탐침 온도계 — 탐침을 액체나 물체 속에 넣어 잰다.","㉯ 알코올 온도계 — 빨간 액체 기둥 끝을 읽는다.","㉰ 적외선 온도계 — 물체 표면을 겨누고 단추를 누른다."],"title":"세 가지 온도계"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L02_challenge#2','sci',5,2,'u3','L02','g5_2_sci_u3_L02_challenge','lesson_challenge','SC5-2-u3-C4',2,'mc','auto','온도 측정 표에서 손 느낌과 잰 온도를 견주어 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-2-u3-X04','SC5-2-u3-X08']::text[],false,'{"seq":2,"concept":"SC5-2-u3-C4","difficulty":2,"kind":"mc","stem":"온도 측정 표에서 손 느낌과 잰 온도를 견주어 알 수 있는 것은 어느 것인가요?","options":[{"t":"손 느낌만으로는 정확한 온도를 알기 어렵다","correct":true},{"t":"손 느낌과 잰 온도는 늘 똑같다","mis":"SC5-2-u3-X04"},{"t":"온도계보다 손이 더 정확하다","mis":"SC5-2-u3-X04"},{"t":"물체의 무게를 알 수 있다","mis":"SC5-2-u3-X08"}],"explanation":["느낌은 말로만 나와요.","숫자는 정확해요.","온도계가 필요해요."],"asset":{"type":"passage","lines":["물 — 손 느낌: 미지근하다 · 잰 온도: 24.5 °C","주스 — 손 느낌: 차갑다 · 잰 온도: 8.2 °C","책상 — 손 느낌: 조금 차갑다 · 잰 온도: 21.0 °C","창가 화분 흙 — 손 느낌: 따뜻하다 · 잰 온도: 26.3 °C"],"title":"온도 측정 표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L02_challenge#3','sci',5,2,'u3','L02','g5_2_sci_u3_L02_challenge','lesson_challenge','SC5-2-u3-C2',3,'mc','auto','온도 측정 표에서 온도가 가장 높은 물체는 어느 것인가요?',ARRAY['SC5-2-u3-X13']::text[],false,'{"seq":3,"concept":"SC5-2-u3-C2","difficulty":3,"kind":"mc","stem":"온도 측정 표에서 온도가 가장 높은 물체는 어느 것인가요?","options":[{"t":"창가 화분 흙","correct":true},{"t":"물","mis":"SC5-2-u3-X13"},{"t":"주스","mis":"SC5-2-u3-X13"},{"t":"책상","mis":"SC5-2-u3-X13"}],"explanation":["숫자를 견줘요.","26.3 °C가 가장 커요.","화분 흙이에요."],"asset":{"type":"passage","lines":["물 — 손 느낌: 미지근하다 · 잰 온도: 24.5 °C","주스 — 손 느낌: 차갑다 · 잰 온도: 8.2 °C","책상 — 손 느낌: 조금 차갑다 · 잰 온도: 21.0 °C","창가 화분 흙 — 손 느낌: 따뜻하다 · 잰 온도: 26.3 °C"],"title":"온도 측정 표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L02_challenge#4','sci',5,2,'u3','L02','g5_2_sci_u3_L02_challenge','lesson_challenge','SC5-2-u3-C3',3,'mc','auto','반짝이는 금속 냄비 속 국의 온도를 바르게 재는 방법은 어느 것인가요?',ARRAY['SC5-2-u3-X07','SC5-2-u3-X04','SC5-2-u3-X06']::text[],false,'{"seq":4,"concept":"SC5-2-u3-C3","difficulty":3,"kind":"mc","stem":"반짝이는 금속 냄비 속 국의 온도를 바르게 재는 방법은 어느 것인가요?","options":[{"t":"탐침 온도계를 국 속에 넣어 잰다","correct":true},{"t":"적외선 온도계로 반짝이는 냄비 겉면을 잰다","mis":"SC5-2-u3-X07"},{"t":"손을 국에 넣어 느껴 본다","mis":"SC5-2-u3-X04"},{"t":"알코올 온도계를 냄비 바닥에 붙여 잰다","mis":"SC5-2-u3-X06"}],"explanation":["금속은 빛을 반사해요.","적외선은 어려워요.","탐침을 국에 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L02_challenge#5','sci',5,2,'u3','L02','g5_2_sci_u3_L02_challenge','lesson_challenge','SC5-2-u3-C3',3,'mc','auto','어항 속 물의 온도를 날마다 같은 방법으로 보고 싶어요. 가장 알맞은 온도계는 어느 것인가요?',ARRAY['SC5-2-u3-X06','SC5-2-u3-X04','SC5-2-u3-X07']::text[],false,'{"seq":5,"concept":"SC5-2-u3-C3","difficulty":3,"kind":"mc","stem":"어항 속 물의 온도를 날마다 같은 방법으로 보고 싶어요. 가장 알맞은 온도계는 어느 것인가요?","options":[{"t":"어항 속에 넣어 두고 기둥 끝을 읽는 알코올 온도계","correct":true},{"t":"물 표면만 겨누는 적외선 온도계를 눈높이에서 쓴다","mis":"SC5-2-u3-X06"},{"t":"어항 유리를 손으로 만져 본다","mis":"SC5-2-u3-X04"},{"t":"체온용 온도계로 물고기를 잰다","mis":"SC5-2-u3-X07"}],"explanation":["물속 온도를 재요.","넣어 둘 수 있어요.","알코올 온도계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L02_challenge#6','sci',5,2,'u3','L02','g5_2_sci_u3_L02_challenge','lesson_challenge','SC5-2-u3-C4',3,'ox','auto','병원에서 체온을 재고 온실에서 온도를 맞추는 것은 알맞은 온도를 알아야 하기 때문이에요.',ARRAY['SC5-2-u3-X04']::text[],false,'{"seq":6,"concept":"SC5-2-u3-C4","difficulty":3,"kind":"ox","stem":"병원에서 체온을 재고 온실에서 온도를 맞추는 것은 알맞은 온도를 알아야 하기 때문이에요.","answer":"O","reason_options":[{"t":"건강과 식물 기르기에 알맞은 온도가 있기 때문에","correct":true},{"t":"온도계 숫자가 예뻐 보이기 때문에","mis":"SC5-2-u3-X04"}],"mis":"SC5-2-u3-X04","explanation":["체온으로 건강을 봐요.","식물도 알맞은 온도가 있어요.","그래서 재요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L02_challenge#7','sci',5,2,'u3','L02','g5_2_sci_u3_L02_challenge','lesson_challenge','SC5-2-u3-C3',3,'error','auto','온도를 재며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u3-X06']::text[],false,'{"seq":7,"concept":"SC5-2-u3-C3","difficulty":3,"kind":"error","stem":"온도를 재며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시후 — 「알코올 온도계는 위에서 내려다보고 읽어야 정확해.」","correct":true,"mis_target":"SC5-2-u3-X06"},{"t":"예린 — 「탐침이 컵 바닥에 닿지 않게 했어.」","mis":"SC5-2-u3-X06"},{"t":"주원 — 「적외선 온도계 빛이 친구 얼굴로 가지 않게 했어.」","mis":"SC5-2-u3-X06"}],"explanation":["기둥 끝은 눈높이에서요.","내려다보면 틀려요.","시후의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L02_challenge#8','sci',5,2,'u3','L02','g5_2_sci_u3_L02_challenge','lesson_challenge','SC5-2-u3-C4',4,'mc','auto','「책상이 칠판보다 차갑게 느껴지니 책상 온도가 더 낮아.」라는 말을 확인하는 계획으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X04','SC5-2-u3-X08']::text[],false,'{"seq":8,"concept":"SC5-2-u3-C4","difficulty":4,"kind":"mc","stem":"「책상이 칠판보다 차갑게 느껴지니 책상 온도가 더 낮아.」라는 말을 확인하는 계획으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"적외선 온도계로 두 물체 표면을 같은 방법으로 재어 숫자를 견준다","correct":true},{"t":"여러 친구에게 만져 보게 하고 많이 나온 말을 따른다","mis":"SC5-2-u3-X04"},{"t":"두 물체의 무게를 재어 견준다","mis":"SC5-2-u3-X08"},{"t":"책상만 재고 칠판은 느낌으로 정한다","mis":"SC5-2-u3-X04"}],"explanation":["같은 방법으로 재요.","숫자를 견줘요.","그래야 확인돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L02_challenge#9','sci',5,2,'u3','L02','g5_2_sci_u3_L02_challenge','lesson_challenge','SC5-2-u3-C2',4,'mc','auto','온도를 「따뜻하다」, 「차갑다」 대신 숫자와 °C로 나타내면 좋은 점을 가장 잘 말한 것은 어느 것인가요?',ARRAY['SC5-2-u3-X08','SC5-2-u3-X03','SC5-2-u3-X05']::text[],false,'{"seq":9,"concept":"SC5-2-u3-C2","difficulty":4,"kind":"mc","stem":"온도를 「따뜻하다」, 「차갑다」 대신 숫자와 °C로 나타내면 좋은 점을 가장 잘 말한 것은 어느 것인가요?","options":[{"t":"얼마나 따뜻하거나 차가운지 누구에게나 같게 전할 수 있다","correct":true},{"t":"물체의 무게까지 함께 알 수 있다","mis":"SC5-2-u3-X08"},{"t":"말로 하는 것보다 물체가 빨리 식는다","mis":"SC5-2-u3-X03"},{"t":"°C를 붙이지 않아도 뜻이 같다","mis":"SC5-2-u3-X05"}],"explanation":["말은 사람마다 달라요.","숫자는 같아요.","정확히 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L02_challenge#10','sci',5,2,'u3','L02','g5_2_sci_u3_L02_challenge','lesson_challenge','SC5-2-u3-C4',4,'essay','teacher','우리 집에서 온도계를 두면 좋은 곳 한 곳을 정하고, 어떤 온도계가 알맞은지와 그곳의 온도를 재면 좋은 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u3-C4","difficulty":4,"kind":"essay","stem":"우리 집에서 온도계를 두면 좋은 곳 한 곳을 정하고, 어떤 온도계가 알맞은지와 그곳의 온도를 재면 좋은 까닭을 쓰세요.","answer_guide":{"answer":"예: 냉장고 안에 알코올 온도계를 두면 좋겠다. 음식이 상하지 않게 냉장고가 충분히 차가운지 늘 같은 방법으로 확인할 수 있기 때문이다.","scoring_points":["온도계를 둘 곳을 정했는가","알맞은 온도계를 골랐는가","온도를 재면 좋은 까닭을 썼는가"]},"explanation":["곳을 정해요.","온도계를 골라요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L03_basic#1','sci',5,2,'u3','L03','g5_2_sci_u3_L03_basic','lesson_basic','SC5-2-u3-C5',1,'mc','auto','따뜻한 물이 든 원통에 차가운 물이 든 캔을 넣었어요. 캔 속 차가운 물의 온도는 어떻게 되나요?',ARRAY['SC5-2-u3-X09','SC5-2-u3-X10']::text[],false,'{"seq":1,"concept":"SC5-2-u3-C5","difficulty":1,"kind":"mc","stem":"따뜻한 물이 든 원통에 차가운 물이 든 캔을 넣었어요. 캔 속 차가운 물의 온도는 어떻게 되나요?","options":[{"t":"점점 높아진다","correct":true},{"t":"점점 낮아진다","mis":"SC5-2-u3-X09"},{"t":"변하지 않는다","mis":"SC5-2-u3-X09"},{"t":"따뜻한 물보다 더 높아진다","mis":"SC5-2-u3-X10"}],"explanation":["따뜻한 물과 닿았어요.","열을 받아요.","온도가 높아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L03_basic#2','sci',5,2,'u3','L03','g5_2_sci_u3_L03_basic','lesson_basic','SC5-2-u3-C6',1,'mc','auto','온도가 다른 두 물체가 닿을 때 열은 어느 쪽으로 이동하나요?',ARRAY['SC5-2-u3-X11','SC5-2-u3-X09']::text[],false,'{"seq":2,"concept":"SC5-2-u3-C6","difficulty":1,"kind":"mc","stem":"온도가 다른 두 물체가 닿을 때 열은 어느 쪽으로 이동하나요?","options":[{"t":"온도가 높은 물체에서 온도가 낮은 물체로","correct":true},{"t":"온도가 낮은 물체에서 온도가 높은 물체로","mis":"SC5-2-u3-X11"},{"t":"큰 물체에서 작은 물체로","mis":"SC5-2-u3-X11"},{"t":"이동하지 않는다","mis":"SC5-2-u3-X09"}],"explanation":["온도를 견줘요.","높은 쪽에서 나가요.","낮은 쪽으로 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L03_basic#3','sci',5,2,'u3','L03','g5_2_sci_u3_L03_basic','lesson_basic','SC5-2-u3-C5',1,'ox','auto','시간이 충분히 지나면 맞닿은 두 물의 온도는 같아져요.',ARRAY['SC5-2-u3-X10']::text[],false,'{"seq":3,"concept":"SC5-2-u3-C5","difficulty":1,"kind":"ox","stem":"시간이 충분히 지나면 맞닿은 두 물의 온도는 같아져요.","answer":"O","reason_options":[{"t":"온도가 다를 동안 열이 이동해 결국 온도가 같아지기 때문에","correct":true},{"t":"두 물은 끝까지 처음 온도를 지키기 때문에","mis":"SC5-2-u3-X10"}],"mis":"SC5-2-u3-X10","explanation":["열이 이동해요.","차이가 줄어요.","같아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L03_basic#4','sci',5,2,'u3','L03','g5_2_sci_u3_L03_basic','lesson_basic','SC5-2-u3-C6',1,'sa','auto','생선 가게에서 생선을 얼음 위에 두었어요. 열은 생선과 얼음 가운데 어디에서 어디로 이동하나요? 「○○에서 ○○으로」로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-2-u3-C6","difficulty":1,"kind":"sa","stem":"생선 가게에서 생선을 얼음 위에 두었어요. 열은 생선과 얼음 가운데 어디에서 어디로 이동하나요? 「○○에서 ○○으로」로 쓰세요.","answer":["생선에서 얼음으로"],"explanation":["생선이 더 따뜻해요.","열은 높은 쪽에서 가요.","생선에서 얼음으로예요."],"mis":"SC5-2-u3-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L03_basic#5','sci',5,2,'u3','L03','g5_2_sci_u3_L03_basic','lesson_basic','SC5-2-u3-C5',2,'mc','auto','두 물의 온도 변화 그래프에서 따뜻한 물의 온도는 어떻게 변하나요?',ARRAY['SC5-2-u3-X13','SC5-2-u3-X09','SC5-2-u3-X10']::text[],false,'{"seq":5,"concept":"SC5-2-u3-C5","difficulty":2,"kind":"mc","stem":"두 물의 온도 변화 그래프에서 따뜻한 물의 온도는 어떻게 변하나요?","options":[{"t":"처음 40 °C에서 점점 낮아져 30 °C에서 멈춘다","correct":true},{"t":"처음 10 °C에서 점점 높아진다","mis":"SC5-2-u3-X13"},{"t":"끝까지 40 °C로 그대로이다","mis":"SC5-2-u3-X09"},{"t":"점점 낮아져 차가운 물보다 낮아진다","mis":"SC5-2-u3-X10"}],"explanation":["위쪽 선을 봐요.","내려가요.","30 °C에서 멈춰요."],"asset":{"type":"lgraph","xs":["0","1","2","3","4","5","6"],"series":[{"name":"따뜻한 물","vals":[40,36,34,32,30,30,30]},{"name":"차가운 물","vals":[10,18,24,28,30,30,30]}],"step":2,"ymax":44,"ylab":"(°C)","xlab":"(분)","title":"두 물의 온도 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L03_basic#6','sci',5,2,'u3','L03','g5_2_sci_u3_L03_basic','lesson_basic','SC5-2-u3-C5',2,'mc','auto','두 물의 온도 변화 그래프에서 두 물의 온도가 처음으로 같아진 때는 언제인가요?',ARRAY['SC5-2-u3-X13']::text[],false,'{"seq":6,"concept":"SC5-2-u3-C5","difficulty":2,"kind":"mc","stem":"두 물의 온도 변화 그래프에서 두 물의 온도가 처음으로 같아진 때는 언제인가요?","options":[{"t":"4분","correct":true},{"t":"0분","mis":"SC5-2-u3-X13"},{"t":"2분","mis":"SC5-2-u3-X13"},{"t":"6분","mis":"SC5-2-u3-X13"}],"explanation":["두 선이 만나요.","4분에 30 °C예요.","4분이에요."],"asset":{"type":"lgraph","xs":["0","1","2","3","4","5","6"],"series":[{"name":"따뜻한 물","vals":[40,36,34,32,30,30,30]},{"name":"차가운 물","vals":[10,18,24,28,30,30,30]}],"step":2,"ymax":44,"ylab":"(°C)","xlab":"(분)","title":"두 물의 온도 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L03_basic#7','sci',5,2,'u3','L03','g5_2_sci_u3_L03_basic','lesson_basic','SC5-2-u3-C6',2,'mc','auto','열이 나는 이마에 냉각 시트를 붙였어요. 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-2-u3-X12','SC5-2-u3-X11','SC5-2-u3-X09']::text[],false,'{"seq":7,"concept":"SC5-2-u3-C6","difficulty":2,"kind":"mc","stem":"열이 나는 이마에 냉각 시트를 붙였어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"이마에서 냉각 시트로 열이 이동해 이마의 온도가 낮아진다","correct":true},{"t":"냉각 시트의 냉기가 이마로 이동한다","mis":"SC5-2-u3-X12"},{"t":"냉각 시트에서 이마로 열이 이동한다","mis":"SC5-2-u3-X11"},{"t":"이마와 시트 모두 온도가 변하지 않는다","mis":"SC5-2-u3-X09"}],"explanation":["이마가 더 따뜻해요.","열이 시트로 가요.","이마가 시원해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L03_basic#8','sci',5,2,'u3','L03','g5_2_sci_u3_L03_basic','lesson_basic','SC5-2-u3-C6',2,'ox','auto','얼음을 만지면 손이 차가워지는 것은 얼음의 냉기가 손으로 옮겨 오기 때문이에요.',ARRAY['SC5-2-u3-X12']::text[],false,'{"seq":8,"concept":"SC5-2-u3-C6","difficulty":2,"kind":"ox","stem":"얼음을 만지면 손이 차가워지는 것은 얼음의 냉기가 손으로 옮겨 오기 때문이에요.","answer":"X","reason_options":[{"t":"손의 열이 얼음으로 이동해 손의 온도가 낮아지기 때문에","correct":true},{"t":"차가운 기운은 차가운 쪽에서 따뜻한 쪽으로 가기 때문에","mis":"SC5-2-u3-X12"}],"mis":"SC5-2-u3-X12","explanation":["손이 더 따뜻해요.","손의 열이 나가요.","그래서 차가워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L03_basic#9','sci',5,2,'u3','L03','g5_2_sci_u3_L03_basic','lesson_basic','SC5-2-u3-C5',2,'mc','auto','두 물의 온도 변화를 1분마다 재어 쓴 뒤 한눈에 보려면 무엇으로 나타내면 좋은가요?',ARRAY['SC5-2-u3-X13','SC5-2-u3-X08']::text[],false,'{"seq":9,"concept":"SC5-2-u3-C5","difficulty":2,"kind":"mc","stem":"두 물의 온도 변화를 1분마다 재어 쓴 뒤 한눈에 보려면 무엇으로 나타내면 좋은가요?","options":[{"t":"꺾은선그래프","correct":true},{"t":"그림그래프로 사람 수를 센다","mis":"SC5-2-u3-X13"},{"t":"물의 무게를 적은 표","mis":"SC5-2-u3-X08"},{"t":"물의 색깔을 그린 그림","mis":"SC5-2-u3-X08"}],"explanation":["시간에 따라 변해요.","선으로 이어요.","꺾은선그래프예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L03_basic#10','sci',5,2,'u3','L03','g5_2_sci_u3_L03_basic','lesson_basic','SC5-2-u3-C6',3,'error','auto','갓 삶은 면을 얼음물에 헹구며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u3-X12','SC5-2-u3-X11','SC5-2-u3-X09']::text[],false,'{"seq":10,"concept":"SC5-2-u3-C6","difficulty":3,"kind":"error","stem":"갓 삶은 면을 얼음물에 헹구며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라온 — 「얼음물의 차가움이 면으로 들어가서 면이 식는 거야.」","correct":true,"mis_target":"SC5-2-u3-X12"},{"t":"세아 — 「면의 열이 얼음물로 가서 면이 빨리 식어.」","mis":"SC5-2-u3-X11"},{"t":"규민 — 「얼음물은 면에게 열을 받아 조금 따뜻해져.」","mis":"SC5-2-u3-X09"}],"explanation":["면이 더 뜨거워요.","면의 열이 물로 가요.","라온의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L03_challenge#1','sci',5,2,'u3','L03','g5_2_sci_u3_L03_challenge','lesson_challenge','SC5-2-u3-C6',2,'match','auto','생활 장면과 열이 이동하는 쪽을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u3-C6","difficulty":2,"kind":"match","stem":"생활 장면과 열이 이동하는 쪽을 알맞게 이으세요.","pairs":[{"l":"얼음 위 생선","r":"생선 → 얼음"},{"l":"이마의 냉각 시트","r":"이마 → 냉각 시트"},{"l":"얼음물에 헹군 면","r":"면 → 얼음물"},{"l":"손에 든 아이스크림","r":"손 → 아이스크림"}],"mis":"SC5-2-u3-X11","explanation":["더 따뜻한 쪽을 찾아요.","그쪽에서 열이 나가요.","낮은 쪽으로 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L03_challenge#2','sci',5,2,'u3','L03','g5_2_sci_u3_L03_challenge','lesson_challenge','SC5-2-u3-C5',2,'mc','auto','달걀과 찬물의 온도 변화 그래프에서 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-2-u3-X09','SC5-2-u3-X10']::text[],false,'{"seq":2,"concept":"SC5-2-u3-C5","difficulty":2,"kind":"mc","stem":"달걀과 찬물의 온도 변화 그래프에서 알 수 있는 것은 어느 것인가요?","options":[{"t":"달걀은 낮아지고 찬물은 높아져 34 °C에서 같아진다","correct":true},{"t":"달걀만 낮아지고 찬물은 그대로이다","mis":"SC5-2-u3-X09"},{"t":"찬물이 달걀보다 더 뜨거워진다","mis":"SC5-2-u3-X10"},{"t":"두 온도가 끝까지 만나지 않는다","mis":"SC5-2-u3-X10"}],"explanation":["두 선을 봐요.","하나는 내려가요.","34 °C에서 만나요."],"asset":{"type":"lgraph","xs":["0","1","2","3","4","5","6"],"series":[{"name":"뜨거운 달걀","vals":[60,48,40,36,34,34,34]},{"name":"찬물","vals":[14,22,28,32,34,34,34]}],"step":2,"ymax":64,"ylab":"(°C)","xlab":"(분)","title":"달걀과 찬물의 온도 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L03_challenge#3','sci',5,2,'u3','L03','g5_2_sci_u3_L03_challenge','lesson_challenge','SC5-2-u3-C5',3,'mc','auto','두 물의 온도 변화 그래프에서 따뜻한 물의 온도가 가장 많이 낮아진 때는 언제인가요?',ARRAY['SC5-2-u3-X13']::text[],false,'{"seq":3,"concept":"SC5-2-u3-C5","difficulty":3,"kind":"mc","stem":"두 물의 온도 변화 그래프에서 따뜻한 물의 온도가 가장 많이 낮아진 때는 언제인가요?","options":[{"t":"0분과 1분 사이","correct":true},{"t":"2분과 3분 사이","mis":"SC5-2-u3-X13"},{"t":"4분과 5분 사이","mis":"SC5-2-u3-X13"},{"t":"5분과 6분 사이","mis":"SC5-2-u3-X13"}],"explanation":["처음엔 차이가 커요.","4 °C 낮아졌어요.","0분과 1분 사이예요."],"asset":{"type":"lgraph","xs":["0","1","2","3","4","5","6"],"series":[{"name":"따뜻한 물","vals":[40,36,34,32,30,30,30]},{"name":"차가운 물","vals":[10,18,24,28,30,30,30]}],"step":2,"ymax":44,"ylab":"(°C)","xlab":"(분)","title":"두 물의 온도 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L03_challenge#4','sci',5,2,'u3','L03','g5_2_sci_u3_L03_challenge','lesson_challenge','SC5-2-u3-C5',3,'mc','auto','두 물의 온도 변화 그래프에서 4분 뒤 두 선이 더 이상 변하지 않는 까닭은 어느 것인가요?',ARRAY['SC5-2-u3-X09','SC5-2-u3-X12','SC5-2-u3-X11']::text[],false,'{"seq":4,"concept":"SC5-2-u3-C5","difficulty":3,"kind":"mc","stem":"두 물의 온도 변화 그래프에서 4분 뒤 두 선이 더 이상 변하지 않는 까닭은 어느 것인가요?","options":[{"t":"두 물의 온도가 같아져 더 이상 열이 이동하지 않기 때문이다","correct":true},{"t":"온도계가 고장 났기 때문이다","mis":"SC5-2-u3-X09"},{"t":"차가운 물의 냉기가 모두 빠져나갔기 때문이다","mis":"SC5-2-u3-X12"},{"t":"따뜻한 물이 열을 받기 시작했기 때문이다","mis":"SC5-2-u3-X11"}],"explanation":["두 온도가 같아요.","높고 낮음이 없어요.","이동이 멈춰요."],"asset":{"type":"lgraph","xs":["0","1","2","3","4","5","6"],"series":[{"name":"따뜻한 물","vals":[40,36,34,32,30,30,30]},{"name":"차가운 물","vals":[10,18,24,28,30,30,30]}],"step":2,"ymax":44,"ylab":"(°C)","xlab":"(분)","title":"두 물의 온도 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L03_challenge#5','sci',5,2,'u3','L03','g5_2_sci_u3_L03_challenge','lesson_challenge','SC5-2-u3-C6',3,'ox','auto','냉동실에서 꺼낸 아이스크림을 손에 들고 있으면 녹는 것은 손과 공기에서 아이스크림으로 열이 오기 때문이에요.',ARRAY['SC5-2-u3-X12']::text[],false,'{"seq":5,"concept":"SC5-2-u3-C6","difficulty":3,"kind":"ox","stem":"냉동실에서 꺼낸 아이스크림을 손에 들고 있으면 녹는 것은 손과 공기에서 아이스크림으로 열이 오기 때문이에요.","answer":"O","reason_options":[{"t":"손과 공기가 아이스크림보다 온도가 높기 때문에","correct":true},{"t":"아이스크림의 차가움이 손으로 빠져나가기 때문에","mis":"SC5-2-u3-X12"}],"mis":"SC5-2-u3-X12","explanation":["손과 공기가 더 따뜻해요.","열이 아이스크림으로 가요.","그래서 녹아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L03_challenge#6','sci',5,2,'u3','L03','g5_2_sci_u3_L03_challenge','lesson_challenge','SC5-2-u3-C5',3,'error','auto','두 물 실험 결과를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u3-X10','SC5-2-u3-X09','SC5-2-u3-X13']::text[],false,'{"seq":6,"concept":"SC5-2-u3-C5","difficulty":3,"kind":"error","stem":"두 물 실험 결과를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하율 — 「더 오래 두면 차가웠던 물이 따뜻했던 물보다 뜨거워질 거야.」","correct":true,"mis_target":"SC5-2-u3-X10"},{"t":"서진 — 「따뜻한 물은 내려가고 차가운 물은 올라갔어.」","mis":"SC5-2-u3-X09"},{"t":"유찬 — 「온도 변화는 처음에 크고 점점 작아졌어.」","mis":"SC5-2-u3-X13"}],"explanation":["같아지면 멈춰요.","뒤바뀌지 않아요.","하율의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L03_challenge#7','sci',5,2,'u3','L03','g5_2_sci_u3_L03_challenge','lesson_challenge','SC5-2-u3-C6',3,'mc','auto','뜨거운 국그릇에 차가운 숟가락을 담가 두었어요. 일어나는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X12','SC5-2-u3-X11','SC5-2-u3-X09']::text[],false,'{"seq":7,"concept":"SC5-2-u3-C6","difficulty":3,"kind":"mc","stem":"뜨거운 국그릇에 차가운 숟가락을 담가 두었어요. 일어나는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"국에서 숟가락으로 열이 이동해 숟가락이 따뜻해지고 국은 조금 식는다","correct":true},{"t":"숟가락의 냉기가 국으로 퍼져 국이 식는다","mis":"SC5-2-u3-X12"},{"t":"숟가락에서 국으로 열이 이동한다","mis":"SC5-2-u3-X11"},{"t":"숟가락만 따뜻해지고 국의 온도는 그대로이다","mis":"SC5-2-u3-X09"}],"explanation":["국이 더 뜨거워요.","열이 숟가락으로 가요.","둘 다 변해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L03_challenge#8','sci',5,2,'u3','L03','g5_2_sci_u3_L03_challenge','lesson_challenge','SC5-2-u3-C5',4,'mc','auto','35 °C 물과 15 °C 물을 맞닿게 오래 두었어요. 두 물의 온도가 같아질 때로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X10']::text[],false,'{"seq":8,"concept":"SC5-2-u3-C5","difficulty":4,"kind":"mc","stem":"35 °C 물과 15 °C 물을 맞닿게 오래 두었어요. 두 물의 온도가 같아질 때로 알맞은 것은 어느 것인가요?","options":[{"t":"15 °C보다 높고 35 °C보다 낮은 어느 온도","correct":true},{"t":"35 °C보다 더 높은 온도","mis":"SC5-2-u3-X10"},{"t":"15 °C보다 더 낮은 온도","mis":"SC5-2-u3-X10"},{"t":"두 물은 끝내 같아지지 않는다","mis":"SC5-2-u3-X10"}],"explanation":["뜨거운 물은 내려와요.","찬물은 올라가요.","그 사이에서 만나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L03_challenge#9','sci',5,2,'u3','L03','g5_2_sci_u3_L03_challenge','lesson_challenge','SC5-2-u3-C6',4,'mc','auto','찬물에 넣은 뜨거운 달걀이 식는 까닭을 가장 바르게 설명한 것은 어느 것인가요?',ARRAY['SC5-2-u3-X12','SC5-2-u3-X11','SC5-2-u3-X09']::text[],false,'{"seq":9,"concept":"SC5-2-u3-C6","difficulty":4,"kind":"mc","stem":"찬물에 넣은 뜨거운 달걀이 식는 까닭을 가장 바르게 설명한 것은 어느 것인가요?","options":[{"t":"달걀이 찬물보다 온도가 높아 달걀의 열이 찬물로 이동했기 때문이다","correct":true},{"t":"찬물의 냉기가 달걀 속으로 들어갔기 때문이다","mis":"SC5-2-u3-X12"},{"t":"찬물의 열이 달걀로 이동했기 때문이다","mis":"SC5-2-u3-X11"},{"t":"달걀만 식고 찬물은 그대로이기 때문이다","mis":"SC5-2-u3-X09"}],"explanation":["달걀이 더 뜨거워요.","열이 물로 가요.","그래서 식어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L03_challenge#10','sci',5,2,'u3','L03','g5_2_sci_u3_L03_challenge','lesson_challenge','SC5-2-u3-C6',4,'essay','teacher','「얼음을 쥐면 얼음의 차가움이 손으로 와서 손이 차가워진다.」는 말을 열의 이동으로 바르게 고쳐 쓰고, 얼음은 어떻게 되는지도 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u3-C6","difficulty":4,"kind":"essay","stem":"「얼음을 쥐면 얼음의 차가움이 손으로 와서 손이 차가워진다.」는 말을 열의 이동으로 바르게 고쳐 쓰고, 얼음은 어떻게 되는지도 쓰세요.","answer_guide":{"answer":"예: 손이 얼음보다 온도가 높아 손의 열이 얼음으로 이동하기 때문에 손의 온도가 낮아져 차갑게 느껴진다. 얼음은 열을 받아 온도가 높아지며 녹는다.","scoring_points":["어느 쪽 온도가 높은지 썼는가","열이 손에서 얼음으로 이동한다고 썼는가","얼음이 열을 받아 녹는다고 썼는가"]},"explanation":["손이 더 따뜻해요.","열이 얼음으로 가요.","얼음은 녹아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L04_basic#1','sci',5,2,'u3','L04','g5_2_sci_u3_L04_basic','lesson_basic','SC5-2-u3-C7',1,'mc','auto','긴 구리판 한쪽 끝을 가열하면 붙임딱지 색깔은 어떤 차례로 변하나요?',ARRAY['SC5-2-u3-X14']::text[],false,'{"seq":1,"concept":"SC5-2-u3-C7","difficulty":1,"kind":"mc","stem":"긴 구리판 한쪽 끝을 가열하면 붙임딱지 색깔은 어떤 차례로 변하나요?","options":[{"t":"가열한 곳에서 가까운 곳부터 차례로","correct":true},{"t":"가열한 곳에서 먼 곳부터 차례로","mis":"SC5-2-u3-X14"},{"t":"모든 곳이 한꺼번에","mis":"SC5-2-u3-X14"},{"t":"가운데부터","mis":"SC5-2-u3-X14"}],"explanation":["가열한 곳부터 뜨거워요.","열이 판을 따라가요.","가까운 곳부터예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L04_basic#2','sci',5,2,'u3','L04','g5_2_sci_u3_L04_basic','lesson_basic','SC5-2-u3-C8',1,'sa','auto','온도가 높은 부분에서 낮은 부분으로 고체 물질을 따라 열이 이동하는 방식을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-2-u3-C8","difficulty":1,"kind":"sa","stem":"온도가 높은 부분에서 낮은 부분으로 고체 물질을 따라 열이 이동하는 방식을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["전도"],"explanation":["고체를 따라가요.","두 글자예요.","전도예요."],"mis":"SC5-2-u3-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L04_basic#3','sci',5,2,'u3','L04','g5_2_sci_u3_L04_basic','lesson_basic','SC5-2-u3-C7',1,'ox','auto','ㄷ자 구리판에서 열은 끊어진 틈을 건너뛰지 않고 구리판을 따라 이동해요.',ARRAY['SC5-2-u3-X15']::text[],false,'{"seq":3,"concept":"SC5-2-u3-C7","difficulty":1,"kind":"ox","stem":"ㄷ자 구리판에서 열은 끊어진 틈을 건너뛰지 않고 구리판을 따라 이동해요.","answer":"O","reason_options":[{"t":"열이 고체 물질을 따라 이동하기 때문에","correct":true},{"t":"가까운 틈 건너편으로 바로 건너가기 때문에","mis":"SC5-2-u3-X15"}],"mis":"SC5-2-u3-X15","explanation":["판을 따라가요.","틈은 건너지 않아요.","돌아서 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L04_basic#4','sci',5,2,'u3','L04','g5_2_sci_u3_L04_basic','lesson_basic','SC5-2-u3-C9',1,'mc','auto','프라이팬과 냄비 몸통을 금속으로 만드는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X18']::text[],false,'{"seq":4,"concept":"SC5-2-u3-C9","difficulty":1,"kind":"mc","stem":"프라이팬과 냄비 몸통을 금속으로 만드는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"바닥의 열이 음식까지 빨리 전해지게 하려고","correct":true},{"t":"열이 음식으로 가지 않게 하려고","mis":"SC5-2-u3-X18"},{"t":"프라이팬을 가볍게 하려고","mis":"SC5-2-u3-X18"},{"t":"음식의 색깔을 바꾸려고","mis":"SC5-2-u3-X18"}],"explanation":["금속은 열이 잘 가요.","바닥이 뜨거워져요.","음식이 빨리 익어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L04_basic#5','sci',5,2,'u3','L04','g5_2_sci_u3_L04_basic','lesson_basic','SC5-2-u3-C7',2,'mc','auto','긴 구리판 가열하기에서 붙임딱지 색깔이 가장 늦게 변하는 것은 어느 것인가요?',ARRAY['SC5-2-u3-X14']::text[],false,'{"seq":5,"concept":"SC5-2-u3-C7","difficulty":2,"kind":"mc","stem":"긴 구리판 가열하기에서 붙임딱지 색깔이 가장 늦게 변하는 것은 어느 것인가요?","options":[{"t":"㉣","correct":true},{"t":"㉠","mis":"SC5-2-u3-X14"},{"t":"㉡","mis":"SC5-2-u3-X14"},{"t":"㉢","mis":"SC5-2-u3-X14"}],"explanation":["가열한 곳은 ㉠ 쪽이에요.","㉣이 가장 멀어요.","㉣이 가장 늦어요."],"asset":{"type":"passage","lines":["긴 구리판에 붙임딱지 ㉠~㉣을 한 줄로 붙였다.","㉠은 가열하는 끝에 가장 가깝고, ㉣이 가장 멀다.","구리판 왼쪽 끝 ㉠ 쪽을 촛불로 가열했다."],"title":"긴 구리판 가열하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L04_basic#6','sci',5,2,'u3','L04','g5_2_sci_u3_L04_basic','lesson_basic','SC5-2-u3-C9',2,'mc','auto','뜨거운 국에 금속 숟가락을 담가 두면 숟가락은 어떻게 되나요?',ARRAY['SC5-2-u3-X14','SC5-2-u3-X16']::text[],false,'{"seq":6,"concept":"SC5-2-u3-C9","difficulty":2,"kind":"mc","stem":"뜨거운 국에 금속 숟가락을 담가 두면 숟가락은 어떻게 되나요?","options":[{"t":"국에 담긴 부분부터 손잡이 쪽으로 차례로 뜨거워진다","correct":true},{"t":"손잡이 끝부터 먼저 뜨거워진다","mis":"SC5-2-u3-X14"},{"t":"숟가락 전체가 한꺼번에 뜨거워진다","mis":"SC5-2-u3-X14"},{"t":"숟가락은 뜨거워지지 않는다","mis":"SC5-2-u3-X16"}],"explanation":["국에 닿은 곳부터요.","숟가락을 따라가요.","손잡이까지 와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L04_basic#7','sci',5,2,'u3','L04','g5_2_sci_u3_L04_basic','lesson_basic','SC5-2-u3-C8',2,'ox','auto','금속 프라이팬과 달걀처럼 종류가 다른 고체끼리는 열이 이동하지 않아요.',ARRAY['SC5-2-u3-X16']::text[],false,'{"seq":7,"concept":"SC5-2-u3-C8","difficulty":2,"kind":"ox","stem":"금속 프라이팬과 달걀처럼 종류가 다른 고체끼리는 열이 이동하지 않아요.","answer":"X","reason_options":[{"t":"종류가 달라도 맞닿아 있으면 열이 이동하기 때문에","correct":true},{"t":"같은 종류의 고체끼리만 열이 이동하기 때문에","mis":"SC5-2-u3-X16"}],"mis":"SC5-2-u3-X16","explanation":["프라이팬은 뜨거워요.","달걀과 닿아 있어요.","열이 달걀로 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L04_basic#8','sci',5,2,'u3','L04','g5_2_sci_u3_L04_basic','lesson_basic','SC5-2-u3-C9',2,'mc','auto','냄비 손잡이를 나무나 플라스틱으로 만드는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X18']::text[],false,'{"seq":8,"concept":"SC5-2-u3-C9","difficulty":2,"kind":"mc","stem":"냄비 손잡이를 나무나 플라스틱으로 만드는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"손잡이로 열이 잘 이동하지 않아 손이 데지 않게 하려고","correct":true},{"t":"손잡이도 빨리 뜨거워지게 하려고","mis":"SC5-2-u3-X18"},{"t":"냄비의 열이 음식으로 가지 않게 하려고","mis":"SC5-2-u3-X18"},{"t":"손잡이를 금속보다 더 무겁게 하려고","mis":"SC5-2-u3-X18"}],"explanation":["손으로 잡아요.","열이 잘 안 가야 해요.","손을 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L04_basic#9','sci',5,2,'u3','L04','g5_2_sci_u3_L04_basic','lesson_basic','SC5-2-u3-C8',2,'mc','auto','석쇠에 닿지 않은 고기 윗부분까지 익는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X12','SC5-2-u3-X14','SC5-2-u3-X16']::text[],false,'{"seq":9,"concept":"SC5-2-u3-C8","difficulty":2,"kind":"mc","stem":"석쇠에 닿지 않은 고기 윗부분까지 익는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"석쇠에 닿은 부분의 열이 고기를 따라 윗부분으로 이동하기 때문이다","correct":true},{"t":"고기 윗부분의 냉기가 빠져나가기 때문이다","mis":"SC5-2-u3-X12"},{"t":"고기 윗부분이 가장 먼저 뜨거워지기 때문이다","mis":"SC5-2-u3-X14"},{"t":"고기와 석쇠는 종류가 달라 열이 오지 않기 때문이다","mis":"SC5-2-u3-X16"}],"explanation":["아래가 먼저 뜨거워요.","고기를 따라 올라가요.","전도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L04_basic#10','sci',5,2,'u3','L04','g5_2_sci_u3_L04_basic','lesson_basic','SC5-2-u3-C7',3,'error','auto','ㄷ자 구리판 가열하기를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u3-X15','SC5-2-u3-X14','SC5-2-u3-X11']::text[],false,'{"seq":10,"concept":"SC5-2-u3-C7","difficulty":3,"kind":"error","stem":"ㄷ자 구리판 가열하기를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은솔 — 「위쪽 팔이 뜨거워지면 틈 건너 아래쪽 팔 끝이 바로 뜨거워져.」","correct":true,"mis_target":"SC5-2-u3-X15"},{"t":"다온 — 「세로 기둥을 지나 아래쪽 팔로 차례로 변했어.」","mis":"SC5-2-u3-X14"},{"t":"건우 — 「열은 판을 따라 온도가 낮은 쪽으로 갔어.」","mis":"SC5-2-u3-X11"}],"explanation":["열은 판을 따라가요.","틈을 건너지 않아요.","은솔의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["ㄷ자 구리판의 위쪽 팔 끝을 가열했다.","위쪽 팔 끝과 아래쪽 팔 끝은 틈을 사이에 두고 마주 보고 있다.","붙임딱지는 위쪽 팔 → 세로 기둥 → 아래쪽 팔 차례로 붙어 있다."],"title":"ㄷ자 구리판 가열하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L04_challenge#1','sci',5,2,'u3','L04','g5_2_sci_u3_L04_challenge','lesson_challenge','SC5-2-u3-C9',2,'match','auto','부엌 도구와 쓰는 재료의 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u3-C9","difficulty":2,"kind":"match","stem":"부엌 도구와 쓰는 재료의 까닭을 알맞게 이으세요.","pairs":[{"l":"프라이팬 바닥","r":"열이 잘 가는 금속"},{"l":"냄비 손잡이","r":"열이 잘 안 가는 나무"},{"l":"국 속 금속 숟가락","r":"손잡이까지 뜨거워짐"}],"mis":"SC5-2-u3-X18","explanation":["바닥은 열을 전해요.","손잡이는 막아요.","숟가락은 따라 뜨거워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L04_challenge#2','sci',5,2,'u3','L04','g5_2_sci_u3_L04_challenge','lesson_challenge','SC5-2-u3-C7',2,'mc','auto','ㄷ자 구리판 가열하기에서 붙임딱지가 변하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X15','SC5-2-u3-X14']::text[],false,'{"seq":2,"concept":"SC5-2-u3-C7","difficulty":2,"kind":"mc","stem":"ㄷ자 구리판 가열하기에서 붙임딱지가 변하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"위쪽 팔 → 세로 기둥 → 아래쪽 팔","correct":true},{"t":"위쪽 팔 → 아래쪽 팔 → 세로 기둥","mis":"SC5-2-u3-X15"},{"t":"아래쪽 팔 → 세로 기둥 → 위쪽 팔","mis":"SC5-2-u3-X14"},{"t":"세 곳이 한꺼번에","mis":"SC5-2-u3-X14"}],"explanation":["위쪽 팔을 가열했어요.","판을 따라 돌아요.","아래쪽 팔이 마지막이에요."],"asset":{"type":"passage","lines":["ㄷ자 구리판의 위쪽 팔 끝을 가열했다.","위쪽 팔 끝과 아래쪽 팔 끝은 틈을 사이에 두고 마주 보고 있다.","붙임딱지는 위쪽 팔 → 세로 기둥 → 아래쪽 팔 차례로 붙어 있다."],"title":"ㄷ자 구리판 가열하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L04_challenge#3','sci',5,2,'u3','L04','g5_2_sci_u3_L04_challenge','lesson_challenge','SC5-2-u3-C7',3,'mc','auto','네모난 구리판 한가운데를 가열하면 붙임딱지 색깔은 어떻게 변하나요?',ARRAY['SC5-2-u3-X14']::text[],false,'{"seq":3,"concept":"SC5-2-u3-C7","difficulty":3,"kind":"mc","stem":"네모난 구리판 한가운데를 가열하면 붙임딱지 색깔은 어떻게 변하나요?","options":[{"t":"가운데에서 바깥쪽으로 둥글게 퍼진다","correct":true},{"t":"네 모서리부터 가운데로 모인다","mis":"SC5-2-u3-X14"},{"t":"판 전체가 한꺼번에 변한다","mis":"SC5-2-u3-X14"},{"t":"한쪽 모서리로만 한 줄로 간다","mis":"SC5-2-u3-X14"}],"explanation":["가운데가 가장 가까워요.","사방으로 퍼져요.","바깥으로 둥글게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L04_challenge#4','sci',5,2,'u3','L04','g5_2_sci_u3_L04_challenge','lesson_challenge','SC5-2-u3-C8',3,'mc','auto','프라이팬 가장자리·중간·한가운데에 버터 조각을 놓고 한가운데 아래만 가열했어요. 버터가 녹는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X14']::text[],false,'{"seq":4,"concept":"SC5-2-u3-C8","difficulty":3,"kind":"mc","stem":"프라이팬 가장자리·중간·한가운데에 버터 조각을 놓고 한가운데 아래만 가열했어요. 버터가 녹는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"한가운데 → 중간 → 가장자리","correct":true},{"t":"가장자리 → 중간 → 한가운데","mis":"SC5-2-u3-X14"},{"t":"세 조각이 한꺼번에","mis":"SC5-2-u3-X14"},{"t":"중간 → 한가운데 → 가장자리","mis":"SC5-2-u3-X14"}],"explanation":["불은 한가운데예요.","열이 바깥으로 가요.","가장자리가 마지막이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L04_challenge#5','sci',5,2,'u3','L04','g5_2_sci_u3_L04_challenge','lesson_challenge','SC5-2-u3-C8',3,'ox','auto','추운 날 금속 문손잡이를 잡으면 차갑게 느껴지는 것은 손의 열이 손잡이로 이동하기 때문이에요.',ARRAY['SC5-2-u3-X12']::text[],false,'{"seq":5,"concept":"SC5-2-u3-C8","difficulty":3,"kind":"ox","stem":"추운 날 금속 문손잡이를 잡으면 차갑게 느껴지는 것은 손의 열이 손잡이로 이동하기 때문이에요.","answer":"O","reason_options":[{"t":"손이 손잡이보다 따뜻해 손의 열이 전도로 손잡이에 가기 때문에","correct":true},{"t":"손잡이의 냉기가 손으로 전도되기 때문에","mis":"SC5-2-u3-X12"}],"mis":"SC5-2-u3-X12","explanation":["손이 더 따뜻해요.","열이 손잡이로 가요.","그래서 차가워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L04_challenge#6','sci',5,2,'u3','L04','g5_2_sci_u3_L04_challenge','lesson_challenge','SC5-2-u3-C8',3,'error','auto','전도를 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u3-X17','SC5-2-u3-X16']::text[],false,'{"seq":6,"concept":"SC5-2-u3-C8","difficulty":3,"kind":"error","stem":"전도를 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"나윤 — 「주전자 속 물이 위아래로 돌며 뜨거워지는 것도 전도야.」","correct":true,"mis_target":"SC5-2-u3-X17"},{"t":"지후 — 「전도는 고체 물질을 따라 열이 이동하는 거야.」","mis":"SC5-2-u3-X16"},{"t":"소이 — 「프라이팬에서 달걀로도 전도가 일어나.」","mis":"SC5-2-u3-X16"}],"explanation":["전도는 고체를 따라가요.","물이 도는 것은 달라요.","나윤의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L04_challenge#7','sci',5,2,'u3','L04','g5_2_sci_u3_L04_challenge','lesson_challenge','SC5-2-u3-C9',3,'mc','auto','뜨거운 냄비를 옮길 때 주방 장갑을 끼는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X12','SC5-2-u3-X11','SC5-2-u3-X18']::text[],false,'{"seq":7,"concept":"SC5-2-u3-C9","difficulty":3,"kind":"mc","stem":"뜨거운 냄비를 옮길 때 주방 장갑을 끼는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"냄비의 열이 손으로 전도되는 것을 줄이려고","correct":true},{"t":"냄비의 냉기가 손으로 오는 것을 막으려고","mis":"SC5-2-u3-X12"},{"t":"손의 열을 냄비로 더 보내려고","mis":"SC5-2-u3-X11"},{"t":"냄비가 더 빨리 뜨거워지게 하려고","mis":"SC5-2-u3-X18"}],"explanation":["냄비가 뜨거워요.","손으로 열이 와요.","장갑이 줄여 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L04_challenge#8','sci',5,2,'u3','L04','g5_2_sci_u3_L04_challenge','lesson_challenge','SC5-2-u3-C7',4,'mc','auto','긴 구리판의 ㉡과 ㉢ 사이에 붙임딱지 ㉤을 하나 더 붙였어요. 왼쪽 ㉠ 쪽 끝을 가열할 때 ㉤의 색깔이 변하는 때로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X14']::text[],false,'{"seq":8,"concept":"SC5-2-u3-C7","difficulty":4,"kind":"mc","stem":"긴 구리판의 ㉡과 ㉢ 사이에 붙임딱지 ㉤을 하나 더 붙였어요. 왼쪽 ㉠ 쪽 끝을 가열할 때 ㉤의 색깔이 변하는 때로 알맞은 것은 어느 것인가요?","options":[{"t":"㉡보다 늦고 ㉢보다 빠르다","correct":true},{"t":"㉠보다 먼저 변한다","mis":"SC5-2-u3-X14"},{"t":"㉣과 같은 때에 변한다","mis":"SC5-2-u3-X14"},{"t":"가열하자마자 모두와 함께 변한다","mis":"SC5-2-u3-X14"}],"explanation":["㉤은 ㉡ 다음 자리예요.","가까운 곳부터 변해요.","㉡과 ㉢ 사이예요."],"asset":{"type":"passage","lines":["긴 구리판에 붙임딱지 ㉠~㉣을 한 줄로 붙였다.","㉠은 가열하는 끝에 가장 가깝고, ㉣이 가장 멀다.","구리판 왼쪽 끝 ㉠ 쪽을 촛불로 가열했다."],"title":"긴 구리판 가열하기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L04_challenge#9','sci',5,2,'u3','L04','g5_2_sci_u3_L04_challenge','lesson_challenge','SC5-2-u3-C9',4,'mc','auto','새 냄비를 만들려고 해요. 전도를 생각해 가장 알맞게 설계한 것은 어느 것인가요?',ARRAY['SC5-2-u3-X18','SC5-2-u3-X16']::text[],false,'{"seq":9,"concept":"SC5-2-u3-C9","difficulty":4,"kind":"mc","stem":"새 냄비를 만들려고 해요. 전도를 생각해 가장 알맞게 설계한 것은 어느 것인가요?","options":[{"t":"몸통은 금속, 손잡이는 나무로 만든다","correct":true},{"t":"몸통과 손잡이를 모두 금속으로 만든다","mis":"SC5-2-u3-X18"},{"t":"몸통은 나무, 손잡이는 금속으로 만든다","mis":"SC5-2-u3-X18"},{"t":"몸통과 손잡이를 모두 나무로 만든다","mis":"SC5-2-u3-X16"}],"explanation":["몸통은 열을 전해야 해요.","손잡이는 막아야 해요.","금속과 나무예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L04_challenge#10','sci',5,2,'u3','L04','g5_2_sci_u3_L04_challenge','lesson_challenge','SC5-2-u3-C8',4,'essay','teacher','석쇠 위 고기의 윗부분까지 익는 과정을 「석쇠 → 고기 아랫부분 → 고기 윗부분」 차례로 전도를 넣어 설명하고, 열이 어느 쪽에서 어느 쪽으로 가는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u3-C8","difficulty":4,"kind":"essay","stem":"석쇠 위 고기의 윗부분까지 익는 과정을 「석쇠 → 고기 아랫부분 → 고기 윗부분」 차례로 전도를 넣어 설명하고, 열이 어느 쪽에서 어느 쪽으로 가는지 쓰세요.","answer_guide":{"answer":"예: 불에 달궈진 석쇠의 열이 맞닿은 고기 아랫부분으로 전도되고, 다시 고기를 따라 윗부분으로 전도된다. 열은 온도가 높은 석쇠 쪽에서 온도가 낮은 고기 윗부분 쪽으로 이동한다.","scoring_points":["석쇠에서 고기로 열이 간다고 썼는가","고기를 따라 윗부분으로 간다고 썼는가","높은 쪽에서 낮은 쪽이라고 썼는가"]},"explanation":["석쇠가 뜨거워요.","고기를 따라가요.","높은 쪽에서 낮은 쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L05_basic#1','sci',5,2,'u3','L05','g5_2_sci_u3_L05_basic','lesson_basic','SC5-2-u3-C10',1,'mc','auto','물속 잉크 관찰에서 잉크는 처음에 어느 쪽으로 움직이나요?',ARRAY['SC5-2-u3-X20','SC5-2-u3-X19']::text[],false,'{"seq":1,"concept":"SC5-2-u3-C10","difficulty":1,"kind":"mc","stem":"물속 잉크 관찰에서 잉크는 처음에 어느 쪽으로 움직이나요?","options":[{"t":"위쪽으로","correct":true},{"t":"아래쪽으로","mis":"SC5-2-u3-X20"},{"t":"움직이지 않는다","mis":"SC5-2-u3-X20"},{"t":"통 밖으로","mis":"SC5-2-u3-X19"}],"explanation":["잉크 아래가 뜨거워요.","데워진 물이 올라가요.","위쪽으로 가요."],"asset":{"type":"passage","lines":["① 물이 든 사각 통을 컵 두 개 위에 올렸다.","② 스포이트로 통 바닥 가운데에 잉크를 조금 넣었다.","③ 잉크 바로 아래에 뜨거운 물이 든 컵을 밀어 넣었다.","④ 잉크가 어떻게 움직이는지 살폈다."],"title":"물속 잉크 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L05_basic#2','sci',5,2,'u3','L05','g5_2_sci_u3_L05_basic','lesson_basic','SC5-2-u3-C12',1,'sa','auto','액체나 기체에서 데워진 물질이 위로 올라가고 차가운 물질이 내려오며 열이 이동하는 방식을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-2-u3-C12","difficulty":1,"kind":"sa","stem":"액체나 기체에서 데워진 물질이 위로 올라가고 차가운 물질이 내려오며 열이 이동하는 방식을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["대류"],"explanation":["물질이 움직여요.","두 글자예요.","대류예요."],"mis":"SC5-2-u3-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L05_basic#3','sci',5,2,'u3','L05','g5_2_sci_u3_L05_basic','lesson_basic','SC5-2-u3-C11',1,'mc','auto','아크릴 통과 촛불 실험에서 색깔이 가장 먼저 변하는 붙임딱지는 어느 것인가요?',ARRAY['SC5-2-u3-X21']::text[],false,'{"seq":3,"concept":"SC5-2-u3-C11","difficulty":1,"kind":"mc","stem":"아크릴 통과 촛불 실험에서 색깔이 가장 먼저 변하는 붙임딱지는 어느 것인가요?","options":[{"t":"위에 붙인 붙임딱지","correct":true},{"t":"아래에 붙인 붙임딱지","mis":"SC5-2-u3-X21"},{"t":"가운데에 붙인 붙임딱지","mis":"SC5-2-u3-X21"},{"t":"세 붙임딱지가 한꺼번에","mis":"SC5-2-u3-X21"}],"explanation":["촛불이 공기를 데워요.","데워진 공기는 올라가요.","위부터 변해요."],"asset":{"type":"passage","lines":["아크릴 통 안쪽 벽에 붙임딱지를 위·가운데·아래에 붙였다.","통 바닥 한가운데에 촛불을 두었다.","통 위에는 구멍이 몇 개 뚫려 있다."],"title":"아크릴 통과 촛불"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L05_basic#4','sci',5,2,'u3','L05','g5_2_sci_u3_L05_basic','lesson_basic','SC5-2-u3-C13',1,'ox','auto','방 전체를 빨리 따뜻하게 하려면 난방기를 방 아래쪽에 두는 것이 좋아요.',ARRAY['SC5-2-u3-X20']::text[],false,'{"seq":4,"concept":"SC5-2-u3-C13","difficulty":1,"kind":"ox","stem":"방 전체를 빨리 따뜻하게 하려면 난방기를 방 아래쪽에 두는 것이 좋아요.","answer":"O","reason_options":[{"t":"아래에서 데워진 공기가 위로 올라가며 방 전체가 돌기 때문에","correct":true},{"t":"데워진 공기는 아래로 내려가 바닥에 머물기 때문에","mis":"SC5-2-u3-X20"}],"mis":"SC5-2-u3-X20","explanation":["데워진 공기는 올라가요.","방 공기가 돌아요.","아래쪽이 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L05_basic#5','sci',5,2,'u3','L05','g5_2_sci_u3_L05_basic','lesson_basic','SC5-2-u3-C10',2,'mc','auto','물속 잉크 관찰에서 위로 올라간 잉크는 그다음에 어떻게 되나요?',ARRAY['SC5-2-u3-X22','SC5-2-u3-X20','SC5-2-u3-X19']::text[],false,'{"seq":5,"concept":"SC5-2-u3-C10","difficulty":2,"kind":"mc","stem":"물속 잉크 관찰에서 위로 올라간 잉크는 그다음에 어떻게 되나요?","options":[{"t":"옆으로 퍼지면서 다시 아래로 내려온다","correct":true},{"t":"물 위에서 멈춰 그대로 있다","mis":"SC5-2-u3-X22"},{"t":"통 바닥으로 곧장 떨어진다","mis":"SC5-2-u3-X20"},{"t":"잉크가 사라져 열이 된다","mis":"SC5-2-u3-X19"}],"explanation":["위로 올라갔어요.","옆으로 퍼져요.","다시 내려와요."],"asset":{"type":"passage","lines":["① 물이 든 사각 통을 컵 두 개 위에 올렸다.","② 스포이트로 통 바닥 가운데에 잉크를 조금 넣었다.","③ 잉크 바로 아래에 뜨거운 물이 든 컵을 밀어 넣었다.","④ 잉크가 어떻게 움직이는지 살폈다."],"title":"물속 잉크 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L05_basic#6','sci',5,2,'u3','L05','g5_2_sci_u3_L05_basic','lesson_basic','SC5-2-u3-C10',2,'ox','auto','물속에서 위로 올라가는 잉크의 모습이 바로 열의 모습이에요.',ARRAY['SC5-2-u3-X19']::text[],false,'{"seq":6,"concept":"SC5-2-u3-C10","difficulty":2,"kind":"ox","stem":"물속에서 위로 올라가는 잉크의 모습이 바로 열의 모습이에요.","answer":"X","reason_options":[{"t":"열은 보이지 않고 잉크는 물이 움직이는 모습을 보여 주는 도우미이기 때문에","correct":true},{"t":"열은 잉크처럼 색깔이 있어 눈에 보이기 때문에","mis":"SC5-2-u3-X19"}],"mis":"SC5-2-u3-X19","explanation":["열은 보이지 않아요.","잉크는 물을 따라가요.","도우미예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L05_basic#7','sci',5,2,'u3','L05','g5_2_sci_u3_L05_basic','lesson_basic','SC5-2-u3-C12',2,'mc','auto','대류를 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-2-u3-X22','SC5-2-u3-X17','SC5-2-u3-X20']::text[],false,'{"seq":7,"concept":"SC5-2-u3-C12","difficulty":2,"kind":"mc","stem":"대류를 바르게 말한 것은 어느 것인가요?","options":[{"t":"데워진 물질이 직접 움직이며 열을 옮긴다","correct":true},{"t":"물질은 가만히 있고 열만 이동한다","mis":"SC5-2-u3-X22"},{"t":"고체 물질을 따라 열이 이동한다","mis":"SC5-2-u3-X17"},{"t":"데워진 물질이 아래로 내려간다","mis":"SC5-2-u3-X20"}],"explanation":["물질이 움직여요.","위로 올라가요.","열을 옮겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L05_basic#8','sci',5,2,'u3','L05','g5_2_sci_u3_L05_basic','lesson_basic','SC5-2-u3-C11',2,'mc','auto','찜기 바닥에만 물이 끓는데 맨 위 칸 만두까지 익는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X20','SC5-2-u3-X12','SC5-2-u3-X14']::text[],false,'{"seq":8,"concept":"SC5-2-u3-C11","difficulty":2,"kind":"mc","stem":"찜기 바닥에만 물이 끓는데 맨 위 칸 만두까지 익는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"데워진 뜨거운 김이 위로 올라가기 때문이다","correct":true},{"t":"뜨거운 김이 아래로 내려가기 때문이다","mis":"SC5-2-u3-X20"},{"t":"만두의 냉기가 바닥으로 빠지기 때문이다","mis":"SC5-2-u3-X12"},{"t":"맨 위 칸이 바닥보다 먼저 데워지기 때문이다","mis":"SC5-2-u3-X14"}],"explanation":["바닥에서 김이 나요.","김은 올라가요.","위 칸도 익어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L05_basic#9','sci',5,2,'u3','L05','g5_2_sci_u3_L05_basic','lesson_basic','SC5-2-u3-C13',2,'mc','auto','주전자 바닥만 가열해도 물 전체가 뜨거워지는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X18','SC5-2-u3-X22','SC5-2-u3-X20']::text[],false,'{"seq":9,"concept":"SC5-2-u3-C13","difficulty":2,"kind":"mc","stem":"주전자 바닥만 가열해도 물 전체가 뜨거워지는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"바닥에서 데워진 물이 올라가고 위의 물이 내려오기를 되풀이하기 때문이다","correct":true},{"t":"바닥의 열이 주전자 손잡이로만 가기 때문이다","mis":"SC5-2-u3-X18"},{"t":"물은 움직이지 않고 열만 위로 가기 때문이다","mis":"SC5-2-u3-X22"},{"t":"위의 차가운 물이 먼저 뜨거워지기 때문이다","mis":"SC5-2-u3-X20"}],"explanation":["바닥 물이 데워져요.","올라가고 내려와요.","전체가 데워져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L05_basic#10','sci',5,2,'u3','L05','g5_2_sci_u3_L05_basic','lesson_basic','SC5-2-u3-C13',3,'error','auto','방 안 냉방기와 난방기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u3-X23','SC5-2-u3-X20']::text[],false,'{"seq":10,"concept":"SC5-2-u3-C13","difficulty":3,"kind":"error","stem":"방 안 냉방기와 난방기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태린 — 「냉방기는 바닥 가까이 낮게 달아야 방 전체가 시원해.」","correct":true,"mis_target":"SC5-2-u3-X23"},{"t":"준호 — 「난방기는 아래쪽에 두면 따뜻한 공기가 올라가.」","mis":"SC5-2-u3-X20"},{"t":"예서 — 「냉방기에서 나온 차가운 공기는 아래로 내려와.」","mis":"SC5-2-u3-X20"}],"explanation":["차가운 공기는 내려와요.","냉방기는 높은 곳이에요.","태린의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L05_challenge#1','sci',5,2,'u3','L05','g5_2_sci_u3_L05_challenge','lesson_challenge','SC5-2-u3-C12',2,'match','auto','장면과 알맞은 움직임을 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u3-C12","difficulty":2,"kind":"match","stem":"장면과 알맞은 움직임을 이으세요.","pairs":[{"l":"바닥을 데운 물","r":"위로 올라감"},{"l":"위쪽의 차가운 물","r":"아래로 내려옴"},{"l":"촛불에 데워진 공기","r":"통 위쪽으로 감"},{"l":"냉방기의 차가운 공기","r":"방 아래로 내려옴"}],"mis":"SC5-2-u3-X20","explanation":["데워지면 올라가요.","차가우면 내려와요.","돌며 데워져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L05_challenge#2','sci',5,2,'u3','L05','g5_2_sci_u3_L05_challenge','lesson_challenge','SC5-2-u3-C10',2,'mc','auto','물속 잉크 관찰에서 뜨거운 물 컵을 잉크 바로 아래에 넣는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X19','SC5-2-u3-X22','SC5-2-u3-X20']::text[],false,'{"seq":2,"concept":"SC5-2-u3-C10","difficulty":2,"kind":"mc","stem":"물속 잉크 관찰에서 뜨거운 물 컵을 잉크 바로 아래에 넣는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"잉크가 있는 곳의 물을 데워 물의 움직임을 보려고","correct":true},{"t":"잉크를 더 진하게 하려고","mis":"SC5-2-u3-X19"},{"t":"물의 움직임을 멈추게 하려고","mis":"SC5-2-u3-X22"},{"t":"잉크를 바닥에 붙여 두려고","mis":"SC5-2-u3-X20"}],"explanation":["아래에서 데워요.","데워진 물이 움직여요.","잉크가 보여 줘요."],"asset":{"type":"passage","lines":["① 물이 든 사각 통을 컵 두 개 위에 올렸다.","② 스포이트로 통 바닥 가운데에 잉크를 조금 넣었다.","③ 잉크 바로 아래에 뜨거운 물이 든 컵을 밀어 넣었다.","④ 잉크가 어떻게 움직이는지 살폈다."],"title":"물속 잉크 관찰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L05_challenge#3','sci',5,2,'u3','L05','g5_2_sci_u3_L05_challenge','lesson_challenge','SC5-2-u3-C11',3,'mc','auto','아크릴 통과 촛불에서 위쪽 붙임딱지가 먼저 변하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X21','SC5-2-u3-X20','SC5-2-u3-X22']::text[],false,'{"seq":3,"concept":"SC5-2-u3-C11","difficulty":3,"kind":"mc","stem":"아크릴 통과 촛불에서 위쪽 붙임딱지가 먼저 변하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"촛불에 데워진 공기가 위로 올라가 위쪽부터 따뜻해지기 때문이다","correct":true},{"t":"위쪽 붙임딱지가 촛불에 가장 가깝기 때문이다","mis":"SC5-2-u3-X21"},{"t":"데워진 공기는 아래로 내려가기 때문이다","mis":"SC5-2-u3-X20"},{"t":"공기는 움직이지 않고 열만 올라가기 때문이다","mis":"SC5-2-u3-X22"}],"explanation":["공기가 데워져요.","데워진 공기는 올라가요.","위쪽이 먼저예요."],"asset":{"type":"passage","lines":["아크릴 통 안쪽 벽에 붙임딱지를 위·가운데·아래에 붙였다.","통 바닥 한가운데에 촛불을 두었다.","통 위에는 구멍이 몇 개 뚫려 있다."],"title":"아크릴 통과 촛불"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L05_challenge#4','sci',5,2,'u3','L05','g5_2_sci_u3_L05_challenge','lesson_challenge','SC5-2-u3-C13',3,'mc','auto','냉방기를 방의 높은 곳에 다는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X20','SC5-2-u3-X17','SC5-2-u3-X23']::text[],false,'{"seq":4,"concept":"SC5-2-u3-C13","difficulty":3,"kind":"mc","stem":"냉방기를 방의 높은 곳에 다는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"차가운 공기가 아래로 내려오고 데워진 공기가 올라가며 방 공기가 돌기 때문이다","correct":true},{"t":"차가운 공기는 위로 올라가 천장에 머물기 때문이다","mis":"SC5-2-u3-X20"},{"t":"높은 곳에서 냉기가 방바닥으로 전도되기 때문이다","mis":"SC5-2-u3-X17"},{"t":"높은 곳이 방에서 가장 따뜻해 냉기가 필요하기 때문이다","mis":"SC5-2-u3-X23"}],"explanation":["차가운 공기는 내려와요.","데워진 공기는 올라가요.","방 공기가 돌아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L05_challenge#5','sci',5,2,'u3','L05','g5_2_sci_u3_L05_challenge','lesson_challenge','SC5-2-u3-C12',3,'ox','auto','대류는 고체에서는 일어나지 않고 액체와 기체에서 일어나요.',ARRAY['SC5-2-u3-X17']::text[],false,'{"seq":5,"concept":"SC5-2-u3-C12","difficulty":3,"kind":"ox","stem":"대류는 고체에서는 일어나지 않고 액체와 기체에서 일어나요.","answer":"O","reason_options":[{"t":"대류는 물질이 직접 움직여야 하는데 고체는 흘러 움직이지 않기 때문에","correct":true},{"t":"고체를 따라 열이 이동하는 것이 대류이기 때문에","mis":"SC5-2-u3-X17"}],"mis":"SC5-2-u3-X17","explanation":["물질이 움직여야 해요.","고체는 흐르지 않아요.","액체와 기체예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L05_challenge#6','sci',5,2,'u3','L05','g5_2_sci_u3_L05_challenge','lesson_challenge','SC5-2-u3-C10',3,'error','auto','물속 잉크 관찰을 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u3-X19','SC5-2-u3-X20','SC5-2-u3-X22']::text[],false,'{"seq":6,"concept":"SC5-2-u3-C10","difficulty":3,"kind":"error","stem":"물속 잉크 관찰을 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"한결 — 「잉크가 올라가는 걸 보니 열은 파란색이야.」","correct":true,"mis_target":"SC5-2-u3-X19"},{"t":"채아 — 「데워진 물이 올라가니 잉크도 따라 올라갔어.」","mis":"SC5-2-u3-X20"},{"t":"도윤 — 「물이 위아래로 돌면서 전체가 데워져.」","mis":"SC5-2-u3-X22"}],"explanation":["잉크는 물을 따라가요.","열은 보이지 않아요.","한결의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L05_challenge#7','sci',5,2,'u3','L05','g5_2_sci_u3_L05_challenge','lesson_challenge','SC5-2-u3-C12',3,'mc','auto','어항 속 수조 히터를 바닥 가까이 두는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X20','SC5-2-u3-X17','SC5-2-u3-X22']::text[],false,'{"seq":7,"concept":"SC5-2-u3-C12","difficulty":3,"kind":"mc","stem":"어항 속 수조 히터를 바닥 가까이 두는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"바닥에서 데워진 물이 올라가며 물 전체가 돌아 골고루 따뜻해지기 때문이다","correct":true},{"t":"데워진 물이 바닥에 머물러 물고기를 데우기 때문이다","mis":"SC5-2-u3-X20"},{"t":"히터의 열이 물을 따라 전도로만 가기 때문이다","mis":"SC5-2-u3-X17"},{"t":"물은 움직이지 않아 바닥만 따뜻하면 되기 때문이다","mis":"SC5-2-u3-X22"}],"explanation":["아래에서 데워요.","데워진 물은 올라가요.","물 전체가 돌아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L05_challenge#8','sci',5,2,'u3','L05','g5_2_sci_u3_L05_challenge','lesson_challenge','SC5-2-u3-C10',4,'mc','auto','차가운 물이 든 컵 위에 뜨거운 물을 조심히 부었어요. 두 물의 모습으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X20','SC5-2-u3-X22','SC5-2-u3-X19']::text[],false,'{"seq":8,"concept":"SC5-2-u3-C10","difficulty":4,"kind":"mc","stem":"차가운 물이 든 컵 위에 뜨거운 물을 조심히 부었어요. 두 물의 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"뜨거운 물은 위에, 차가운 물은 아래에 머무는 편이다","correct":true},{"t":"뜨거운 물이 곧장 아래로 내려가 바닥에 깔린다","mis":"SC5-2-u3-X20"},{"t":"두 물이 순식간에 한꺼번에 섞인다","mis":"SC5-2-u3-X22"},{"t":"뜨거운 물이 열이 되어 사라진다","mis":"SC5-2-u3-X19"}],"explanation":["데워진 물은 위로 가려 해요.","차가운 물은 아래예요.","위아래로 나뉘어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L05_challenge#9','sci',5,2,'u3','L05','g5_2_sci_u3_L05_challenge','lesson_challenge','SC5-2-u3-C11',4,'mc','auto','추운 날 거실 아래쪽에 난로를 켰어요. 잠시 뒤 거실에서 가장 먼저 따뜻해지는 곳으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X20','SC5-2-u3-X14']::text[],false,'{"seq":9,"concept":"SC5-2-u3-C11","difficulty":4,"kind":"mc","stem":"추운 날 거실 아래쪽에 난로를 켰어요. 잠시 뒤 거실에서 가장 먼저 따뜻해지는 곳으로 알맞은 것은 어느 것인가요?","options":[{"t":"난로 위쪽 천장 가까운 곳","correct":true},{"t":"난로에서 먼 바닥 구석","mis":"SC5-2-u3-X20"},{"t":"창문 아래 바닥","mis":"SC5-2-u3-X20"},{"t":"거실 전체가 한꺼번에","mis":"SC5-2-u3-X14"}],"explanation":["난로가 공기를 데워요.","데워진 공기는 올라가요.","위쪽이 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L05_challenge#10','sci',5,2,'u3','L05','g5_2_sci_u3_L05_challenge','lesson_challenge','SC5-2-u3-C13',4,'essay','teacher','주전자 바닥만 가열했는데 물 전체가 뜨거워지는 까닭을 물의 움직임(올라감·내려옴)을 넣어 대류로 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u3-C13","difficulty":4,"kind":"essay","stem":"주전자 바닥만 가열했는데 물 전체가 뜨거워지는 까닭을 물의 움직임(올라감·내려옴)을 넣어 대류로 설명하세요.","answer_guide":{"answer":"예: 바닥의 물이 데워지면 위로 올라가고, 위쪽의 차가운 물은 아래로 내려와 다시 데워진다. 이렇게 물이 위아래로 돌기를 되풀이하며 열이 이동해 물 전체가 뜨거워진다. 이를 대류라고 한다.","scoring_points":["데워진 물이 올라간다고 썼는가","차가운 물이 내려온다고 썼는가","돌기를 되풀이해 전체가 데워진다고 썼는가"]},"explanation":["바닥 물이 올라가요.","차가운 물이 내려와요.","돌며 데워져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L06_basic#1','sci',5,2,'u3','L06','g5_2_sci_u3_L06_basic','lesson_basic','SC5-2-u3-C14',1,'mc','auto','검은색 판 두 장 실험에서 잠시 뒤 온도가 더 높은 판은 어느 것인가요?',ARRAY['SC5-2-u3-X24']::text[],false,'{"seq":1,"concept":"SC5-2-u3-C14","difficulty":1,"kind":"mc","stem":"검은색 판 두 장 실험에서 잠시 뒤 온도가 더 높은 판은 어느 것인가요?","options":[{"t":"햇빛에 둔 ㉮","correct":true},{"t":"그늘에 둔 ㉯","mis":"SC5-2-u3-X24"},{"t":"두 판이 같다","mis":"SC5-2-u3-X24"},{"t":"알 수 없다","mis":"SC5-2-u3-X24"}],"explanation":["㉮는 햇빛을 받았어요.","빛이 열을 옮겨요.","㉮가 더 높아요."],"asset":{"type":"passage","lines":["① 그늘에서 검은색 판 ㉮와 ㉯의 온도를 쟀다.","② ㉮는 햇빛이 비치는 곳, ㉯는 그늘에 두었다.","③ 일정한 시간이 지난 뒤 두 판의 온도를 다시 쟀다."],"title":"검은색 판 두 장 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L06_basic#2','sci',5,2,'u3','L06','g5_2_sci_u3_L06_basic','lesson_basic','SC5-2-u3-C15',1,'sa','auto','빛에 의해 열이 이동하는 방식을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC5-2-u3-C15","difficulty":1,"kind":"sa","stem":"빛에 의해 열이 이동하는 방식을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["복사"],"explanation":["빛이 열을 옮겨요.","두 글자예요.","복사예요."],"mis":"SC5-2-u3-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L06_basic#3','sci',5,2,'u3','L06','g5_2_sci_u3_L06_basic','lesson_basic','SC5-2-u3-C15',1,'ox','auto','난로 앞에 있으면 난로에 닿지 않아도 따뜻한 것은 복사로 열이 오기 때문이에요.',ARRAY['SC5-2-u3-X25']::text[],false,'{"seq":3,"concept":"SC5-2-u3-C15","difficulty":1,"kind":"ox","stem":"난로 앞에 있으면 난로에 닿지 않아도 따뜻한 것은 복사로 열이 오기 때문이에요.","answer":"O","reason_options":[{"t":"빛에 의해 열이 이동하기 때문에","correct":true},{"t":"난로의 열은 닿아야만 이동하기 때문에","mis":"SC5-2-u3-X25"}],"mis":"SC5-2-u3-X25","explanation":["난로에 안 닿았어요.","그래도 따뜻해요.","복사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L06_basic#4','sci',5,2,'u3','L06','g5_2_sci_u3_L06_basic','lesson_basic','SC5-2-u3-C14',1,'mc','auto','햇빛이 비치는 운동장에서 나무 그늘로 가면 시원한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X25','SC5-2-u3-X12','SC5-2-u3-X11']::text[],false,'{"seq":4,"concept":"SC5-2-u3-C14","difficulty":1,"kind":"mc","stem":"햇빛이 비치는 운동장에서 나무 그늘로 가면 시원한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나뭇잎이 햇빛을 가려 복사로 오는 열이 줄기 때문이다","correct":true},{"t":"그늘에서는 공기가 전혀 없기 때문이다","mis":"SC5-2-u3-X25"},{"t":"나무가 차가운 기운을 뿜기 때문이다","mis":"SC5-2-u3-X12"},{"t":"그늘 땅의 열이 몸으로 오기 때문이다","mis":"SC5-2-u3-X11"}],"explanation":["그늘은 햇빛을 가려요.","오는 열이 줄어요.","그래서 시원해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L06_basic#5','sci',5,2,'u3','L06','g5_2_sci_u3_L06_basic','lesson_basic','SC5-2-u3-C15',2,'mc','auto','복사로 열이 이동하는 예는 어느 것인가요?',ARRAY['SC5-2-u3-X26']::text[],false,'{"seq":5,"concept":"SC5-2-u3-C15","difficulty":2,"kind":"mc","stem":"복사로 열이 이동하는 예는 어느 것인가요?","options":[{"t":"보온 등 아래가 따뜻하다","correct":true},{"t":"국에 담근 숟가락이 뜨거워진다","mis":"SC5-2-u3-X26"},{"t":"주전자 속 물이 위아래로 돈다","mis":"SC5-2-u3-X26"},{"t":"프라이팬에서 달걀이 익는다","mis":"SC5-2-u3-X26"}],"explanation":["보온 등은 빛을 내요.","닿지 않아도 와요.","복사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L06_basic#6','sci',5,2,'u3','L06','g5_2_sci_u3_L06_basic','lesson_basic','SC5-2-u3-C14',2,'mc','auto','검은색 판 두 장 실험에서 ①처럼 처음 온도를 재는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X24']::text[],false,'{"seq":6,"concept":"SC5-2-u3-C14","difficulty":2,"kind":"mc","stem":"검은색 판 두 장 실험에서 ①처럼 처음 온도를 재는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 판의 처음 온도가 같은지 확인하려고","correct":true},{"t":"판의 색깔을 바꾸려고","mis":"SC5-2-u3-X24"},{"t":"그늘 판을 먼저 데우려고","mis":"SC5-2-u3-X24"},{"t":"판의 무게를 알려고","mis":"SC5-2-u3-X24"}],"explanation":["처음이 같아야 해요.","그래야 견줄 수 있어요.","처음 온도를 재요."],"asset":{"type":"passage","lines":["① 그늘에서 검은색 판 ㉮와 ㉯의 온도를 쟀다.","② ㉮는 햇빛이 비치는 곳, ㉯는 그늘에 두었다.","③ 일정한 시간이 지난 뒤 두 판의 온도를 다시 쟀다."],"title":"검은색 판 두 장 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L06_basic#7','sci',5,2,'u3','L06','g5_2_sci_u3_L06_basic','lesson_basic','SC5-2-u3-C15',2,'ox','auto','열은 물질이 닿거나 움직여야만 이동할 수 있어요.',ARRAY['SC5-2-u3-X25']::text[],false,'{"seq":7,"concept":"SC5-2-u3-C15","difficulty":2,"kind":"ox","stem":"열은 물질이 닿거나 움직여야만 이동할 수 있어요.","answer":"X","reason_options":[{"t":"복사는 물질이 닿지 않아도 빛에 의해 열이 이동하기 때문에","correct":true},{"t":"해의 열도 공기를 따라 전도로만 오기 때문에","mis":"SC5-2-u3-X25"}],"mis":"SC5-2-u3-X25","explanation":["해는 아주 멀어요.","닿지 않았어요.","빛으로 열이 와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L06_basic#8','sci',5,2,'u3','L06','g5_2_sci_u3_L06_basic','lesson_basic','SC5-2-u3-C15',2,'mc','auto','해와 닿아 있지 않은 판의 온도가 햇빛을 받아 높아진 것을 보고 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-2-u3-X25','SC5-2-u3-X24']::text[],false,'{"seq":8,"concept":"SC5-2-u3-C15","difficulty":2,"kind":"mc","stem":"해와 닿아 있지 않은 판의 온도가 햇빛을 받아 높아진 것을 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"빛에 의해서도 열이 이동할 수 있다","correct":true},{"t":"열은 닿아야만 이동한다","mis":"SC5-2-u3-X25"},{"t":"판이 스스로 열을 만든다","mis":"SC5-2-u3-X24"},{"t":"그늘에서만 열이 이동한다","mis":"SC5-2-u3-X24"}],"explanation":["판은 해와 떨어져 있어요.","그래도 높아졌어요.","빛이 열을 옮겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L06_basic#9','sci',5,2,'u3','L06','g5_2_sci_u3_L06_basic','lesson_basic','SC5-2-u3-C14',2,'mc','auto','검은색 판 두 장 실험에서 두 판을 다르게 한 것은 어느 것인가요?',ARRAY['SC5-2-u3-X24']::text[],false,'{"seq":9,"concept":"SC5-2-u3-C14","difficulty":2,"kind":"mc","stem":"검은색 판 두 장 실험에서 두 판을 다르게 한 것은 어느 것인가요?","options":[{"t":"놓아둔 곳(햇빛과 그늘)","correct":true},{"t":"판의 색깔","mis":"SC5-2-u3-X24"},{"t":"판의 크기","mis":"SC5-2-u3-X24"},{"t":"온도를 재는 시간","mis":"SC5-2-u3-X24"}],"explanation":["색·크기는 같아요.","시간도 같아요.","놓는 곳만 달라요."],"asset":{"type":"passage","lines":["① 그늘에서 검은색 판 ㉮와 ㉯의 온도를 쟀다.","② ㉮는 햇빛이 비치는 곳, ㉯는 그늘에 두었다.","③ 일정한 시간이 지난 뒤 두 판의 온도를 다시 쟀다."],"title":"검은색 판 두 장 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L06_basic#10','sci',5,2,'u3','L06','g5_2_sci_u3_L06_basic','lesson_basic','SC5-2-u3-C15',3,'error','auto','복사를 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u3-X25','SC5-2-u3-X26','SC5-2-u3-X28']::text[],false,'{"seq":10,"concept":"SC5-2-u3-C15","difficulty":3,"kind":"error","stem":"복사를 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"이현 — 「해의 열은 공기를 따라 차례로 전해져서 지구까지 와.」","correct":true,"mis_target":"SC5-2-u3-X25"},{"t":"가윤 — 「모닥불 앞에서 얼굴이 뜨거운 것도 복사야.」","mis":"SC5-2-u3-X26"},{"t":"승우 — 「복사는 빛에 의해 열이 이동하는 거야.」","mis":"SC5-2-u3-X28"}],"explanation":["해와 지구 사이는 아주 멀어요.","빛으로 열이 와요.","이현의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L06_challenge#1','sci',5,2,'u3','L06','g5_2_sci_u3_L06_challenge','lesson_challenge','SC5-2-u3-C15',2,'match','auto','장면과 알맞은 열의 이동을 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u3-C15","difficulty":2,"kind":"match","stem":"장면과 알맞은 열의 이동을 이으세요.","pairs":[{"l":"난로 앞에서 손 쬐기","r":"빛에 의한 열의 이동"},{"l":"국 속 숟가락 손잡이가 뜨거워짐","r":"고체를 따라 이동"},{"l":"주전자 속 물이 돎","r":"물질이 움직이며 이동"}],"mis":"SC5-2-u3-X26","explanation":["난로는 빛이에요.","숟가락은 고체예요.","물은 움직여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L06_challenge#2','sci',5,2,'u3','L06','g5_2_sci_u3_L06_challenge','lesson_challenge','SC5-2-u3-C14',2,'mc','auto','검은색 판 두 장 실험의 결과를 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-2-u3-X12','SC5-2-u3-X24','SC5-2-u3-X25']::text[],false,'{"seq":2,"concept":"SC5-2-u3-C14","difficulty":2,"kind":"mc","stem":"검은색 판 두 장 실험의 결과를 바르게 말한 것은 어느 것인가요?","options":[{"t":"햇빛을 받은 판은 빛에 의해 열이 이동해 온도가 높아졌다","correct":true},{"t":"그늘 판은 냉기를 받아 온도가 높아졌다","mis":"SC5-2-u3-X12"},{"t":"두 판의 온도는 끝까지 같았다","mis":"SC5-2-u3-X24"},{"t":"햇빛 판은 해와 닿아 온도가 높아졌다","mis":"SC5-2-u3-X25"}],"explanation":["햇빛 판이 높아졌어요.","해와는 닿지 않았어요.","빛이 열을 옮겼어요."],"asset":{"type":"passage","lines":["① 그늘에서 검은색 판 ㉮와 ㉯의 온도를 쟀다.","② ㉮는 햇빛이 비치는 곳, ㉯는 그늘에 두었다.","③ 일정한 시간이 지난 뒤 두 판의 온도를 다시 쟀다."],"title":"검은색 판 두 장 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L06_challenge#3','sci',5,2,'u3','L06','g5_2_sci_u3_L06_challenge','lesson_challenge','SC5-2-u3-C15',3,'mc','auto','모닥불 앞에 서면 얼굴은 뜨겁고 등은 차가워요. 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X12','SC5-2-u3-X26','SC5-2-u3-X28']::text[],false,'{"seq":3,"concept":"SC5-2-u3-C15","difficulty":3,"kind":"mc","stem":"모닥불 앞에 서면 얼굴은 뜨겁고 등은 차가워요. 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"모닥불을 향한 얼굴 쪽만 빛을 받아 복사로 열이 오기 때문이다","correct":true},{"t":"등 쪽 공기가 냉기를 보내기 때문이다","mis":"SC5-2-u3-X12"},{"t":"얼굴이 모닥불에 닿아 전도되기 때문이다","mis":"SC5-2-u3-X26"},{"t":"복사는 사람 몸 앞쪽으로만 가기 때문이다","mis":"SC5-2-u3-X28"}],"explanation":["얼굴은 불을 향해요.","빛을 받는 쪽만이에요.","복사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L06_challenge#4','sci',5,2,'u3','L06','g5_2_sci_u3_L06_challenge','lesson_challenge','SC5-2-u3-C14',3,'mc','auto','검은색 판과 흰색 판을 햇빛에 두고 온도를 견주려고 해요. 같게 해야 할 것이 아닌 것은 어느 것인가요?',ARRAY['SC5-2-u3-X24']::text[],false,'{"seq":4,"concept":"SC5-2-u3-C14","difficulty":3,"kind":"mc","stem":"검은색 판과 흰색 판을 햇빛에 두고 온도를 견주려고 해요. 같게 해야 할 것이 아닌 것은 어느 것인가요?","options":[{"t":"판의 색깔","correct":true},{"t":"판을 놓는 곳","mis":"SC5-2-u3-X24"},{"t":"햇빛에 두는 시간","mis":"SC5-2-u3-X24"},{"t":"판의 크기","mis":"SC5-2-u3-X24"}],"explanation":["색깔을 알아보려 해요.","색깔만 달라요.","나머지는 같게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L06_challenge#5','sci',5,2,'u3','L06','g5_2_sci_u3_L06_challenge','lesson_challenge','SC5-2-u3-C15',3,'ox','auto','보온 등 아래에 둔 병아리가 따뜻한 것은 보온 등에서 나온 빛에 의해 열이 오기 때문이에요.',ARRAY['SC5-2-u3-X26']::text[],false,'{"seq":5,"concept":"SC5-2-u3-C15","difficulty":3,"kind":"ox","stem":"보온 등 아래에 둔 병아리가 따뜻한 것은 보온 등에서 나온 빛에 의해 열이 오기 때문이에요.","answer":"O","reason_options":[{"t":"보온 등과 닿지 않아도 빛에 의해 열이 이동하기 때문에","correct":true},{"t":"보온 등의 열이 병아리 깃털을 따라 전도되기 때문에","mis":"SC5-2-u3-X26"}],"mis":"SC5-2-u3-X26","explanation":["보온 등은 위에 있어요.","닿지 않았어요.","복사로 따뜻해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L06_challenge#6','sci',5,2,'u3','L06','g5_2_sci_u3_L06_challenge','lesson_challenge','SC5-2-u3-C14',3,'error','auto','검은색 판 실험을 계획하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u3-X24','SC5-2-u3-X04']::text[],false,'{"seq":6,"concept":"SC5-2-u3-C14","difficulty":3,"kind":"error","stem":"검은색 판 실험을 계획하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"로아 — 「햇빛 판은 오래 두고 그늘 판은 조금만 두자.」","correct":true,"mis_target":"SC5-2-u3-X24"},{"t":"시아 — 「처음에 두 판의 온도를 같은 방법으로 재자.」","mis":"SC5-2-u3-X24"},{"t":"지민 — 「다시 잴 때도 같은 온도계로 재자.」","mis":"SC5-2-u3-X04"}],"explanation":["시간도 같아야 해요.","하나만 달라야 해요.","로아의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L06_challenge#7','sci',5,2,'u3','L06','g5_2_sci_u3_L06_challenge','lesson_challenge','SC5-2-u3-C15',3,'mc','auto','해의 열이 아주 먼 지구까지 올 수 있는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X28','SC5-2-u3-X25','SC5-2-u3-X12']::text[],false,'{"seq":7,"concept":"SC5-2-u3-C15","difficulty":3,"kind":"mc","stem":"해의 열이 아주 먼 지구까지 올 수 있는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"빛에 의해 열이 이동하는 복사는 물질이 없어도 일어나기 때문이다","correct":true},{"t":"해와 지구 사이가 공기로 꽉 차 대류가 일어나기 때문이다","mis":"SC5-2-u3-X28"},{"t":"해와 지구가 맞닿아 전도가 일어나기 때문이다","mis":"SC5-2-u3-X25"},{"t":"지구의 냉기가 해로 가기 때문이다","mis":"SC5-2-u3-X12"}],"explanation":["해는 아주 멀어요.","빛이 열을 옮겨요.","복사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L06_challenge#8','sci',5,2,'u3','L06','g5_2_sci_u3_L06_challenge','lesson_challenge','SC5-2-u3-C14',4,'mc','auto','여름날 그늘막 아래가 햇빛 아래보다 시원한 까닭을 가장 바르게 설명한 것은 어느 것인가요?',ARRAY['SC5-2-u3-X12','SC5-2-u3-X25','SC5-2-u3-X24']::text[],false,'{"seq":8,"concept":"SC5-2-u3-C14","difficulty":4,"kind":"mc","stem":"여름날 그늘막 아래가 햇빛 아래보다 시원한 까닭을 가장 바르게 설명한 것은 어느 것인가요?","options":[{"t":"그늘막이 햇빛을 가려 복사로 오는 열이 줄어들기 때문이다","correct":true},{"t":"그늘막이 차가운 기운을 아래로 내려보내기 때문이다","mis":"SC5-2-u3-X12"},{"t":"그늘막 아래에는 공기가 없어 열이 못 오기 때문이다","mis":"SC5-2-u3-X25"},{"t":"그늘막이 스스로 시원한 바람을 만들기 때문이다","mis":"SC5-2-u3-X24"}],"explanation":["그늘막은 햇빛을 가려요.","오는 열이 줄어요.","그래서 시원해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L06_challenge#9','sci',5,2,'u3','L06','g5_2_sci_u3_L06_challenge','lesson_challenge','SC5-2-u3-C15',4,'mc','auto','모닥불 앞에서 몸 전체를 고르게 따뜻하게 하는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X26','SC5-2-u3-X27','SC5-2-u3-X24']::text[],false,'{"seq":9,"concept":"SC5-2-u3-C15","difficulty":4,"kind":"mc","stem":"모닥불 앞에서 몸 전체를 고르게 따뜻하게 하는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"몸을 돌려 가며 여러 쪽이 모닥불 빛을 받게 한다","correct":true},{"t":"등을 모닥불에 닿게 기댄다","mis":"SC5-2-u3-X26"},{"t":"얼굴만 계속 불 쪽으로 둔다","mis":"SC5-2-u3-X27"},{"t":"불 뒤쪽 그늘에 선다","mis":"SC5-2-u3-X24"}],"explanation":["빛을 받는 쪽만 따뜻해요.","돌려 가며 쬐어요.","골고루 따뜻해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L06_challenge#10','sci',5,2,'u3','L06','g5_2_sci_u3_L06_challenge','lesson_challenge','SC5-2-u3-C14',4,'essay','teacher','검은색 판과 흰색 판 가운데 햇빛을 받으면 어느 판의 온도가 더 높아질지 확인하는 실험을 계획하세요. 다르게 할 것, 같게 할 것, 재는 방법을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u3-C14","difficulty":4,"kind":"essay","stem":"검은색 판과 흰색 판 가운데 햇빛을 받으면 어느 판의 온도가 더 높아질지 확인하는 실험을 계획하세요. 다르게 할 것, 같게 할 것, 재는 방법을 쓰세요.","answer_guide":{"answer":"예: 다르게 할 것은 판의 색깔이다. 판의 크기·처음 온도·놓는 곳·햇빛에 두는 시간은 같게 한다. 처음 온도를 적외선 온도계로 재고, 같은 시간이 지난 뒤 같은 방법으로 다시 재어 견준다.","scoring_points":["다르게 할 것을 하나만 썼는가","같게 할 것을 썼는가","같은 방법으로 처음과 나중 온도를 잰다고 썼는가"]},"explanation":["색깔만 달라요.","나머지는 같게 해요.","같은 방법으로 재요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L07_basic#1','sci',5,2,'u3','L07','g5_2_sci_u3_L07_basic','lesson_basic','SC5-2-u3-C16',1,'mc','auto','전기 주전자 속 물 전체가 뜨거워지는 방식은 어느 것인가요?',ARRAY['SC5-2-u3-X17','SC5-2-u3-X26','SC5-2-u3-X28']::text[],false,'{"seq":1,"concept":"SC5-2-u3-C16","difficulty":1,"kind":"mc","stem":"전기 주전자 속 물 전체가 뜨거워지는 방식은 어느 것인가요?","options":[{"t":"대류","correct":true},{"t":"전도","mis":"SC5-2-u3-X17"},{"t":"복사","mis":"SC5-2-u3-X26"},{"t":"증발","mis":"SC5-2-u3-X28"}],"explanation":["물이 데워져 올라가요.","물이 돌아요.","대류예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L07_basic#2','sci',5,2,'u3','L07','g5_2_sci_u3_L07_basic','lesson_basic','SC5-2-u3-C16',1,'mc','auto','프라이팬에서 달걀이 익는 방식은 어느 것인가요?',ARRAY['SC5-2-u3-X17','SC5-2-u3-X26','SC5-2-u3-X28']::text[],false,'{"seq":2,"concept":"SC5-2-u3-C16","difficulty":1,"kind":"mc","stem":"프라이팬에서 달걀이 익는 방식은 어느 것인가요?","options":[{"t":"전도","correct":true},{"t":"대류","mis":"SC5-2-u3-X17"},{"t":"복사","mis":"SC5-2-u3-X26"},{"t":"응결","mis":"SC5-2-u3-X28"}],"explanation":["프라이팬은 고체예요.","달걀과 닿아 있어요.","전도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L07_basic#3','sci',5,2,'u3','L07','g5_2_sci_u3_L07_basic','lesson_basic','SC5-2-u3-C16',1,'ox','auto','열이 이동하는 방식에는 전도·대류·복사가 있어요.',ARRAY['SC5-2-u3-X27']::text[],false,'{"seq":3,"concept":"SC5-2-u3-C16","difficulty":1,"kind":"ox","stem":"열이 이동하는 방식에는 전도·대류·복사가 있어요.","answer":"O","reason_options":[{"t":"고체를 따라, 물질이 움직이며, 빛에 의해 열이 이동하기 때문에","correct":true},{"t":"열은 한 가지 방식으로만 이동하기 때문에","mis":"SC5-2-u3-X27"}],"mis":"SC5-2-u3-X27","explanation":["세 가지가 있어요.","전도·대류예요.","그리고 복사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L07_basic#4','sci',5,2,'u3','L07','g5_2_sci_u3_L07_basic','lesson_basic','SC5-2-u3-C16',1,'sa','auto','그림 속 열의 이동 장면 다에서 열 전구 아래가 따뜻한 것은 어떤 방식으로 열이 이동하기 때문인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-2-u3-C16","difficulty":1,"kind":"sa","stem":"그림 속 열의 이동 장면 다에서 열 전구 아래가 따뜻한 것은 어떤 방식으로 열이 이동하기 때문인가요? 두 글자로 쓰세요.","answer":["복사"],"explanation":["열 전구는 빛을 내요.","닿지 않아도 와요.","복사예요."],"asset":{"type":"passage","lines":["가 — 프라이팬에 달걀을 부쳐 익힌다.","나 — 전기 주전자로 물을 끓인다.","다 — 열 전구 아래에서 몸을 녹인다.","라 — 돌 화덕 안에서 석쇠 위 생선을 굽는다."],"title":"그림 속 열의 이동 장면"},"mis":"SC5-2-u3-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L07_basic#5','sci',5,2,'u3','L07','g5_2_sci_u3_L07_basic','lesson_basic','SC5-2-u3-C16',2,'mc','auto','세 가지 열의 이동 방식을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X28']::text[],false,'{"seq":5,"concept":"SC5-2-u3-C16","difficulty":2,"kind":"mc","stem":"세 가지 열의 이동 방식을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"대류 — 액체나 기체가 직접 움직이며 이동","correct":true},{"t":"복사 — 물질이 꼭 닿아야 이동","mis":"SC5-2-u3-X28"},{"t":"전도 — 액체나 기체가 움직이며 이동","mis":"SC5-2-u3-X28"},{"t":"대류 — 빛에 의해 이동","mis":"SC5-2-u3-X28"}],"explanation":["대류는 물질이 움직여요.","액체와 기체예요.","바르게 짝지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L07_basic#6','sci',5,2,'u3','L07','g5_2_sci_u3_L07_basic','lesson_basic','SC5-2-u3-C16',2,'mc','auto','그림 속 열의 이동 장면에서 전도·대류·복사가 함께 일어나는 장면은 어느 것인가요?',ARRAY['SC5-2-u3-X27']::text[],false,'{"seq":6,"concept":"SC5-2-u3-C16","difficulty":2,"kind":"mc","stem":"그림 속 열의 이동 장면에서 전도·대류·복사가 함께 일어나는 장면은 어느 것인가요?","options":[{"t":"라","correct":true},{"t":"가","mis":"SC5-2-u3-X27"},{"t":"나","mis":"SC5-2-u3-X27"},{"t":"다","mis":"SC5-2-u3-X27"}],"explanation":["화덕은 석쇠가 있어요.","공기와 벽도 뜨거워요.","라예요."],"asset":{"type":"passage","lines":["가 — 프라이팬에 달걀을 부쳐 익힌다.","나 — 전기 주전자로 물을 끓인다.","다 — 열 전구 아래에서 몸을 녹인다.","라 — 돌 화덕 안에서 석쇠 위 생선을 굽는다."],"title":"그림 속 열의 이동 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L07_basic#7','sci',5,2,'u3','L07','g5_2_sci_u3_L07_basic','lesson_basic','SC5-2-u3-C16',2,'ox','auto','한 가지 상황에서는 열이 한 가지 방식으로만 이동해요.',ARRAY['SC5-2-u3-X27']::text[],false,'{"seq":7,"concept":"SC5-2-u3-C16","difficulty":2,"kind":"ox","stem":"한 가지 상황에서는 열이 한 가지 방식으로만 이동해요.","answer":"X","reason_options":[{"t":"화덕처럼 전도·대류·복사가 함께 일어날 수 있기 때문에","correct":true},{"t":"방식마다 일어나는 상황이 따로 정해져 있기 때문에","mis":"SC5-2-u3-X27"}],"mis":"SC5-2-u3-X27","explanation":["화덕을 떠올려요.","여러 방식이 있어요.","함께 일어나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L07_basic#8','sci',5,2,'u3','L07','g5_2_sci_u3_L07_basic','lesson_basic','SC5-2-u3-C16',2,'mc','auto','추운 날 난로 앞에서 손을 쬘 때 난로에서 손까지 열이 오는 주된 방식은 어느 것인가요?',ARRAY['SC5-2-u3-X26','SC5-2-u3-X28']::text[],false,'{"seq":8,"concept":"SC5-2-u3-C16","difficulty":2,"kind":"mc","stem":"추운 날 난로 앞에서 손을 쬘 때 난로에서 손까지 열이 오는 주된 방식은 어느 것인가요?","options":[{"t":"복사","correct":true},{"t":"전도","mis":"SC5-2-u3-X26"},{"t":"대류","mis":"SC5-2-u3-X26"},{"t":"응결","mis":"SC5-2-u3-X28"}],"explanation":["난로에 안 닿아요.","빛으로 와요.","복사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L07_basic#9','sci',5,2,'u3','L07','g5_2_sci_u3_L07_basic','lesson_basic','SC5-2-u3-C16',2,'mc','auto','돌 화덕 안 석쇠 위 생선이 익을 때 석쇠에서 생선으로 열이 가는 방식은 어느 것인가요?',ARRAY['SC5-2-u3-X26','SC5-2-u3-X17','SC5-2-u3-X25']::text[],false,'{"seq":9,"concept":"SC5-2-u3-C16","difficulty":2,"kind":"mc","stem":"돌 화덕 안 석쇠 위 생선이 익을 때 석쇠에서 생선으로 열이 가는 방식은 어느 것인가요?","options":[{"t":"전도","correct":true},{"t":"복사","mis":"SC5-2-u3-X26"},{"t":"대류","mis":"SC5-2-u3-X17"},{"t":"열이 이동하지 않는다","mis":"SC5-2-u3-X25"}],"explanation":["석쇠와 생선이 닿아요.","고체를 따라가요.","전도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L07_basic#10','sci',5,2,'u3','L07','g5_2_sci_u3_L07_basic','lesson_basic','SC5-2-u3-C16',3,'error','auto','세 방식을 견주며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u3-X28','SC5-2-u3-X17','SC5-2-u3-X22']::text[],false,'{"seq":10,"concept":"SC5-2-u3-C16","difficulty":3,"kind":"error","stem":"세 방식을 견주며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하은 — 「복사도 물질이 맞닿아 있어야만 열이 이동해.」","correct":true,"mis_target":"SC5-2-u3-X28"},{"t":"도겸 — 「전도는 고체 물질을 따라 열이 이동해.」","mis":"SC5-2-u3-X17"},{"t":"시윤 — 「대류는 물질이 직접 움직이며 열을 옮겨.」","mis":"SC5-2-u3-X22"}],"explanation":["복사는 빛으로 와요.","닿지 않아도 돼요.","하은의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L07_challenge#1','sci',5,2,'u3','L07','g5_2_sci_u3_L07_challenge','lesson_challenge','SC5-2-u3-C16',2,'match','auto','요리 방법과 주로 이용하는 열의 이동 방식을 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u3-C16","difficulty":2,"kind":"match","stem":"요리 방법과 주로 이용하는 열의 이동 방식을 이으세요.","pairs":[{"l":"프라이팬 볶음","r":"전도"},{"l":"찜과 국","r":"대류"},{"l":"숯불 바비큐","r":"복사"}],"mis":"SC5-2-u3-X28","explanation":["프라이팬은 고체예요.","찜은 김과 물이에요.","숯불은 빛이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L07_challenge#2','sci',5,2,'u3','L07','g5_2_sci_u3_L07_challenge','lesson_challenge','SC5-2-u3-C16',2,'mc','auto','겨울 모닥불 장면에서 복사가 일어나는 곳은 어느 것인가요?',ARRAY['SC5-2-u3-X26']::text[],false,'{"seq":2,"concept":"SC5-2-u3-C16","difficulty":2,"kind":"mc","stem":"겨울 모닥불 장면에서 복사가 일어나는 곳은 어느 것인가요?","options":[{"t":"불에서 떨어져 둘러앉은 친구들의 손","correct":true},{"t":"불에 닿은 냄비 바닥","mis":"SC5-2-u3-X26"},{"t":"위아래로 도는 냄비 속 물","mis":"SC5-2-u3-X26"},{"t":"냄비 바닥에서 손잡이 쪽","mis":"SC5-2-u3-X26"}],"explanation":["친구들은 불에 안 닿아요.","빛을 받아요.","복사예요."],"asset":{"type":"passage","lines":["모닥불 위에 냄비를 걸어 물을 끓였다.","냄비 바닥은 불에 닿아 있고, 냄비 속 물은 위아래로 돌았다.","친구들은 불에서 조금 떨어져 둘러앉아 손을 쬐었다."],"title":"겨울 모닥불 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L07_challenge#3','sci',5,2,'u3','L07','g5_2_sci_u3_L07_challenge','lesson_challenge','SC5-2-u3-C16',3,'mc','auto','라면을 끓일 때 냄비 바닥과 냄비 속 물에서 일어나는 열의 이동을 차례로 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-2-u3-X17','SC5-2-u3-X27']::text[],false,'{"seq":3,"concept":"SC5-2-u3-C16","difficulty":3,"kind":"mc","stem":"라면을 끓일 때 냄비 바닥과 냄비 속 물에서 일어나는 열의 이동을 차례로 바르게 말한 것은 어느 것인가요?","options":[{"t":"전도 — 대류","correct":true},{"t":"대류 — 전도","mis":"SC5-2-u3-X17"},{"t":"복사 — 복사","mis":"SC5-2-u3-X27"},{"t":"전도 — 전도","mis":"SC5-2-u3-X17"}],"explanation":["냄비 바닥은 고체예요.","물은 액체예요.","전도와 대류예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L07_challenge#4','sci',5,2,'u3','L07','g5_2_sci_u3_L07_challenge','lesson_challenge','SC5-2-u3-C16',3,'mc','auto','오븐 안에서 빵이 익을 때를 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-2-u3-X27','SC5-2-u3-X25']::text[],false,'{"seq":4,"concept":"SC5-2-u3-C16","difficulty":3,"kind":"mc","stem":"오븐 안에서 빵이 익을 때를 바르게 말한 것은 어느 것인가요?","options":[{"t":"뜨거운 판·데워진 공기·뜨거운 벽에서 세 방식이 함께 빵을 익힌다","correct":true},{"t":"오븐 안 공기의 대류 한 가지로만 익힌다","mis":"SC5-2-u3-X27"},{"t":"빵이 판에 닿아 있으니 전도 한 가지로만 익힌다","mis":"SC5-2-u3-X27"},{"t":"오븐 안에서는 열이 이동하지 않는다","mis":"SC5-2-u3-X25"}],"explanation":["판은 전도예요.","공기는 대류예요.","벽은 복사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L07_challenge#5','sci',5,2,'u3','L07','g5_2_sci_u3_L07_challenge','lesson_challenge','SC5-2-u3-C16',3,'ox','auto','겨울에 금속 손잡이를 잡으면 차갑게 느껴지는 것은 전도와 이어져요.',ARRAY['SC5-2-u3-X12']::text[],false,'{"seq":5,"concept":"SC5-2-u3-C16","difficulty":3,"kind":"ox","stem":"겨울에 금속 손잡이를 잡으면 차갑게 느껴지는 것은 전도와 이어져요.","answer":"O","reason_options":[{"t":"손의 열이 맞닿은 손잡이로 고체를 따라 이동하기 때문에","correct":true},{"t":"손잡이의 냉기가 빛에 의해 손으로 오기 때문에","mis":"SC5-2-u3-X12"}],"mis":"SC5-2-u3-X12","explanation":["손과 손잡이가 닿아요.","열이 손잡이로 가요.","전도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L07_challenge#6','sci',5,2,'u3','L07','g5_2_sci_u3_L07_challenge','lesson_challenge','SC5-2-u3-C16',3,'error','auto','겨울 모닥불 장면을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u3-X26','SC5-2-u3-X17','SC5-2-u3-X28']::text[],false,'{"seq":6,"concept":"SC5-2-u3-C16","difficulty":3,"kind":"error","stem":"겨울 모닥불 장면을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"이안 — 「냄비 속 물이 위아래로 도는 건 복사야.」","correct":true,"mis_target":"SC5-2-u3-X26"},{"t":"윤아 — 「냄비 바닥의 열은 냄비를 따라 전도돼.」","mis":"SC5-2-u3-X17"},{"t":"리아 — 「둘러앉아 손이 따뜻한 건 복사야.」","mis":"SC5-2-u3-X28"}],"explanation":["물이 움직여요.","그건 대류예요.","이안의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["모닥불 위에 냄비를 걸어 물을 끓였다.","냄비 바닥은 불에 닿아 있고, 냄비 속 물은 위아래로 돌았다.","친구들은 불에서 조금 떨어져 둘러앉아 손을 쬐었다."],"title":"겨울 모닥불 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L07_challenge#7','sci',5,2,'u3','L07','g5_2_sci_u3_L07_challenge','lesson_challenge','SC5-2-u3-C16',3,'mc','auto','목욕탕 온탕에서 물 위쪽이 아래쪽보다 더 뜨겁게 느껴질 때가 있어요. 이와 같은 방식으로 일어나는 일은 어느 것인가요?',ARRAY['SC5-2-u3-X17','SC5-2-u3-X26']::text[],false,'{"seq":7,"concept":"SC5-2-u3-C16","difficulty":3,"kind":"mc","stem":"목욕탕 온탕에서 물 위쪽이 아래쪽보다 더 뜨겁게 느껴질 때가 있어요. 이와 같은 방식으로 일어나는 일은 어느 것인가요?","options":[{"t":"찜기 맨 위 칸까지 뜨거운 김이 올라간다","correct":true},{"t":"금속 숟가락 손잡이가 뜨거워진다","mis":"SC5-2-u3-X17"},{"t":"양지바른 곳의 돌이 따뜻해진다","mis":"SC5-2-u3-X26"},{"t":"프라이팬 가장자리가 늦게 뜨거워진다","mis":"SC5-2-u3-X17"}],"explanation":["데워진 물이 올라가요.","대류예요.","김도 올라가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L07_challenge#8','sci',5,2,'u3','L07','g5_2_sci_u3_L07_challenge','lesson_challenge','SC5-2-u3-C16',4,'mc','auto','겨울 모닥불 장면에서 전도·대류·복사를 하나씩 바르게 찾은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X28','SC5-2-u3-X27','SC5-2-u3-X26']::text[],false,'{"seq":8,"concept":"SC5-2-u3-C16","difficulty":4,"kind":"mc","stem":"겨울 모닥불 장면에서 전도·대류·복사를 하나씩 바르게 찾은 것은 어느 것인가요?","options":[{"t":"냄비 바닥 — 전도, 냄비 속 물 — 대류, 둘러앉은 손 — 복사","correct":true},{"t":"냄비 바닥 — 복사, 냄비 속 물 — 전도, 둘러앉은 손 — 대류","mis":"SC5-2-u3-X28"},{"t":"냄비 바닥 — 대류, 냄비 속 물 — 대류, 둘러앉은 손 — 대류","mis":"SC5-2-u3-X27"},{"t":"냄비 바닥 — 전도, 냄비 속 물 — 복사, 둘러앉은 손 — 전도","mis":"SC5-2-u3-X26"}],"explanation":["바닥은 고체예요.","물은 움직여요.","손은 빛을 받아요."],"asset":{"type":"passage","lines":["모닥불 위에 냄비를 걸어 물을 끓였다.","냄비 바닥은 불에 닿아 있고, 냄비 속 물은 위아래로 돌았다.","친구들은 불에서 조금 떨어져 둘러앉아 손을 쬐었다."],"title":"겨울 모닥불 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L07_challenge#9','sci',5,2,'u3','L07','g5_2_sci_u3_L07_challenge','lesson_challenge','SC5-2-u3-C16',4,'mc','auto','우주처럼 공기가 거의 없는 곳에서도 일어날 수 있는 열의 이동 방식은 어느 것인가요?',ARRAY['SC5-2-u3-X28','SC5-2-u3-X25']::text[],false,'{"seq":9,"concept":"SC5-2-u3-C16","difficulty":4,"kind":"mc","stem":"우주처럼 공기가 거의 없는 곳에서도 일어날 수 있는 열의 이동 방식은 어느 것인가요?","options":[{"t":"복사","correct":true},{"t":"대류","mis":"SC5-2-u3-X28"},{"t":"전도와 대류 둘 다","mis":"SC5-2-u3-X25"},{"t":"어떤 방식도 일어나지 않는다","mis":"SC5-2-u3-X25"}],"explanation":["대류는 물질이 움직여야 해요.","빛은 물질이 없어도 가요.","복사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L07_challenge#10','sci',5,2,'u3','L07','g5_2_sci_u3_L07_challenge','lesson_challenge','SC5-2-u3-C16',4,'essay','teacher','내가 겪은 열과 관련된 일을 하나 골라 쓰고, 그 일이 전도·대류·복사 가운데 무엇과 이어지는지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u3-C16","difficulty":4,"kind":"essay","stem":"내가 겪은 열과 관련된 일을 하나 골라 쓰고, 그 일이 전도·대류·복사 가운데 무엇과 이어지는지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 겨울 아침 햇볕이 드는 창가에 앉으면 등이 따뜻했다. 창가에 닿지 않았는데도 햇빛에 의해 열이 왔으므로 복사와 이어진다.","scoring_points":["겪은 일을 구체적으로 썼는가","알맞은 열의 이동 방식을 골랐는가","고체·물질의 움직임·빛 가운데 무엇 때문인지 까닭을 썼는가"]},"explanation":["겪은 일을 떠올려요.","방식을 골라요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L08_basic#1','sci',5,2,'u3','L08','g5_2_sci_u3_L08_basic','lesson_basic','SC5-2-u3-C17',1,'sa','auto','열의 이동을 막는 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u3-C17","difficulty":1,"kind":"sa","stem":"열의 이동을 막는 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["단열"],"explanation":["열이 오가지 못하게 해요.","두 글자예요.","단열이에요."],"mis":"SC5-2-u3-X30"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L08_basic#2','sci',5,2,'u3','L08','g5_2_sci_u3_L08_basic','lesson_basic','SC5-2-u3-C17',1,'ox','auto','보온병에 차가운 물을 담으면 오랫동안 차갑게 마실 수 있어요.',ARRAY['SC5-2-u3-X29']::text[],false,'{"seq":2,"concept":"SC5-2-u3-C17","difficulty":1,"kind":"ox","stem":"보온병에 차가운 물을 담으면 오랫동안 차갑게 마실 수 있어요.","answer":"O","reason_options":[{"t":"보온병은 열의 이동을 막아 차가운 것도 차갑게 지키기 때문에","correct":true},{"t":"보온병은 따뜻한 것만 지킬 수 있기 때문에","mis":"SC5-2-u3-X29"}],"mis":"SC5-2-u3-X29","explanation":["보온병은 열을 막아요.","바깥 열이 못 들어와요.","차갑게 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L08_basic#3','sci',5,2,'u3','L08','g5_2_sci_u3_L08_basic','lesson_basic','SC5-2-u3-C18',1,'mc','auto','여름에 양산은 주로 어떤 방식으로 열이 이동하는 것을 막나요?',ARRAY['SC5-2-u3-X31','SC5-2-u3-X28']::text[],false,'{"seq":3,"concept":"SC5-2-u3-C18","difficulty":1,"kind":"mc","stem":"여름에 양산은 주로 어떤 방식으로 열이 이동하는 것을 막나요?","options":[{"t":"복사","correct":true},{"t":"전도","mis":"SC5-2-u3-X31"},{"t":"대류","mis":"SC5-2-u3-X31"},{"t":"응결","mis":"SC5-2-u3-X28"}],"explanation":["양산은 햇빛을 가려요.","빛으로 오는 열이에요.","복사를 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L08_basic#4','sci',5,2,'u3','L08','g5_2_sci_u3_L08_basic','lesson_basic','SC5-2-u3-C18',1,'mc','auto','단열을 이용하는 물건은 어느 것인가요?',ARRAY['SC5-2-u3-X30']::text[],false,'{"seq":4,"concept":"SC5-2-u3-C18","difficulty":1,"kind":"mc","stem":"단열을 이용하는 물건은 어느 것인가요?","options":[{"t":"아이스박스","correct":true},{"t":"금속 프라이팬","mis":"SC5-2-u3-X30"},{"t":"금속 숟가락","mis":"SC5-2-u3-X30"},{"t":"전기 주전자 바닥","mis":"SC5-2-u3-X30"}],"explanation":["아이스박스는 열을 막아요.","안을 차갑게 지켜요.","단열이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L08_basic#5','sci',5,2,'u3','L08','g5_2_sci_u3_L08_basic','lesson_basic','SC5-2-u3-C18',2,'mc','auto','주방 장갑이 막는 열의 이동 방식은 어느 것인가요?',ARRAY['SC5-2-u3-X31','SC5-2-u3-X28']::text[],false,'{"seq":5,"concept":"SC5-2-u3-C18","difficulty":2,"kind":"mc","stem":"주방 장갑이 막는 열의 이동 방식은 어느 것인가요?","options":[{"t":"전도","correct":true},{"t":"복사","mis":"SC5-2-u3-X31"},{"t":"대류","mis":"SC5-2-u3-X31"},{"t":"증발","mis":"SC5-2-u3-X28"}],"explanation":["뜨거운 냄비를 잡아요.","닿은 손으로 열이 와요.","전도를 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L08_basic#6','sci',5,2,'u3','L08','g5_2_sci_u3_L08_basic','lesson_basic','SC5-2-u3-C18',2,'mc','auto','열의 이동을 막는 물건에서 대류를 막는 것은 어느 것인가요?',ARRAY['SC5-2-u3-X31']::text[],false,'{"seq":6,"concept":"SC5-2-u3-C18","difficulty":2,"kind":"mc","stem":"열의 이동을 막는 물건에서 대류를 막는 것은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"SC5-2-u3-X31"},{"t":"㉰","mis":"SC5-2-u3-X31"},{"t":"㉱","mis":"SC5-2-u3-X31"}],"explanation":["창문을 닫았어요.","공기 흐름을 막아요.","㉯예요."],"asset":{"type":"passage","lines":["㉮ 주방 장갑","㉯ 닫은 창문","㉰ 양산","㉱ 나무 냄비 받침"],"title":"열의 이동을 막는 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L08_basic#7','sci',5,2,'u3','L08','g5_2_sci_u3_L08_basic','lesson_basic','SC5-2-u3-C17',2,'ox','auto','추운 날 창문을 닫으면 교실의 열이 밖으로 덜 빠져나가요.',ARRAY['SC5-2-u3-X32']::text[],false,'{"seq":7,"concept":"SC5-2-u3-C17","difficulty":2,"kind":"ox","stem":"추운 날 창문을 닫으면 교실의 열이 밖으로 덜 빠져나가요.","answer":"O","reason_options":[{"t":"창문이 공기의 흐름을 막아 열의 이동을 줄이기 때문에","correct":true},{"t":"창문을 닫으면 교실이 스스로 열을 만들기 때문에","mis":"SC5-2-u3-X32"}],"mis":"SC5-2-u3-X32","explanation":["창문을 열면 공기가 오가요.","닫으면 막혀요.","열이 덜 나가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L08_basic#8','sci',5,2,'u3','L08','g5_2_sci_u3_L08_basic','lesson_basic','SC5-2-u3-C17',2,'mc','auto','단열에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-2-u3-X30','SC5-2-u3-X29','SC5-2-u3-X32']::text[],false,'{"seq":8,"concept":"SC5-2-u3-C17","difficulty":2,"kind":"mc","stem":"단열에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"열의 이동을 막아 따뜻한 것은 따뜻하게, 차가운 것은 차갑게 지킨다","correct":true},{"t":"열이 더 빨리 이동하게 돕는다","mis":"SC5-2-u3-X30"},{"t":"따뜻한 것만 따뜻하게 지킨다","mis":"SC5-2-u3-X29"},{"t":"물체를 스스로 차갑게 만든다","mis":"SC5-2-u3-X32"}],"explanation":["단열은 막는 거예요.","처음 온도를 지켜요.","양쪽 다 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L08_basic#9','sci',5,2,'u3','L08','g5_2_sci_u3_L08_basic','lesson_basic','SC5-2-u3-C18',2,'mc','auto','집의 벽과 지붕 안에 열의 이동을 막는 재료를 넣으면 좋은 점은 어느 것인가요?',ARRAY['SC5-2-u3-X12','SC5-2-u3-X30','SC5-2-u3-X32']::text[],false,'{"seq":9,"concept":"SC5-2-u3-C18","difficulty":2,"kind":"mc","stem":"집의 벽과 지붕 안에 열의 이동을 막는 재료를 넣으면 좋은 점은 어느 것인가요?","options":[{"t":"겨울에는 안의 열이 덜 빠져나가 난방 에너지를 아낀다","correct":true},{"t":"겨울에 바깥 냉기가 더 잘 들어온다","mis":"SC5-2-u3-X12"},{"t":"집 안의 열이 더 빨리 빠져나간다","mis":"SC5-2-u3-X30"},{"t":"벽이 스스로 열을 만들어 낸다","mis":"SC5-2-u3-X32"}],"explanation":["벽이 열을 막아요.","안의 열을 지켜요.","에너지를 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L08_basic#10','sci',5,2,'u3','L08','g5_2_sci_u3_L08_basic','lesson_basic','SC5-2-u3-C18',3,'error','auto','단열 사례를 조사하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u3-X31','SC5-2-u3-X29','SC5-2-u3-X30']::text[],false,'{"seq":10,"concept":"SC5-2-u3-C18","difficulty":3,"kind":"error","stem":"단열 사례를 조사하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「양산은 손잡이를 따라 오는 전도를 막으려고 써.」","correct":true,"mis_target":"SC5-2-u3-X31"},{"t":"태윤 — 「겹쳐 입은 옷은 몸의 열이 빠져나가는 걸 막아.」","mis":"SC5-2-u3-X29"},{"t":"나은 — 「나무 냄비 받침은 식탁으로 가는 전도를 막아.」","mis":"SC5-2-u3-X30"}],"explanation":["양산은 햇빛을 가려요.","복사를 막아요.","수아의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L08_challenge#1','sci',5,2,'u3','L08','g5_2_sci_u3_L08_challenge','lesson_challenge','SC5-2-u3-C18',2,'match','auto','열의 이동을 막는 물건과 주로 막는 방식을 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u3-C18","difficulty":2,"kind":"match","stem":"열의 이동을 막는 물건과 주로 막는 방식을 이으세요.","pairs":[{"l":"주방 장갑","r":"전도"},{"l":"닫은 창문","r":"대류"},{"l":"양산","r":"복사"}],"mis":"SC5-2-u3-X31","explanation":["장갑은 닿는 열이에요.","창문은 공기 흐름이에요.","양산은 햇빛이에요."],"asset":{"type":"passage","lines":["㉮ 주방 장갑","㉯ 닫은 창문","㉰ 양산","㉱ 나무 냄비 받침"],"title":"열의 이동을 막는 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L08_challenge#2','sci',5,2,'u3','L08','g5_2_sci_u3_L08_challenge','lesson_challenge','SC5-2-u3-C18',2,'mc','auto','냄비 받침을 나무나 실리콘으로 만드는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X12','SC5-2-u3-X30','SC5-2-u3-X31']::text[],false,'{"seq":2,"concept":"SC5-2-u3-C18","difficulty":2,"kind":"mc","stem":"냄비 받침을 나무나 실리콘으로 만드는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"냄비의 열이 식탁으로 전도되는 것을 막으려고","correct":true},{"t":"냄비의 냉기가 식탁으로 가는 것을 막으려고","mis":"SC5-2-u3-X12"},{"t":"냄비의 열을 식탁으로 더 잘 보내려고","mis":"SC5-2-u3-X30"},{"t":"햇빛의 복사를 막으려고","mis":"SC5-2-u3-X31"}],"explanation":["냄비는 뜨거워요.","식탁과 닿아요.","받침이 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L08_challenge#3','sci',5,2,'u3','L08','g5_2_sci_u3_L08_challenge','lesson_challenge','SC5-2-u3-C17',3,'mc','auto','얼음을 신문지에 싼 것과 그냥 둔 것을 같은 곳에 두었어요. 더 오래 남는 얼음과 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X32','SC5-2-u3-X12','SC5-2-u3-X30']::text[],false,'{"seq":3,"concept":"SC5-2-u3-C17","difficulty":3,"kind":"mc","stem":"얼음을 신문지에 싼 것과 그냥 둔 것을 같은 곳에 두었어요. 더 오래 남는 얼음과 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"신문지에 싼 얼음 — 주변 공기의 열이 얼음으로 오는 것을 막아서","correct":true},{"t":"신문지에 싼 얼음 — 신문지가 얼음을 더 차갑게 만들어서","mis":"SC5-2-u3-X32"},{"t":"그냥 둔 얼음 — 공기가 얼음을 차갑게 지켜서","mis":"SC5-2-u3-X12"},{"t":"둘 다 같다 — 신문지는 아무 일도 하지 않아서","mis":"SC5-2-u3-X30"}],"explanation":["열은 공기에서 와요.","신문지가 막아요.","싼 얼음이 오래가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L08_challenge#4','sci',5,2,'u3','L08','g5_2_sci_u3_L08_challenge','lesson_challenge','SC5-2-u3-C18',3,'mc','auto','이중창이 열의 이동을 줄이는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X32','SC5-2-u3-X33','SC5-2-u3-X30']::text[],false,'{"seq":4,"concept":"SC5-2-u3-C18","difficulty":3,"kind":"mc","stem":"이중창이 열의 이동을 줄이는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 유리 사이의 공기층이 열의 이동을 줄여서","correct":true},{"t":"유리 두 장이 스스로 열을 만들어서","mis":"SC5-2-u3-X32"},{"t":"유리 사이로 바람이 잘 통해서","mis":"SC5-2-u3-X33"},{"t":"유리가 많을수록 햇빛이 더 들어와서","mis":"SC5-2-u3-X30"}],"explanation":["유리 사이에 공기가 있어요.","공기층이 막아요.","열이 덜 오가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L08_challenge#5','sci',5,2,'u3','L08','g5_2_sci_u3_L08_challenge','lesson_challenge','SC5-2-u3-C18',3,'ox','auto','소방관의 보호 장비도 단열을 이용해 불의 열이 몸으로 오는 것을 막아요.',ARRAY['SC5-2-u3-X32']::text[],false,'{"seq":5,"concept":"SC5-2-u3-C18","difficulty":3,"kind":"ox","stem":"소방관의 보호 장비도 단열을 이용해 불의 열이 몸으로 오는 것을 막아요.","answer":"O","reason_options":[{"t":"보호 장비가 바깥의 뜨거운 열이 몸으로 이동하는 것을 막기 때문에","correct":true},{"t":"보호 장비가 몸을 스스로 차갑게 만들기 때문에","mis":"SC5-2-u3-X32"}],"mis":"SC5-2-u3-X32","explanation":["불은 아주 뜨거워요.","장비가 열을 막아요.","단열이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L08_challenge#6','sci',5,2,'u3','L08','g5_2_sci_u3_L08_challenge','lesson_challenge','SC5-2-u3-C17',3,'error','auto','보온병을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u3-X29','SC5-2-u3-X30']::text[],false,'{"seq":6,"concept":"SC5-2-u3-C17","difficulty":3,"kind":"error","stem":"보온병을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"다인 — 「보온병은 이름처럼 따뜻한 음료에만 쓸 수 있어.」","correct":true,"mis_target":"SC5-2-u3-X29"},{"t":"하준 — 「보온병에 얼음을 넣으면 오래 안 녹아.」","mis":"SC5-2-u3-X30"},{"t":"유진 — 「보온병은 열의 이동을 막는 병이야.」","mis":"SC5-2-u3-X30"}],"explanation":["보온병은 열을 막아요.","차가운 것도 지켜요.","다인의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L08_challenge#7','sci',5,2,'u3','L08','g5_2_sci_u3_L08_challenge','lesson_challenge','SC5-2-u3-C18',3,'mc','auto','아이스박스가 안의 음료를 차갑게 지키는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X12','SC5-2-u3-X30','SC5-2-u3-X32']::text[],false,'{"seq":7,"concept":"SC5-2-u3-C18","difficulty":3,"kind":"mc","stem":"아이스박스가 안의 음료를 차갑게 지키는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"바깥의 열이 안으로 들어오지 못하게 막는다","correct":true},{"t":"안의 냉기가 바깥으로 나가지 못하게 가둔다","mis":"SC5-2-u3-X12"},{"t":"바깥의 열을 안으로 더 끌어온다","mis":"SC5-2-u3-X30"},{"t":"상자가 스스로 차가운 기운을 만든다","mis":"SC5-2-u3-X32"}],"explanation":["바깥이 더 따뜻해요.","열이 들어오려 해요.","그것을 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L08_challenge#8','sci',5,2,'u3','L08','g5_2_sci_u3_L08_challenge','lesson_challenge','SC5-2-u3-C18',4,'mc','auto','우리 교실 창틀 틈으로 찬바람이 들어와요. 열의 이동을 줄이는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X33','SC5-2-u3-X30','SC5-2-u3-X12']::text[],false,'{"seq":8,"concept":"SC5-2-u3-C18","difficulty":4,"kind":"mc","stem":"우리 교실 창틀 틈으로 찬바람이 들어와요. 열의 이동을 줄이는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"문풍지를 붙여 틈으로 드나드는 공기의 흐름을 막는다","correct":true},{"t":"창문을 활짝 열어 공기를 더 통하게 한다","mis":"SC5-2-u3-X33"},{"t":"창틀에 금속판을 붙여 열을 잘 전하게 한다","mis":"SC5-2-u3-X30"},{"t":"창문 앞에 얼음을 두어 냉기를 막는다","mis":"SC5-2-u3-X12"}],"explanation":["틈으로 공기가 드나들어요.","대류를 막아야 해요.","문풍지를 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L08_challenge#9','sci',5,2,'u3','L08','g5_2_sci_u3_L08_challenge','lesson_challenge','SC5-2-u3-C17',4,'mc','auto','단열이 잘된 집이 환경에 도움이 되는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X30','SC5-2-u3-X32','SC5-2-u3-X12']::text[],false,'{"seq":9,"concept":"SC5-2-u3-C17","difficulty":4,"kind":"mc","stem":"단열이 잘된 집이 환경에 도움이 되는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"열이 덜 새어 난방과 냉방에 쓰는 에너지를 아낄 수 있기 때문이다","correct":true},{"t":"집 안 온도가 빨리 바뀌어 기계를 자주 켜기 때문이다","mis":"SC5-2-u3-X30"},{"t":"벽이 스스로 열을 만들어 난방이 필요 없기 때문이다","mis":"SC5-2-u3-X32"},{"t":"바깥 냉기가 집 안으로 들어오기 때문이다","mis":"SC5-2-u3-X12"}],"explanation":["열이 덜 새요.","기계를 덜 써요.","에너지를 아껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L08_challenge#10','sci',5,2,'u3','L08','g5_2_sci_u3_L08_challenge','lesson_challenge','SC5-2-u3-C18',4,'essay','teacher','일상생활에서 단열을 이용하는 물건 두 가지를 골라 쓰고, 각각 어떤 열의 이동(전도·대류·복사)을 막는지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u3-C18","difficulty":4,"kind":"essay","stem":"일상생활에서 단열을 이용하는 물건 두 가지를 골라 쓰고, 각각 어떤 열의 이동(전도·대류·복사)을 막는지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 주방 장갑은 뜨거운 냄비의 열이 손으로 전도되는 것을 막는다. 양산은 햇빛을 가려 복사로 오는 열을 막는다.","scoring_points":["단열 물건 두 가지를 바르게 골랐는가","각 물건이 막는 방식을 바르게 짝지었는가","어떻게 막는지 까닭을 썼는가"]},"explanation":["물건을 골라요.","방식을 짝지어요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L09_basic#1','sci',5,2,'u3','L09','g5_2_sci_u3_L09_basic','lesson_basic','SC5-2-u3-C19',1,'sa','auto','뽁뽁이·스타이로폼·솜처럼 단열을 하기 위해 쓰는 재료를 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u3-C19","difficulty":1,"kind":"sa","stem":"뽁뽁이·스타이로폼·솜처럼 단열을 하기 위해 쓰는 재료를 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["단열재"],"explanation":["단열에 써요.","세 글자예요.","단열재예요."],"mis":"SC5-2-u3-X32"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L09_basic#2','sci',5,2,'u3','L09','g5_2_sci_u3_L09_basic','lesson_basic','SC5-2-u3-C19',1,'mc','auto','단열재로 쓰기에 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X30']::text[],false,'{"seq":2,"concept":"SC5-2-u3-C19","difficulty":1,"kind":"mc","stem":"단열재로 쓰기에 알맞은 것은 어느 것인가요?","options":[{"t":"스타이로폼","correct":true},{"t":"구리판","mis":"SC5-2-u3-X30"},{"t":"알루미늄 캔","mis":"SC5-2-u3-X30"},{"t":"금속 숟가락","mis":"SC5-2-u3-X30"}],"explanation":["스타이로폼은 열을 막아요.","구리는 열이 잘 가요.","스타이로폼이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L09_basic#3','sci',5,2,'u3','L09','g5_2_sci_u3_L09_basic','lesson_basic','SC5-2-u3-C20',1,'mc','auto','장치가 온도를 잘 지키는지 알아보는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X34']::text[],false,'{"seq":3,"concept":"SC5-2-u3-C20","difficulty":1,"kind":"mc","stem":"장치가 온도를 잘 지키는지 알아보는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"넣은 물체의 온도를 시간 간격을 두고 잰다","correct":true},{"t":"장치의 색깔을 본다","mis":"SC5-2-u3-X34"},{"t":"장치의 무게를 잰다","mis":"SC5-2-u3-X34"},{"t":"장치를 흔들어 본다","mis":"SC5-2-u3-X34"}],"explanation":["온도를 지키는지 봐요.","시간마다 재요.","온도를 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L09_basic#4','sci',5,2,'u3','L09','g5_2_sci_u3_L09_basic','lesson_basic','SC5-2-u3-C19',1,'ox','auto','아이스크림을 오래 차갑게 지키려면 바깥의 열이 안으로 들어오지 않게 막아야 해요.',ARRAY['SC5-2-u3-X12']::text[],false,'{"seq":4,"concept":"SC5-2-u3-C19","difficulty":1,"kind":"ox","stem":"아이스크림을 오래 차갑게 지키려면 바깥의 열이 안으로 들어오지 않게 막아야 해요.","answer":"O","reason_options":[{"t":"바깥이 더 따뜻해 열이 아이스크림으로 오려 하기 때문에","correct":true},{"t":"아이스크림의 냉기를 바깥으로 내보내야 하기 때문에","mis":"SC5-2-u3-X12"}],"mis":"SC5-2-u3-X12","explanation":["바깥이 더 따뜻해요.","열이 들어오려 해요.","그것을 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L09_basic#5','sci',5,2,'u3','L09','g5_2_sci_u3_L09_basic','lesson_basic','SC5-2-u3-C19',2,'mc','auto','샛별 모둠 장치 설계도에서 지키려는 것은 무엇인가요?',ARRAY['SC5-2-u3-X30','SC5-2-u3-X34']::text[],false,'{"seq":5,"concept":"SC5-2-u3-C19","difficulty":2,"kind":"mc","stem":"샛별 모둠 장치 설계도에서 지키려는 것은 무엇인가요?","options":[{"t":"아이스크림을 차갑게 지키는 것","correct":true},{"t":"아이스크림을 빨리 녹이는 것","mis":"SC5-2-u3-X30"},{"t":"군고구마를 따뜻하게 지키는 것","mis":"SC5-2-u3-X34"},{"t":"통을 더 가볍게 하는 것","mis":"SC5-2-u3-X34"}],"explanation":["지킬 것을 봐요.","아이스크림이에요.","차갑게 지켜요."],"asset":{"type":"passage","lines":["지킬 것 — 아이스크림(차갑게)","재료 — 뚜껑 있는 통, 뽁뽁이, 스타이로폼, 은박지","방법 — 통 안쪽에 스타이로폼, 겉에 뽁뽁이 두 겹","확인 — 10분마다 통 안의 온도를 잰다."],"title":"샛별 모둠 장치 설계도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L09_basic#6','sci',5,2,'u3','L09','g5_2_sci_u3_L09_basic','lesson_basic','SC5-2-u3-C19',2,'mc','auto','아이스크림이 녹지 않는 장치를 만드는 방법으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X33']::text[],false,'{"seq":6,"concept":"SC5-2-u3-C19","difficulty":2,"kind":"mc","stem":"아이스크림이 녹지 않는 장치를 만드는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"바람이 잘 통하게 통에 구멍을 뚫는다","correct":true},{"t":"뽁뽁이로 여러 겹 감싼다","mis":"SC5-2-u3-X33"},{"t":"틈이 없도록 뚜껑을 덮는다","mis":"SC5-2-u3-X33"},{"t":"통 안쪽에 스타이로폼을 댄다","mis":"SC5-2-u3-X33"}],"explanation":["구멍으로 공기가 드나들어요.","열이 들어와요.","구멍은 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L09_basic#7','sci',5,2,'u3','L09','g5_2_sci_u3_L09_basic','lesson_basic','SC5-2-u3-C19',2,'ox','auto','단열재로 군고구마를 감싸면 단열재가 열을 만들어 군고구마를 더 따뜻하게 해요.',ARRAY['SC5-2-u3-X32']::text[],false,'{"seq":7,"concept":"SC5-2-u3-C19","difficulty":2,"kind":"ox","stem":"단열재로 군고구마를 감싸면 단열재가 열을 만들어 군고구마를 더 따뜻하게 해요.","answer":"X","reason_options":[{"t":"단열재는 열을 만들지 않고 빠져나가는 열을 막아 처음 온도를 지키기 때문에","correct":true},{"t":"단열재 안에서 열이 새로 생기기 때문에","mis":"SC5-2-u3-X32"}],"mis":"SC5-2-u3-X32","explanation":["단열재는 열을 안 만들어요.","나가는 열을 막아요.","온도를 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L09_basic#8','sci',5,2,'u3','L09','g5_2_sci_u3_L09_basic','lesson_basic','SC5-2-u3-C20',2,'mc','auto','샛별 모둠 장치 설계도의 「확인」처럼 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X34','SC5-2-u3-X30']::text[],false,'{"seq":8,"concept":"SC5-2-u3-C20","difficulty":2,"kind":"mc","stem":"샛별 모둠 장치 설계도의 「확인」처럼 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"온도가 오랫동안 일정하게 유지되는지 알아보려고","correct":true},{"t":"장치의 색깔이 변하는지 보려고","mis":"SC5-2-u3-X34"},{"t":"장치가 얼마나 무거운지 알려고","mis":"SC5-2-u3-X34"},{"t":"아이스크림을 빨리 녹이려고","mis":"SC5-2-u3-X30"}],"explanation":["10분마다 재요.","온도가 지켜지는지 봐요.","확인하는 방법이에요."],"asset":{"type":"passage","lines":["지킬 것 — 아이스크림(차갑게)","재료 — 뚜껑 있는 통, 뽁뽁이, 스타이로폼, 은박지","방법 — 통 안쪽에 스타이로폼, 겉에 뽁뽁이 두 겹","확인 — 10분마다 통 안의 온도를 잰다."],"title":"샛별 모둠 장치 설계도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L09_basic#9','sci',5,2,'u3','L09','g5_2_sci_u3_L09_basic','lesson_basic','SC5-2-u3-C19',2,'mc','auto','장치를 설계할 때 생각할 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X34','SC5-2-u3-X33','SC5-2-u3-X32']::text[],false,'{"seq":9,"concept":"SC5-2-u3-C19","difficulty":2,"kind":"mc","stem":"장치를 설계할 때 생각할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"지킬 물체, 단열재, 쓰기 편한 점(뚜껑·손잡이)","correct":true},{"t":"장치의 색깔만 정하면 된다","mis":"SC5-2-u3-X34"},{"t":"구멍을 많이 뚫을 곳","mis":"SC5-2-u3-X33"},{"t":"단열재 없이 통만 고르면 된다","mis":"SC5-2-u3-X32"}],"explanation":["무엇을 지킬까요?","무엇으로 막을까요?","쓰기 편한가요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L09_basic#10','sci',5,2,'u3','L09','g5_2_sci_u3_L09_basic','lesson_basic','SC5-2-u3-C20',3,'error','auto','장치를 시험한 뒤 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u3-X34','SC5-2-u3-X33']::text[],false,'{"seq":10,"concept":"SC5-2-u3-C20","difficulty":3,"kind":"error","stem":"장치를 시험한 뒤 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지율 — 「온도가 많이 바뀐 장치일수록 단열이 잘된 거야.」","correct":true,"mis_target":"SC5-2-u3-X34"},{"t":"하린 — 「10분마다 같은 방법으로 온도를 쟀어.」","mis":"SC5-2-u3-X34"},{"t":"서우 — 「뚜껑 틈을 막아서 고쳐 보자.」","mis":"SC5-2-u3-X33"}],"explanation":["덜 변해야 잘 지킨 거예요.","많이 변하면 못 지켰어요.","지율의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L09_challenge#1','sci',5,2,'u3','L09','g5_2_sci_u3_L09_challenge','lesson_challenge','SC5-2-u3-C19',2,'match','auto','장치의 부분과 막는 열의 이동을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u3-C19","difficulty":2,"kind":"match","stem":"장치의 부분과 막는 열의 이동을 알맞게 이으세요.","pairs":[{"l":"통 안쪽 스타이로폼","r":"전도를 줄임"},{"l":"틈 없이 덮은 뚜껑","r":"대류를 줄임"},{"l":"겉에 두른 은박지","r":"복사를 줄임"}],"mis":"SC5-2-u3-X31","explanation":["스타이로폼은 닿는 열이에요.","뚜껑은 공기 흐름이에요.","은박지는 빛이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L09_challenge#2','sci',5,2,'u3','L09','g5_2_sci_u3_L09_challenge','lesson_challenge','SC5-2-u3-C20',2,'mc','auto','두 장치 시험 결과에서 단열이 더 잘된 장치는 어느 것인가요?',ARRAY['SC5-2-u3-X34']::text[],false,'{"seq":2,"concept":"SC5-2-u3-C20","difficulty":2,"kind":"mc","stem":"두 장치 시험 결과에서 단열이 더 잘된 장치는 어느 것인가요?","options":[{"t":"가 모둠 장치","correct":true},{"t":"나 모둠 장치","mis":"SC5-2-u3-X34"},{"t":"두 장치가 같다","mis":"SC5-2-u3-X34"},{"t":"알 수 없다","mis":"SC5-2-u3-X34"}],"explanation":["가 모둠은 5 °C 낮아졌어요.","덜 변했어요.","가 모둠이에요."],"asset":{"type":"passage","lines":["두 모둠 장치에 같은 온도의 따뜻한 물을 넣었다.","20분 뒤 — 가 모둠: 5 °C 낮아짐 · 나 모둠: 12 °C 낮아짐","나 모둠 장치는 뚜껑 둘레에 틈이 있었다."],"title":"두 장치 시험 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L09_challenge#3','sci',5,2,'u3','L09','g5_2_sci_u3_L09_challenge','lesson_challenge','SC5-2-u3-C20',3,'mc','auto','두 장치 시험 결과에서 나 모둠 장치를 고치는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X33','SC5-2-u3-X34']::text[],false,'{"seq":3,"concept":"SC5-2-u3-C20","difficulty":3,"kind":"mc","stem":"두 장치 시험 결과에서 나 모둠 장치를 고치는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"뚜껑 둘레의 틈을 막고 단열재를 더 겹쳐 감싼다","correct":true},{"t":"뚜껑을 아예 떼어 낸다","mis":"SC5-2-u3-X33"},{"t":"물을 더 차갑게 넣는다","mis":"SC5-2-u3-X34"},{"t":"통에 구멍을 더 뚫는다","mis":"SC5-2-u3-X33"}],"explanation":["틈이 있었어요.","열이 빠져나갔어요.","틈을 막아요."],"asset":{"type":"passage","lines":["두 모둠 장치에 같은 온도의 따뜻한 물을 넣었다.","20분 뒤 — 가 모둠: 5 °C 낮아짐 · 나 모둠: 12 °C 낮아짐","나 모둠 장치는 뚜껑 둘레에 틈이 있었다."],"title":"두 장치 시험 결과"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L09_challenge#4','sci',5,2,'u3','L09','g5_2_sci_u3_L09_challenge','lesson_challenge','SC5-2-u3-C19',3,'mc','auto','군고구마를 오래 따뜻하게 지키는 장치에서 막아야 할 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X12','SC5-2-u3-X11','SC5-2-u3-X32']::text[],false,'{"seq":4,"concept":"SC5-2-u3-C19","difficulty":3,"kind":"mc","stem":"군고구마를 오래 따뜻하게 지키는 장치에서 막아야 할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"군고구마의 열이 바깥으로 빠져나가는 것","correct":true},{"t":"바깥 냉기가 군고구마로 들어오는 것","mis":"SC5-2-u3-X12"},{"t":"바깥 열이 군고구마로 들어오는 것","mis":"SC5-2-u3-X11"},{"t":"단열재가 열을 만드는 것","mis":"SC5-2-u3-X32"}],"explanation":["군고구마가 더 따뜻해요.","열이 나가려 해요.","그것을 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L09_challenge#5','sci',5,2,'u3','L09','g5_2_sci_u3_L09_challenge','lesson_challenge','SC5-2-u3-C20',3,'ox','auto','두 장치를 견줄 때는 처음 온도와 재는 시간을 같게 해야 해요.',ARRAY['SC5-2-u3-X34']::text[],false,'{"seq":5,"concept":"SC5-2-u3-C20","difficulty":3,"kind":"ox","stem":"두 장치를 견줄 때는 처음 온도와 재는 시간을 같게 해야 해요.","answer":"O","reason_options":[{"t":"다른 조건이 같아야 장치 차이만 견줄 수 있기 때문에","correct":true},{"t":"장치가 다르니 조건도 모두 달라야 하기 때문에","mis":"SC5-2-u3-X34"}],"mis":"SC5-2-u3-X34","explanation":["처음 온도가 같아야 해요.","시간도 같아야 해요.","그래야 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L09_challenge#6','sci',5,2,'u3','L09','g5_2_sci_u3_L09_challenge','lesson_challenge','SC5-2-u3-C19',3,'error','auto','장치를 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u3-X32','SC5-2-u3-X34','SC5-2-u3-X33']::text[],false,'{"seq":6,"concept":"SC5-2-u3-C19","difficulty":3,"kind":"error","stem":"장치를 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준서 — 「솜이 아이스크림을 차갑게 만들어 주니까 솜을 넣자.」","correct":true,"mis_target":"SC5-2-u3-X32"},{"t":"예나 — 「택배 상자 골판지를 겹쳐 다시 쓰자.」","mis":"SC5-2-u3-X34"},{"t":"민호 — 「뚜껑과 통 사이를 테이프로 막자.」","mis":"SC5-2-u3-X33"}],"explanation":["솜은 차갑게 만들지 않아요.","열이 오는 걸 막아요.","준서의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L09_challenge#7','sci',5,2,'u3','L09','g5_2_sci_u3_L09_challenge','lesson_challenge','SC5-2-u3-C19',3,'mc','auto','음식 배달 가방 안쪽에 두꺼운 단열재를 넣는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X29','SC5-2-u3-X30','SC5-2-u3-X32']::text[],false,'{"seq":7,"concept":"SC5-2-u3-C19","difficulty":3,"kind":"mc","stem":"음식 배달 가방 안쪽에 두꺼운 단열재를 넣는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"뜨거운 음식은 따뜻하게, 차가운 음식은 차갑게 지키려고","correct":true},{"t":"뜨거운 음식만 더 뜨겁게 하려고","mis":"SC5-2-u3-X29"},{"t":"가방 안의 음식을 빨리 식히려고","mis":"SC5-2-u3-X30"},{"t":"가방이 스스로 열을 만들게 하려고","mis":"SC5-2-u3-X32"}],"explanation":["단열재는 열을 막아요.","처음 온도를 지켜요.","둘 다 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L09_challenge#8','sci',5,2,'u3','L09','g5_2_sci_u3_L09_challenge','lesson_challenge','SC5-2-u3-C20',4,'mc','auto','같은 재료로 장치를 하나 더 만들어 성능을 높이려고 해요. 가장 알맞은 계획은 어느 것인가요?',ARRAY['SC5-2-u3-X32','SC5-2-u3-X33','SC5-2-u3-X34']::text[],false,'{"seq":8,"concept":"SC5-2-u3-C20","difficulty":4,"kind":"mc","stem":"같은 재료로 장치를 하나 더 만들어 성능을 높이려고 해요. 가장 알맞은 계획은 어느 것인가요?","options":[{"t":"단열재를 한 겹 더 두르고 틈을 막아 열이 새는 길을 줄인다","correct":true},{"t":"단열재를 빼고 통을 더 크게 만든다","mis":"SC5-2-u3-X32"},{"t":"통에 공기 구멍을 내어 열을 내보낸다","mis":"SC5-2-u3-X33"},{"t":"장치 겉을 화려하게 꾸민다","mis":"SC5-2-u3-X34"}],"explanation":["열이 새는 길을 찾아요.","겹을 늘려요.","틈을 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L09_challenge#9','sci',5,2,'u3','L09','g5_2_sci_u3_L09_challenge','lesson_challenge','SC5-2-u3-C20',4,'mc','auto','두 장치 시험 결과처럼 장치를 시험하고 고치는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X34']::text[],false,'{"seq":9,"concept":"SC5-2-u3-C20","difficulty":4,"kind":"mc","stem":"두 장치 시험 결과처럼 장치를 시험하고 고치는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"설계하기 → 만들기 → 온도 재어 확인하기 → 고치기","correct":true},{"t":"만들기 → 고치기 → 설계하기 → 확인하기","mis":"SC5-2-u3-X34"},{"t":"확인하기 → 설계하기 → 고치기 → 만들기","mis":"SC5-2-u3-X34"},{"t":"설계하기 → 고치기 → 만들기 → 확인하기","mis":"SC5-2-u3-X34"}],"explanation":["먼저 설계해요.","만들고 재요.","부족하면 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L09_challenge#10','sci',5,2,'u3','L09','g5_2_sci_u3_L09_challenge','lesson_challenge','SC5-2-u3-C19',4,'essay','teacher','군고구마를 오래 따뜻하게 지키는 장치를 설계하세요. 고른 단열재와 감싸는 방법을 쓰고, 그렇게 하면 열의 이동이 어떻게 막히는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u3-C19","difficulty":4,"kind":"essay","stem":"군고구마를 오래 따뜻하게 지키는 장치를 설계하세요. 고른 단열재와 감싸는 방법을 쓰고, 그렇게 하면 열의 이동이 어떻게 막히는지 쓰세요.","answer_guide":{"answer":"예: 뚜껑 있는 통 안쪽에 스타이로폼을 대고, 겉을 뽁뽁이로 두 겹 감싸며, 뚜껑 둘레를 테이프로 막는다. 스타이로폼과 뽁뽁이 속 공기가 군고구마의 열이 통을 따라 빠져나가는 것을 막고, 틈을 막아 따뜻한 공기가 새어 나가지 않게 한다.","scoring_points":["알맞은 단열재를 골랐는가","감싸는 방법(겹·틈 막기)을 썼는가","열이 빠져나가는 것을 막는다고 썼는가"]},"explanation":["단열재를 골라요.","겹치고 틈을 막아요.","열이 못 나가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L10_basic#1','sci',5,2,'u3','L10','g5_2_sci_u3_L10_basic','lesson_basic','SC5-2-u3-C21',1,'mc','auto','인공 태양 연구 장치에서 이중벽 안쪽을 은으로 도금해 막으려는 열의 이동 방식은 어느 것인가요?',ARRAY['SC5-2-u3-X36','SC5-2-u3-X28']::text[],false,'{"seq":1,"concept":"SC5-2-u3-C21","difficulty":1,"kind":"mc","stem":"인공 태양 연구 장치에서 이중벽 안쪽을 은으로 도금해 막으려는 열의 이동 방식은 어느 것인가요?","options":[{"t":"복사","correct":true},{"t":"전도","mis":"SC5-2-u3-X36"},{"t":"대류","mis":"SC5-2-u3-X36"},{"t":"응결","mis":"SC5-2-u3-X28"}],"explanation":["은은 빛을 되돌려요.","빛으로 오는 열이에요.","복사를 막아요."],"asset":{"type":"passage","lines":["인공 태양 연구 장치는 안을 아주 높은 온도로 유지해야 한다.","① 이중벽 사이의 공기를 모두 뺐다.","② 주변을 단열재로 여러 번 감쌌다.","③ 이중벽 안쪽을 은으로 도금했다."],"title":"인공 태양 연구 장치의 단열"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L10_basic#2','sci',5,2,'u3','L10','g5_2_sci_u3_L10_basic','lesson_basic','SC5-2-u3-C22',1,'mc','auto','물체의 따뜻하거나 차가운 정도를 무엇이라고 하나요?',ARRAY['SC5-2-u3-X08','SC5-2-u3-X30']::text[],false,'{"seq":2,"concept":"SC5-2-u3-C22","difficulty":1,"kind":"mc","stem":"물체의 따뜻하거나 차가운 정도를 무엇이라고 하나요?","options":[{"t":"온도","correct":true},{"t":"열의 이동","mis":"SC5-2-u3-X08"},{"t":"단열","mis":"SC5-2-u3-X30"},{"t":"부피","mis":"SC5-2-u3-X08"}],"explanation":["따뜻한 정도예요.","온도계로 재요.","온도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L10_basic#3','sci',5,2,'u3','L10','g5_2_sci_u3_L10_basic','lesson_basic','SC5-2-u3-C21',1,'ox','auto','인공 태양 연구 장치는 보온병과 비슷한 방법으로 단열해요.',ARRAY['SC5-2-u3-X30']::text[],false,'{"seq":3,"concept":"SC5-2-u3-C21","difficulty":1,"kind":"ox","stem":"인공 태양 연구 장치는 보온병과 비슷한 방법으로 단열해요.","answer":"O","reason_options":[{"t":"이중벽 사이 공기를 빼고 감싸는 방법이 보온병과 닮았기 때문에","correct":true},{"t":"보온병과 달리 열의 이동을 더 잘되게 하기 때문에","mis":"SC5-2-u3-X30"}],"mis":"SC5-2-u3-X30","explanation":["보온병도 이중벽이에요.","방법이 닮았어요.","단열해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L10_basic#4','sci',5,2,'u3','L10','g5_2_sci_u3_L10_basic','lesson_basic','SC5-2-u3-C22',1,'sa','auto','열의 이동 정리판의 ㉠에 들어갈 낱말을 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC5-2-u3-C22","difficulty":1,"kind":"sa","stem":"열의 이동 정리판의 ㉠에 들어갈 낱말을 쓰세요.","answer":["전도"],"explanation":["고체에서 일어나요.","주방 장갑이 막아요.","전도예요."],"asset":{"type":"passage","lines":["고체 — (㉠) — 주방 장갑으로 막는다","액체와 기체 — 대류 — (㉡)을 닫아 막는다","빛 — (㉢) — 양산으로 막는다"],"title":"열의 이동 정리판"},"mis":"SC5-2-u3-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L10_basic#5','sci',5,2,'u3','L10','g5_2_sci_u3_L10_basic','lesson_basic','SC5-2-u3-C21',2,'mc','auto','인공 태양 연구 장치에서 이중벽 사이 공기를 빼고 단열재로 감싸 막으려는 것은 어느 것인가요?',ARRAY['SC5-2-u3-X36','SC5-2-u3-X30']::text[],false,'{"seq":5,"concept":"SC5-2-u3-C21","difficulty":2,"kind":"mc","stem":"인공 태양 연구 장치에서 이중벽 사이 공기를 빼고 단열재로 감싸 막으려는 것은 어느 것인가요?","options":[{"t":"전도와 대류","correct":true},{"t":"복사만","mis":"SC5-2-u3-X36"},{"t":"대류와 복사","mis":"SC5-2-u3-X36"},{"t":"아무것도 막지 않는다","mis":"SC5-2-u3-X30"}],"explanation":["공기가 없으면 흐름이 없어요.","감싸면 닿는 열이 줄어요.","전도와 대류예요."],"asset":{"type":"passage","lines":["인공 태양 연구 장치는 안을 아주 높은 온도로 유지해야 한다.","① 이중벽 사이의 공기를 모두 뺐다.","② 주변을 단열재로 여러 번 감쌌다.","③ 이중벽 안쪽을 은으로 도금했다."],"title":"인공 태양 연구 장치의 단열"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L10_basic#6','sci',5,2,'u3','L10','g5_2_sci_u3_L10_basic','lesson_basic','SC5-2-u3-C21',2,'ox','auto','단열 기술은 보온병이나 옷처럼 생활 속 물건에만 쓰여요.',ARRAY['SC5-2-u3-X35']::text[],false,'{"seq":6,"concept":"SC5-2-u3-C21","difficulty":2,"kind":"ox","stem":"단열 기술은 보온병이나 옷처럼 생활 속 물건에만 쓰여요.","answer":"X","reason_options":[{"t":"인공 태양 연구 장치·우주선·소방 장비 같은 첨단 기술에도 쓰이기 때문에","correct":true},{"t":"첨단 기술에서는 열의 이동을 막을 필요가 없기 때문에","mis":"SC5-2-u3-X35"}],"mis":"SC5-2-u3-X35","explanation":["생활에도 써요.","첨단 기술에도 써요.","아주 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L10_basic#7','sci',5,2,'u3','L10','g5_2_sci_u3_L10_basic','lesson_basic','SC5-2-u3-C22',2,'mc','auto','열의 이동 정리판의 ㉡과 ㉢에 들어갈 말을 차례로 바르게 쓴 것은 어느 것인가요?',ARRAY['SC5-2-u3-X31','SC5-2-u3-X28']::text[],false,'{"seq":7,"concept":"SC5-2-u3-C22","difficulty":2,"kind":"mc","stem":"열의 이동 정리판의 ㉡과 ㉢에 들어갈 말을 차례로 바르게 쓴 것은 어느 것인가요?","options":[{"t":"창문 — 복사","correct":true},{"t":"양산 — 전도","mis":"SC5-2-u3-X31"},{"t":"창문 — 대류","mis":"SC5-2-u3-X28"},{"t":"장갑 — 복사","mis":"SC5-2-u3-X31"}],"explanation":["대류는 창문을 닫아 막아요.","빛은 복사예요.","창문 — 복사예요."],"asset":{"type":"passage","lines":["고체 — (㉠) — 주방 장갑으로 막는다","액체와 기체 — 대류 — (㉡)을 닫아 막는다","빛 — (㉢) — 양산으로 막는다"],"title":"열의 이동 정리판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L10_basic#8','sci',5,2,'u3','L10','g5_2_sci_u3_L10_basic','lesson_basic','SC5-2-u3-C22',2,'mc','auto','열과 우리 생활에서 배운 내용으로 바르지 않은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X30']::text[],false,'{"seq":8,"concept":"SC5-2-u3-C22","difficulty":2,"kind":"mc","stem":"열과 우리 생활에서 배운 내용으로 바르지 않은 것은 어느 것인가요?","options":[{"t":"단열은 열이 더 빨리 이동하게 하는 것이다","correct":true},{"t":"고체에서는 전도로 열이 이동한다","mis":"SC5-2-u3-X30"},{"t":"액체와 기체에서는 대류로 열이 이동한다","mis":"SC5-2-u3-X30"},{"t":"빛에 의해 열이 이동하는 방식은 복사이다","mis":"SC5-2-u3-X30"}],"explanation":["단열은 막는 거예요.","나머지는 맞아요.","단열이 틀렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L10_basic#9','sci',5,2,'u3','L10','g5_2_sci_u3_L10_basic','lesson_basic','SC5-2-u3-C22',2,'mc','auto','프라이팬에 고기 익히기, 전기 주전자로 물 끓이기, 난로 쬐기의 열의 이동 방식을 차례로 쓴 것은 어느 것인가요?',ARRAY['SC5-2-u3-X28']::text[],false,'{"seq":9,"concept":"SC5-2-u3-C22","difficulty":2,"kind":"mc","stem":"프라이팬에 고기 익히기, 전기 주전자로 물 끓이기, 난로 쬐기의 열의 이동 방식을 차례로 쓴 것은 어느 것인가요?","options":[{"t":"전도 — 대류 — 복사","correct":true},{"t":"대류 — 전도 — 복사","mis":"SC5-2-u3-X28"},{"t":"복사 — 대류 — 전도","mis":"SC5-2-u3-X28"},{"t":"전도 — 복사 — 대류","mis":"SC5-2-u3-X28"}],"explanation":["프라이팬은 고체예요.","물은 움직여요.","난로는 빛이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L10_basic#10','sci',5,2,'u3','L10','g5_2_sci_u3_L10_basic','lesson_basic','SC5-2-u3-C21',3,'error','auto','인공 태양 연구 장치의 단열을 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u3-X36']::text[],false,'{"seq":10,"concept":"SC5-2-u3-C21","difficulty":3,"kind":"error","stem":"인공 태양 연구 장치의 단열을 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"우진 — 「은 도금은 벽을 따라 오는 전도를 막으려는 거야.」","correct":true,"mis_target":"SC5-2-u3-X36"},{"t":"소윤 — 「공기를 뺀 건 대류를 막으려는 거야.」","mis":"SC5-2-u3-X36"},{"t":"태호 — 「단열재로 여러 번 감싸 전도를 막아.」","mis":"SC5-2-u3-X36"}],"explanation":["은은 빛을 되돌려요.","복사를 막아요.","우진의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["인공 태양 연구 장치는 안을 아주 높은 온도로 유지해야 한다.","① 이중벽 사이의 공기를 모두 뺐다.","② 주변을 단열재로 여러 번 감쌌다.","③ 이중벽 안쪽을 은으로 도금했다."],"title":"인공 태양 연구 장치의 단열"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L10_challenge#1','sci',5,2,'u3','L10','g5_2_sci_u3_L10_challenge','lesson_challenge','SC5-2-u3-C21',2,'match','auto','인공 태양 연구 장치의 단열 방법과 막는 열의 이동을 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u3-C21","difficulty":2,"kind":"match","stem":"인공 태양 연구 장치의 단열 방법과 막는 열의 이동을 이으세요.","pairs":[{"l":"이중벽 사이 공기 빼기","r":"대류를 막음"},{"l":"단열재로 여러 번 감싸기","r":"전도를 막음"},{"l":"이중벽 안쪽 은 도금","r":"복사를 막음"}],"mis":"SC5-2-u3-X36","explanation":["공기가 없으면 대류가 없어요.","감싸면 전도가 줄어요.","은은 복사를 막아요."],"asset":{"type":"passage","lines":["인공 태양 연구 장치는 안을 아주 높은 온도로 유지해야 한다.","① 이중벽 사이의 공기를 모두 뺐다.","② 주변을 단열재로 여러 번 감쌌다.","③ 이중벽 안쪽을 은으로 도금했다."],"title":"인공 태양 연구 장치의 단열"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L10_challenge#2','sci',5,2,'u3','L10','g5_2_sci_u3_L10_challenge','lesson_challenge','SC5-2-u3-C22',2,'mc','auto','열이 이동하는 방향을 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-2-u3-X11','SC5-2-u3-X12']::text[],false,'{"seq":2,"concept":"SC5-2-u3-C22","difficulty":2,"kind":"mc","stem":"열이 이동하는 방향을 바르게 말한 것은 어느 것인가요?","options":[{"t":"언제나 온도가 높은 곳에서 낮은 곳으로","correct":true},{"t":"온도가 낮은 곳에서 높은 곳으로","mis":"SC5-2-u3-X11"},{"t":"차가운 기운이 따뜻한 곳으로","mis":"SC5-2-u3-X12"},{"t":"무거운 물체에서 가벼운 물체로","mis":"SC5-2-u3-X11"}],"explanation":["온도를 견줘요.","높은 곳에서 나가요.","낮은 곳으로 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L10_challenge#3','sci',5,2,'u3','L10','g5_2_sci_u3_L10_challenge','lesson_challenge','SC5-2-u3-C21',3,'mc','auto','뜨거운 태양 가까이를 탐사하는 우주선은 공기가 거의 없는 곳을 날아요. 가장 크게 막아야 할 열의 이동 방식은 어느 것인가요?',ARRAY['SC5-2-u3-X36','SC5-2-u3-X35']::text[],false,'{"seq":3,"concept":"SC5-2-u3-C21","difficulty":3,"kind":"mc","stem":"뜨거운 태양 가까이를 탐사하는 우주선은 공기가 거의 없는 곳을 날아요. 가장 크게 막아야 할 열의 이동 방식은 어느 것인가요?","options":[{"t":"복사","correct":true},{"t":"대류","mis":"SC5-2-u3-X36"},{"t":"전도만","mis":"SC5-2-u3-X36"},{"t":"막을 필요가 없다","mis":"SC5-2-u3-X35"}],"explanation":["우주는 공기가 거의 없어요.","태양 열은 빛으로 와요.","복사를 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L10_challenge#4','sci',5,2,'u3','L10','g5_2_sci_u3_L10_challenge','lesson_challenge','SC5-2-u3-C21',3,'mc','auto','태양 가까이 가는 우주선 바깥을 반짝이는 재료로 덮는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X36','SC5-2-u3-X30']::text[],false,'{"seq":4,"concept":"SC5-2-u3-C21","difficulty":3,"kind":"mc","stem":"태양 가까이 가는 우주선 바깥을 반짝이는 재료로 덮는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"빛을 되돌려 복사로 오는 열을 막으려고","correct":true},{"t":"우주선 몸체를 따라 오는 전도를 키우려고","mis":"SC5-2-u3-X36"},{"t":"우주의 공기 흐름을 막으려고","mis":"SC5-2-u3-X36"},{"t":"우주선을 더 따뜻하게 하려고","mis":"SC5-2-u3-X30"}],"explanation":["반짝이면 빛을 되돌려요.","태양의 빛이에요.","복사를 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L10_challenge#5','sci',5,2,'u3','L10','g5_2_sci_u3_L10_challenge','lesson_challenge','SC5-2-u3-C22',3,'ox','auto','얼음 위 생선, 프라이팬 속 달걀, 난로 앞 손처럼 열은 늘 온도가 높은 쪽에서 낮은 쪽으로 이동해요.',ARRAY['SC5-2-u3-X11']::text[],false,'{"seq":5,"concept":"SC5-2-u3-C22","difficulty":3,"kind":"ox","stem":"얼음 위 생선, 프라이팬 속 달걀, 난로 앞 손처럼 열은 늘 온도가 높은 쪽에서 낮은 쪽으로 이동해요.","answer":"O","reason_options":[{"t":"열의 이동 방식은 달라도 방향은 늘 높은 쪽에서 낮은 쪽이기 때문에","correct":true},{"t":"방식에 따라 낮은 쪽에서 높은 쪽으로 가기도 하기 때문에","mis":"SC5-2-u3-X11"}],"mis":"SC5-2-u3-X11","explanation":["생선이 얼음보다 따뜻해요.","팬이 달걀보다 뜨거워요.","방향은 늘 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L10_challenge#6','sci',5,2,'u3','L10','g5_2_sci_u3_L10_challenge','lesson_challenge','SC5-2-u3-C22',3,'error','auto','단원을 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u3-X12','SC5-2-u3-X04','SC5-2-u3-X29']::text[],false,'{"seq":6,"concept":"SC5-2-u3-C22","difficulty":3,"kind":"error","stem":"단원을 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"유나 — 「얼음을 쥐면 얼음의 냉기가 손으로 전도돼.」","correct":true,"mis_target":"SC5-2-u3-X12"},{"t":"규리 — 「온도는 온도계로 재야 정확해.」","mis":"SC5-2-u3-X04"},{"t":"도하 — 「보온병은 차가운 것도 차갑게 지켜.」","mis":"SC5-2-u3-X29"}],"explanation":["손이 더 따뜻해요.","손의 열이 얼음으로 가요.","유나의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L10_challenge#7','sci',5,2,'u3','L10','g5_2_sci_u3_L10_challenge','lesson_challenge','SC5-2-u3-C22',3,'mc','auto','열의 이동을 막는 방법을 고를 때 먼저 따져야 할 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X34','SC5-2-u3-X11','SC5-2-u3-X32']::text[],false,'{"seq":7,"concept":"SC5-2-u3-C22","difficulty":3,"kind":"mc","stem":"열의 이동을 막는 방법을 고를 때 먼저 따져야 할 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"열이 어디에서 어떤 방식(전도·대류·복사)으로 이동하는지","correct":true},{"t":"막을 물건의 색깔이 예쁜지","mis":"SC5-2-u3-X34"},{"t":"열이 낮은 곳에서 높은 곳으로 가는지","mis":"SC5-2-u3-X11"},{"t":"단열재가 열을 얼마나 만드는지","mis":"SC5-2-u3-X32"}],"explanation":["방식을 먼저 봐요.","그에 맞게 막아요.","방식이 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L10_challenge#8','sci',5,2,'u3','L10','g5_2_sci_u3_L10_challenge','lesson_challenge','SC5-2-u3-C21',4,'mc','auto','얇고 따뜻한 겨울옷을 만들려고 해요. 전도·대류·복사를 모두 생각한 계획으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X30','SC5-2-u3-X33','SC5-2-u3-X32']::text[],false,'{"seq":8,"concept":"SC5-2-u3-C21","difficulty":4,"kind":"mc","stem":"얇고 따뜻한 겨울옷을 만들려고 해요. 전도·대류·복사를 모두 생각한 계획으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"옷감 사이에 공기층을 두어 전도·대류를 줄이고 몸 쪽 안감을 반짝이게 해 복사를 줄인다","correct":true},{"t":"얇은 금속판 한 장으로 옷을 만든다","mis":"SC5-2-u3-X30"},{"t":"옷에 구멍을 많이 뚫어 공기가 잘 통하게 한다","mis":"SC5-2-u3-X33"},{"t":"옷이 스스로 열을 만들도록 색만 바꾼다","mis":"SC5-2-u3-X32"}],"explanation":["공기층이 막아요.","안감은 빛을 되돌려요.","세 방식을 다 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L10_challenge#9','sci',5,2,'u3','L10','g5_2_sci_u3_L10_challenge','lesson_challenge','SC5-2-u3-C22',4,'mc','auto','겨울 캠핑에서 텐트 안을 따뜻하게 지키는 방법을 열의 이동과 바르게 이은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X30','SC5-2-u3-X33','SC5-2-u3-X12']::text[],false,'{"seq":9,"concept":"SC5-2-u3-C22","difficulty":4,"kind":"mc","stem":"겨울 캠핑에서 텐트 안을 따뜻하게 지키는 방법을 열의 이동과 바르게 이은 것은 어느 것인가요?","options":[{"t":"바닥에 깔개를 깔아 땅으로 가는 전도를 줄이고, 텐트 문을 닫아 공기 흐름을 막는다","correct":true},{"t":"바닥 깔개를 빼고 차가운 땅에 바로 눕는다","mis":"SC5-2-u3-X30"},{"t":"텐트 문을 열어 따뜻한 공기가 잘 나가게 한다","mis":"SC5-2-u3-X33"},{"t":"냉기가 들어오지 않게 텐트를 금속으로 만든다","mis":"SC5-2-u3-X12"}],"explanation":["땅이 더 차가워요.","깔개가 전도를 막아요.","문은 대류를 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_L10_challenge#10','sci',5,2,'u3','L10','g5_2_sci_u3_L10_challenge','lesson_challenge','SC5-2-u3-C21',4,'essay','teacher','단열 기술을 미래에 어디에 쓰고 싶은지 하나 정하고, 전도·대류·복사를 각각 어떻게 막을지 계획해 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC5-2-u3-C21","difficulty":4,"kind":"essay","stem":"단열 기술을 미래에 어디에 쓰고 싶은지 하나 정하고, 전도·대류·복사를 각각 어떻게 막을지 계획해 쓰세요.","answer_guide":{"answer":"예: 사막을 지나는 구급차에 쓰고 싶다. 차 벽 사이에 단열재를 넣어 전도를 막고, 창문과 문 틈을 막아 대류를 막으며, 차 바깥을 반짝이는 재료로 덮어 햇빛의 복사를 막는다.","scoring_points":["쓰고 싶은 곳을 정했는가","전도·대류·복사를 막는 방법을 각각 썼는가","방법과 방식을 바르게 짝지었는가"]},"explanation":["쓸 곳을 정해요.","세 방식을 막아요.","바르게 짝지어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_a#1','sci',5,2,'u3','','g5_2_sci_u3_review_a','unit_review','SC5-2-u3-C1',1,'mc','auto','햇빛반 캠프 일지 ①에서 이름표 붙임딱지 색이 바뀐 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X01','SC5-2-u3-X03']::text[],false,'{"seq":1,"concept":"SC5-2-u3-C1","difficulty":1,"kind":"mc","stem":"햇빛반 캠프 일지 ①에서 이름표 붙임딱지 색이 바뀐 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"따뜻한 손을 대었기 때문이다","correct":true},{"t":"이름표를 세게 문질렀기 때문이다","mis":"SC5-2-u3-X01"},{"t":"입김을 세게 불었기 때문이다","mis":"SC5-2-u3-X03"},{"t":"차가운 바람이 불었기 때문이다","mis":"SC5-2-u3-X03"}],"explanation":["손을 대었어요.","손이 따뜻해요.","색이 바뀌었어요."],"asset":{"type":"passage","lines":["캠프 첫날, 이름표에 열 변색 붙임딱지를 붙였다. 손을 대면 색이 바뀌었다.","텐트 안 공기 — 알코올 온도계: 6.5 °C","물통 속 물 — 탐침 온도계: 12.0 °C","나무 의자 표면 — 적외선 온도계: 3.8 °C","모둠장 은찬: 「느낌 말고 숫자로 적자.」"],"title":"① 첫날 — 이름표와 온도 재기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_a#2','sci',5,2,'u3','','g5_2_sci_u3_review_a','unit_review','SC5-2-u3-C3',1,'mc','auto','햇빛반 캠프 일지 ①에서 나무 의자 표면을 겨누어 잰 온도계는 어느 것인가요?',ARRAY['SC5-2-u3-X07','SC5-2-u3-X08']::text[],false,'{"seq":2,"concept":"SC5-2-u3-C3","difficulty":1,"kind":"mc","stem":"햇빛반 캠프 일지 ①에서 나무 의자 표면을 겨누어 잰 온도계는 어느 것인가요?","options":[{"t":"적외선 온도계","correct":true},{"t":"알코올 온도계","mis":"SC5-2-u3-X07"},{"t":"탐침 온도계","mis":"SC5-2-u3-X07"},{"t":"체중계","mis":"SC5-2-u3-X08"}],"explanation":["표면을 겨누었어요.","단추를 눌러요.","적외선 온도계예요."],"asset":{"type":"passage","lines":["캠프 첫날, 이름표에 열 변색 붙임딱지를 붙였다. 손을 대면 색이 바뀌었다.","텐트 안 공기 — 알코올 온도계: 6.5 °C","물통 속 물 — 탐침 온도계: 12.0 °C","나무 의자 표면 — 적외선 온도계: 3.8 °C","모둠장 은찬: 「느낌 말고 숫자로 적자.」"],"title":"① 첫날 — 이름표와 온도 재기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_a#3','sci',5,2,'u3','','g5_2_sci_u3_review_a','unit_review','SC5-2-u3-C6',1,'mc','auto','햇빛반 캠프 일지 ②에서 열은 어느 쪽으로 이동했나요?',ARRAY['SC5-2-u3-X11','SC5-2-u3-X09']::text[],false,'{"seq":3,"concept":"SC5-2-u3-C6","difficulty":1,"kind":"mc","stem":"햇빛반 캠프 일지 ②에서 열은 어느 쪽으로 이동했나요?","options":[{"t":"코코아에서 우유 팩으로","correct":true},{"t":"우유 팩에서 코코아로","mis":"SC5-2-u3-X11"},{"t":"이동하지 않았다","mis":"SC5-2-u3-X09"},{"t":"컵에서 손으로만","mis":"SC5-2-u3-X11"}],"explanation":["코코아가 더 따뜻해요.","높은 쪽에서 가요.","우유 팩으로 가요."],"asset":{"type":"passage","lines":["따뜻한 코코아 컵 속에 차가운 우유 팩을 넣고 온도를 쟀다.","0분 — 코코아 50 °C · 우유 팩 10 °C","4분 — 코코아 40 °C · 우유 팩 22 °C","8분 — 코코아 34 °C · 우유 팩 28 °C","12분 — 코코아 31 °C · 우유 팩 31 °C"],"title":"② 첫날 저녁 — 코코아와 우유 팩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_a#4','sci',5,2,'u3','','g5_2_sci_u3_review_a','unit_review','SC5-2-u3-C8',1,'sa','auto','고체 물질을 따라 열이 이동하는 방식을 무엇이라고 하나요? 두 글자로 쓰세요. (햇빛반 캠프 일지 ③)','{}'::text[],false,'{"seq":4,"concept":"SC5-2-u3-C8","difficulty":1,"kind":"sa","stem":"고체 물질을 따라 열이 이동하는 방식을 무엇이라고 하나요? 두 글자로 쓰세요. (햇빛반 캠프 일지 ③)","answer":["전도"],"explanation":["철판은 고체예요.","두 글자예요.","전도예요."],"asset":{"type":"passage","lines":["아침에 넓은 철판 한가운데 아래에만 불을 켜고 버터를 올렸다.","한가운데 버터가 먼저 녹고, 가장자리 버터는 나중에 녹았다.","요리사님은 쇠 주걱 대신 나무 주걱을 손에 쥐었다."],"title":"③ 둘째 날 아침 — 철판 구이"},"mis":"SC5-2-u3-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_a#5','sci',5,2,'u3','','g5_2_sci_u3_review_a','unit_review','SC5-2-u3-C12',1,'sa','auto','햇빛반 캠프 일지 ④에서 냄비 물이 위아래로 돌며 데워지는 열의 이동 방식은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"SC5-2-u3-C12","difficulty":1,"kind":"sa","stem":"햇빛반 캠프 일지 ④에서 냄비 물이 위아래로 돌며 데워지는 열의 이동 방식은 무엇인가요? 두 글자로 쓰세요.","answer":["대류"],"explanation":["물이 움직여요.","두 글자예요.","대류예요."],"asset":{"type":"passage","lines":["냄비에 물을 붓고 바닥만 가열하니 물이 위아래로 돌았다.","텐트 안 바닥 가까이에 난로를 두었더니 텐트 위쪽부터 따뜻해졌다.","선생님: 「난로는 꼭 어른과 함께, 환기도 잊지 말아요.」"],"title":"④ 둘째 날 — 냄비 물과 텐트 난로"},"mis":"SC5-2-u3-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_a#6','sci',5,2,'u3','','g5_2_sci_u3_review_a','unit_review','SC5-2-u3-C15',1,'mc','auto','햇빛반 캠프 일지 ⑤에서 모닥불 앞 얼굴이 뜨거운 까닭이 되는 열의 이동 방식은 어느 것인가요?',ARRAY['SC5-2-u3-X26','SC5-2-u3-X28']::text[],false,'{"seq":6,"concept":"SC5-2-u3-C15","difficulty":1,"kind":"mc","stem":"햇빛반 캠프 일지 ⑤에서 모닥불 앞 얼굴이 뜨거운 까닭이 되는 열의 이동 방식은 어느 것인가요?","options":[{"t":"복사","correct":true},{"t":"전도","mis":"SC5-2-u3-X26"},{"t":"대류","mis":"SC5-2-u3-X26"},{"t":"응결","mis":"SC5-2-u3-X28"}],"explanation":["불에 닿지 않았어요.","빛으로 와요.","복사예요."],"asset":{"type":"passage","lines":["같은 온도의 검은 장갑 두 짝 가운데 한 짝은 햇빛, 한 짝은 그늘에 두었다.","30분 뒤 햇빛에 둔 장갑이 더 따뜻했다.","밤에는 모닥불 앞에 앉았더니 얼굴은 뜨겁고 등은 차가웠다."],"title":"⑤ 둘째 날 오후와 밤 — 햇빛과 모닥불"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_a#7','sci',5,2,'u3','','g5_2_sci_u3_review_a','unit_review','SC5-2-u3-C17',1,'mc','auto','햇빛반 캠프 일지 ⑦에서 보온병 ㉯의 얼음물은 어떻게 되나요?',ARRAY['SC5-2-u3-X29','SC5-2-u3-X32','SC5-2-u3-X30']::text[],false,'{"seq":7,"concept":"SC5-2-u3-C17","difficulty":1,"kind":"mc","stem":"햇빛반 캠프 일지 ⑦에서 보온병 ㉯의 얼음물은 어떻게 되나요?","options":[{"t":"오랫동안 차갑게 유지된다","correct":true},{"t":"보온병이라 금방 따뜻해진다","mis":"SC5-2-u3-X29"},{"t":"보온병이 스스로 더 차갑게 만든다","mis":"SC5-2-u3-X32"},{"t":"곧바로 끓는다","mis":"SC5-2-u3-X30"}],"explanation":["보온병은 열을 막아요.","열이 못 들어와요.","차갑게 지켜요."],"asset":{"type":"passage","lines":["보온병 ㉮에는 뜨거운 보리차, 보온병 ㉯에는 얼음물을 담았다.","아이스박스에 우유를, 보온 도시락에 밥을 담았다.","밤에는 겹겹이 옷을 입고 두꺼운 침낭에 들어갔다."],"title":"⑦ 셋째 날 밤 — 열을 지키는 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_a#8','sci',5,2,'u3','','g5_2_sci_u3_review_a','unit_review','SC5-2-u3-C19',1,'sa','auto','햇빛반 캠프 일지 ⑧에서 뽁뽁이·스타이로폼처럼 단열에 쓰는 재료를 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SC5-2-u3-C19","difficulty":1,"kind":"sa","stem":"햇빛반 캠프 일지 ⑧에서 뽁뽁이·스타이로폼처럼 단열에 쓰는 재료를 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["단열재"],"explanation":["단열에 써요.","세 글자예요.","단열재예요."],"asset":{"type":"passage","lines":["같은 온도의 따뜻한 물을 세 장치에 넣고 30분 뒤 다시 쟀다.","가 — 뽁뽁이 두 겹, 뚜껑 덮음: 4 °C 낮아짐","나 — 신문지 한 겹, 뚜껑 없음: 15 °C 낮아짐","다 — 스타이로폼 상자, 뚜껑, 은박지: 2 °C 낮아짐","마지막 영상 — 인공 태양 연구 장치의 단열 이야기"],"title":"⑧ 마지막 날 — 장치 대회와 영상"},"mis":"SC5-2-u3-X32"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_a#9','sci',5,2,'u3','','g5_2_sci_u3_review_a','unit_review','SC5-2-u3-C2',2,'mc','auto','햇빛반 캠프 일지 ①에서 온도가 가장 낮은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X13','SC5-2-u3-X09']::text[],false,'{"seq":9,"concept":"SC5-2-u3-C2","difficulty":2,"kind":"mc","stem":"햇빛반 캠프 일지 ①에서 온도가 가장 낮은 것은 어느 것인가요?","options":[{"t":"나무 의자 표면","correct":true},{"t":"텐트 안 공기","mis":"SC5-2-u3-X13"},{"t":"물통 속 물","mis":"SC5-2-u3-X13"},{"t":"세 가지가 모두 같다","mis":"SC5-2-u3-X09"}],"explanation":["숫자를 견줘요.","3.8 °C가 가장 작아요.","나무 의자예요."],"asset":{"type":"passage","lines":["캠프 첫날, 이름표에 열 변색 붙임딱지를 붙였다. 손을 대면 색이 바뀌었다.","텐트 안 공기 — 알코올 온도계: 6.5 °C","물통 속 물 — 탐침 온도계: 12.0 °C","나무 의자 표면 — 적외선 온도계: 3.8 °C","모둠장 은찬: 「느낌 말고 숫자로 적자.」"],"title":"① 첫날 — 이름표와 온도 재기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_a#10','sci',5,2,'u3','','g5_2_sci_u3_review_a','unit_review','SC5-2-u3-C5',2,'mc','auto','햇빛반 캠프 일지 ②에서 코코아의 온도 변화로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X09','SC5-2-u3-X10']::text[],false,'{"seq":10,"concept":"SC5-2-u3-C5","difficulty":2,"kind":"mc","stem":"햇빛반 캠프 일지 ②에서 코코아의 온도 변화로 알맞은 것은 어느 것인가요?","options":[{"t":"50 °C에서 점점 낮아져 31 °C가 되었다","correct":true},{"t":"50 °C에서 점점 높아졌다","mis":"SC5-2-u3-X09"},{"t":"끝까지 50 °C였다","mis":"SC5-2-u3-X09"},{"t":"우유 팩보다 낮아졌다","mis":"SC5-2-u3-X10"}],"explanation":["50에서 시작해요.","내려가요.","31 °C예요."],"asset":{"type":"passage","lines":["따뜻한 코코아 컵 속에 차가운 우유 팩을 넣고 온도를 쟀다.","0분 — 코코아 50 °C · 우유 팩 10 °C","4분 — 코코아 40 °C · 우유 팩 22 °C","8분 — 코코아 34 °C · 우유 팩 28 °C","12분 — 코코아 31 °C · 우유 팩 31 °C"],"title":"② 첫날 저녁 — 코코아와 우유 팩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_a#11','sci',5,2,'u3','','g5_2_sci_u3_review_a','unit_review','SC5-2-u3-C6',2,'mc','auto','얼음물 보온병 ㉯를 맨손으로 오래 쥐면 손이 차가워지는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X12','SC5-2-u3-X11','SC5-2-u3-X09']::text[],false,'{"seq":11,"concept":"SC5-2-u3-C6","difficulty":2,"kind":"mc","stem":"얼음물 보온병 ㉯를 맨손으로 오래 쥐면 손이 차가워지는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"손의 열이 차가운 보온병 겉으로 이동하기 때문이다","correct":true},{"t":"보온병의 냉기가 손으로 옮겨 오기 때문이다","mis":"SC5-2-u3-X12"},{"t":"보온병의 열이 손으로 오기 때문이다","mis":"SC5-2-u3-X11"},{"t":"손의 온도는 변하지 않기 때문이다","mis":"SC5-2-u3-X09"}],"explanation":["손이 더 따뜻해요.","손의 열이 나가요.","손이 차가워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_a#12','sci',5,2,'u3','','g5_2_sci_u3_review_a','unit_review','SC5-2-u3-C7',2,'mc','auto','햇빛반 캠프 일지 ③에서 가장자리 버터가 나중에 녹은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X12','SC5-2-u3-X15','SC5-2-u3-X14']::text[],false,'{"seq":12,"concept":"SC5-2-u3-C7","difficulty":2,"kind":"mc","stem":"햇빛반 캠프 일지 ③에서 가장자리 버터가 나중에 녹은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"한가운데의 열이 철판을 따라 가장자리까지 오는 데 시간이 걸려서","correct":true},{"t":"가장자리의 냉기가 버터를 지켜서","mis":"SC5-2-u3-X12"},{"t":"열이 한가운데에서 틈을 건너뛰어서","mis":"SC5-2-u3-X15"},{"t":"가장자리부터 먼저 뜨거워져서","mis":"SC5-2-u3-X14"}],"explanation":["불은 한가운데예요.","판을 따라가요.","가장자리는 멀어요."],"asset":{"type":"passage","lines":["아침에 넓은 철판 한가운데 아래에만 불을 켜고 버터를 올렸다.","한가운데 버터가 먼저 녹고, 가장자리 버터는 나중에 녹았다.","요리사님은 쇠 주걱 대신 나무 주걱을 손에 쥐었다."],"title":"③ 둘째 날 아침 — 철판 구이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_a#13','sci',5,2,'u3','','g5_2_sci_u3_review_a','unit_review','SC5-2-u3-C10',2,'mc','auto','물속 잉크가 위로 올라갔다가 퍼지며 내려오는 것을 보고 알 수 있는 것은 어느 것인가요?',ARRAY['SC5-2-u3-X19','SC5-2-u3-X22','SC5-2-u3-X20']::text[],false,'{"seq":13,"concept":"SC5-2-u3-C10","difficulty":2,"kind":"mc","stem":"물속 잉크가 위로 올라갔다가 퍼지며 내려오는 것을 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"데워진 물이 움직이며 열을 옮긴다","correct":true},{"t":"잉크가 바로 열이다","mis":"SC5-2-u3-X19"},{"t":"물은 움직이지 않는다","mis":"SC5-2-u3-X22"},{"t":"데워진 물은 아래로 내려간다","mis":"SC5-2-u3-X20"}],"explanation":["잉크는 물을 따라가요.","물이 움직여요.","대류예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_a#14','sci',5,2,'u3','','g5_2_sci_u3_review_a','unit_review','SC5-2-u3-C14',2,'mc','auto','햇빛반 캠프 일지 ⑤의 장갑 실험에서 다르게 한 것은 어느 것인가요?',ARRAY['SC5-2-u3-X24']::text[],false,'{"seq":14,"concept":"SC5-2-u3-C14","difficulty":2,"kind":"mc","stem":"햇빛반 캠프 일지 ⑤의 장갑 실험에서 다르게 한 것은 어느 것인가요?","options":[{"t":"장갑을 둔 곳","correct":true},{"t":"장갑의 색깔","mis":"SC5-2-u3-X24"},{"t":"장갑의 처음 온도","mis":"SC5-2-u3-X24"},{"t":"두는 시간","mis":"SC5-2-u3-X24"}],"explanation":["같은 검은 장갑이에요.","시간도 같아요.","둔 곳만 달라요."],"asset":{"type":"passage","lines":["같은 온도의 검은 장갑 두 짝 가운데 한 짝은 햇빛, 한 짝은 그늘에 두었다.","30분 뒤 햇빛에 둔 장갑이 더 따뜻했다.","밤에는 모닥불 앞에 앉았더니 얼굴은 뜨겁고 등은 차가웠다."],"title":"⑤ 둘째 날 오후와 밤 — 햇빛과 모닥불"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_a#15','sci',5,2,'u3','','g5_2_sci_u3_review_a','unit_review','SC5-2-u3-C16',2,'mc','auto','햇빛반 캠프 일지 ⑥에서 피자 바닥이 돌판에서 열을 받는 방식은 어느 것인가요?',ARRAY['SC5-2-u3-X17','SC5-2-u3-X26','SC5-2-u3-X28']::text[],false,'{"seq":15,"concept":"SC5-2-u3-C16","difficulty":2,"kind":"mc","stem":"햇빛반 캠프 일지 ⑥에서 피자 바닥이 돌판에서 열을 받는 방식은 어느 것인가요?","options":[{"t":"전도","correct":true},{"t":"대류","mis":"SC5-2-u3-X17"},{"t":"복사","mis":"SC5-2-u3-X26"},{"t":"응결","mis":"SC5-2-u3-X28"}],"explanation":["바닥이 돌판에 닿아요.","고체끼리예요.","전도예요."],"asset":{"type":"passage","lines":["돌로 만든 화덕에 장작을 피우고 피자를 넣었다.","피자 바닥은 뜨거운 돌판에 닿아 있었다.","화덕 안 뜨거운 공기가 돌았고, 벽과 불빛도 피자를 데웠다."],"title":"⑥ 셋째 날 낮 — 화덕 피자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_a#16','sci',5,2,'u3','','g5_2_sci_u3_review_a','unit_review','SC5-2-u3-C18',2,'mc','auto','햇빛반 캠프 일지 ⑦에서 아이스박스가 우유를 차갑게 지키는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X12','SC5-2-u3-X30','SC5-2-u3-X32']::text[],false,'{"seq":16,"concept":"SC5-2-u3-C18","difficulty":2,"kind":"mc","stem":"햇빛반 캠프 일지 ⑦에서 아이스박스가 우유를 차갑게 지키는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"바깥의 열이 안으로 들어오는 것을 막는다","correct":true},{"t":"우유의 냉기를 안에 가둔다","mis":"SC5-2-u3-X12"},{"t":"바깥 열을 안으로 끌어온다","mis":"SC5-2-u3-X30"},{"t":"상자가 스스로 차가워진다","mis":"SC5-2-u3-X32"}],"explanation":["바깥이 더 따뜻해요.","열이 들어오려 해요.","막아요."],"asset":{"type":"passage","lines":["보온병 ㉮에는 뜨거운 보리차, 보온병 ㉯에는 얼음물을 담았다.","아이스박스에 우유를, 보온 도시락에 밥을 담았다.","밤에는 겹겹이 옷을 입고 두꺼운 침낭에 들어갔다."],"title":"⑦ 셋째 날 밤 — 열을 지키는 물건"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_a#17','sci',5,2,'u3','','g5_2_sci_u3_review_a','unit_review','SC5-2-u3-C3',3,'mc','auto','캠프에서 끓는 국의 온도를 재려고 해요. 가장 알맞은 방법은 어느 것인가요?',ARRAY['SC5-2-u3-X07','SC5-2-u3-X04','SC5-2-u3-X06']::text[],false,'{"seq":17,"concept":"SC5-2-u3-C3","difficulty":3,"kind":"mc","stem":"캠프에서 끓는 국의 온도를 재려고 해요. 가장 알맞은 방법은 어느 것인가요?","options":[{"t":"탐침 온도계를 국 가운데에 넣고 숫자가 멈추면 읽는다","correct":true},{"t":"반짝이는 냄비 겉면을 적외선 온도계로 잰다","mis":"SC5-2-u3-X07"},{"t":"국에 손가락을 넣어 느껴 본다","mis":"SC5-2-u3-X04"},{"t":"탐침을 냄비 바닥에 꾹 대고 잰다","mis":"SC5-2-u3-X06"}],"explanation":["국 속을 재요.","바닥에 닿지 않게요.","탐침 온도계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_a#18','sci',5,2,'u3','','g5_2_sci_u3_review_a','unit_review','SC5-2-u3-C6',3,'mc','auto','햇빛반 캠프 일지 ②에서 코코아가 식고 우유 팩이 데워진 까닭을 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-2-u3-X12','SC5-2-u3-X11','SC5-2-u3-X09']::text[],false,'{"seq":18,"concept":"SC5-2-u3-C6","difficulty":3,"kind":"mc","stem":"햇빛반 캠프 일지 ②에서 코코아가 식고 우유 팩이 데워진 까닭을 바르게 말한 것은 어느 것인가요?","options":[{"t":"온도가 높은 코코아에서 낮은 우유 팩으로 열이 이동했기 때문이다","correct":true},{"t":"우유 팩의 냉기가 코코아로 이동했기 때문이다","mis":"SC5-2-u3-X12"},{"t":"우유 팩에서 코코아로 열이 이동했기 때문이다","mis":"SC5-2-u3-X11"},{"t":"코코아만 변하고 우유 팩은 그대로였기 때문이다","mis":"SC5-2-u3-X09"}],"explanation":["코코아가 더 따뜻해요.","열이 우유로 가요.","둘 다 변해요."],"asset":{"type":"passage","lines":["따뜻한 코코아 컵 속에 차가운 우유 팩을 넣고 온도를 쟀다.","0분 — 코코아 50 °C · 우유 팩 10 °C","4분 — 코코아 40 °C · 우유 팩 22 °C","8분 — 코코아 34 °C · 우유 팩 28 °C","12분 — 코코아 31 °C · 우유 팩 31 °C"],"title":"② 첫날 저녁 — 코코아와 우유 팩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_a#19','sci',5,2,'u3','','g5_2_sci_u3_review_a','unit_review','SC5-2-u3-C13',3,'mc','auto','햇빛반 캠프 일지 ④에서 난로를 텐트 바닥 가까이에 둔 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X20','SC5-2-u3-X17','SC5-2-u3-X12']::text[],false,'{"seq":19,"concept":"SC5-2-u3-C13","difficulty":3,"kind":"mc","stem":"햇빛반 캠프 일지 ④에서 난로를 텐트 바닥 가까이에 둔 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"데워진 공기가 위로 올라가며 텐트 안 공기가 돌아 전체가 따뜻해지기 때문이다","correct":true},{"t":"데워진 공기가 바닥에 머물러 발만 데우기 때문이다","mis":"SC5-2-u3-X20"},{"t":"난로의 열이 땅을 따라 전도로만 가기 때문이다","mis":"SC5-2-u3-X17"},{"t":"텐트 위쪽에 냉기가 모이게 하려고","mis":"SC5-2-u3-X12"}],"explanation":["데워진 공기는 올라가요.","공기가 돌아요.","전체가 따뜻해요."],"asset":{"type":"passage","lines":["냄비에 물을 붓고 바닥만 가열하니 물이 위아래로 돌았다.","텐트 안 바닥 가까이에 난로를 두었더니 텐트 위쪽부터 따뜻해졌다.","선생님: 「난로는 꼭 어른과 함께, 환기도 잊지 말아요.」"],"title":"④ 둘째 날 — 냄비 물과 텐트 난로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_a#20','sci',5,2,'u3','','g5_2_sci_u3_review_a','unit_review','SC5-2-u3-C16',3,'mc','auto','모닥불에 냄비를 걸어 물을 끓이고 둘러앉아 불을 쬘 때, 공기가 거의 없어도 일어날 수 있는 열의 이동은 어느 것인가요?',ARRAY['SC5-2-u3-X28','SC5-2-u3-X25']::text[],false,'{"seq":20,"concept":"SC5-2-u3-C16","difficulty":3,"kind":"mc","stem":"모닥불에 냄비를 걸어 물을 끓이고 둘러앉아 불을 쬘 때, 공기가 거의 없어도 일어날 수 있는 열의 이동은 어느 것인가요?","options":[{"t":"둘러앉은 친구들 손이 불빛으로 따뜻해지는 것","correct":true},{"t":"냄비 속 물이 위아래로 도는 것","mis":"SC5-2-u3-X28"},{"t":"냄비 바닥에서 손잡이로 열이 가는 것","mis":"SC5-2-u3-X28"},{"t":"세 가지 모두 공기가 있어야만 일어난다","mis":"SC5-2-u3-X25"}],"explanation":["빛은 물질이 없어도 가요.","복사예요.","손을 쬐는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_a#21','sci',5,2,'u3','','g5_2_sci_u3_review_a','unit_review','SC5-2-u3-C20',3,'mc','auto','햇빛반 캠프 일지 ⑧에서 단열이 가장 잘된 장치는 어느 것인가요?',ARRAY['SC5-2-u3-X34']::text[],false,'{"seq":21,"concept":"SC5-2-u3-C20","difficulty":3,"kind":"mc","stem":"햇빛반 캠프 일지 ⑧에서 단열이 가장 잘된 장치는 어느 것인가요?","options":[{"t":"다","correct":true},{"t":"가","mis":"SC5-2-u3-X34"},{"t":"나","mis":"SC5-2-u3-X34"},{"t":"셋이 같다","mis":"SC5-2-u3-X34"}],"explanation":["덜 변해야 잘된 거예요.","다는 2 °C예요.","다예요."],"asset":{"type":"passage","lines":["같은 온도의 따뜻한 물을 세 장치에 넣고 30분 뒤 다시 쟀다.","가 — 뽁뽁이 두 겹, 뚜껑 덮음: 4 °C 낮아짐","나 — 신문지 한 겹, 뚜껑 없음: 15 °C 낮아짐","다 — 스타이로폼 상자, 뚜껑, 은박지: 2 °C 낮아짐","마지막 영상 — 인공 태양 연구 장치의 단열 이야기"],"title":"⑧ 마지막 날 — 장치 대회와 영상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_a#22','sci',5,2,'u3','','g5_2_sci_u3_review_a','unit_review','SC5-2-u3-C21',3,'mc','auto','햇빛반 캠프 일지 ⑧의 영상에서 인공 태양 연구 장치가 이중벽 안쪽을 은으로 도금한 까닭은 어느 것인가요?',ARRAY['SC5-2-u3-X36','SC5-2-u3-X32']::text[],false,'{"seq":22,"concept":"SC5-2-u3-C21","difficulty":3,"kind":"mc","stem":"햇빛반 캠프 일지 ⑧의 영상에서 인공 태양 연구 장치가 이중벽 안쪽을 은으로 도금한 까닭은 어느 것인가요?","options":[{"t":"빛을 되돌려 복사로 열이 이동하는 것을 막으려고","correct":true},{"t":"벽을 따라 오는 전도를 키우려고","mis":"SC5-2-u3-X36"},{"t":"공기 흐름을 막으려고","mis":"SC5-2-u3-X36"},{"t":"장치를 스스로 차갑게 하려고","mis":"SC5-2-u3-X32"}],"explanation":["은은 빛을 되돌려요.","빛으로 오는 열이에요.","복사를 막아요."],"asset":{"type":"passage","lines":["같은 온도의 따뜻한 물을 세 장치에 넣고 30분 뒤 다시 쟀다.","가 — 뽁뽁이 두 겹, 뚜껑 덮음: 4 °C 낮아짐","나 — 신문지 한 겹, 뚜껑 없음: 15 °C 낮아짐","다 — 스타이로폼 상자, 뚜껑, 은박지: 2 °C 낮아짐","마지막 영상 — 인공 태양 연구 장치의 단열 이야기"],"title":"⑧ 마지막 날 — 장치 대회와 영상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_a#23','sci',5,2,'u3','','g5_2_sci_u3_review_a','unit_review','SC5-2-u3-C6',4,'essay','teacher','햇빛반 캠프 일지 ②의 결과를 보고 코코아와 우유 팩의 온도가 어떻게 변했는지 쓰고, 그 까닭을 열의 이동 방향을 넣어 설명하세요.','{}'::text[],false,'{"seq":23,"concept":"SC5-2-u3-C6","difficulty":4,"kind":"essay","stem":"햇빛반 캠프 일지 ②의 결과를 보고 코코아와 우유 팩의 온도가 어떻게 변했는지 쓰고, 그 까닭을 열의 이동 방향을 넣어 설명하세요.","answer_guide":{"answer":"예: 코코아는 50 °C에서 점점 낮아지고 우유 팩은 10 °C에서 점점 높아져 12분에 31 °C로 같아졌다. 온도가 높은 코코아에서 온도가 낮은 우유 팩으로 열이 이동했기 때문이다.","scoring_points":["두 물체의 온도 변화를 썼는가","같아졌다는 것을 썼는가","높은 쪽에서 낮은 쪽으로 열이 이동한다고 썼는가"]},"explanation":["변화를 읽어요.","같아졌어요.","방향을 써요."],"asset":{"type":"passage","lines":["따뜻한 코코아 컵 속에 차가운 우유 팩을 넣고 온도를 쟀다.","0분 — 코코아 50 °C · 우유 팩 10 °C","4분 — 코코아 40 °C · 우유 팩 22 °C","8분 — 코코아 34 °C · 우유 팩 28 °C","12분 — 코코아 31 °C · 우유 팩 31 °C"],"title":"② 첫날 저녁 — 코코아와 우유 팩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_a#24','sci',5,2,'u3','','g5_2_sci_u3_review_a','unit_review','SC5-2-u3-C16',4,'essay','teacher','햇빛반 캠프 일지 ⑥의 화덕 피자에서 전도·대류·복사가 일어나는 곳을 하나씩 찾아 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-2-u3-C16","difficulty":4,"kind":"essay","stem":"햇빛반 캠프 일지 ⑥의 화덕 피자에서 전도·대류·복사가 일어나는 곳을 하나씩 찾아 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 전도 — 뜨거운 돌판에 닿은 피자 바닥으로 열이 고체를 따라 간다. 대류 — 화덕 안 뜨거운 공기가 돌며 피자를 데운다. 복사 — 벽과 불빛에서 빛에 의해 열이 피자로 온다.","scoring_points":["전도가 일어나는 곳을 바르게 찾았는가","대류가 일어나는 곳을 바르게 찾았는가","복사가 일어나는 곳을 바르게 찾았는가"]},"explanation":["돌판을 봐요.","공기를 봐요.","불빛을 봐요."],"asset":{"type":"passage","lines":["돌로 만든 화덕에 장작을 피우고 피자를 넣었다.","피자 바닥은 뜨거운 돌판에 닿아 있었다.","화덕 안 뜨거운 공기가 돌았고, 벽과 불빛도 피자를 데웠다."],"title":"⑥ 셋째 날 낮 — 화덕 피자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_a#25','sci',5,2,'u3','','g5_2_sci_u3_review_a','unit_review','SC5-2-u3-C20',4,'essay','teacher','햇빛반 캠프 일지 ⑧의 세 장치를 단열이 잘된 차례로 쓰고, 나 장치를 고칠 방법을 열의 이동과 함께 두 가지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-2-u3-C20","difficulty":4,"kind":"essay","stem":"햇빛반 캠프 일지 ⑧의 세 장치를 단열이 잘된 차례로 쓰고, 나 장치를 고칠 방법을 열의 이동과 함께 두 가지 쓰세요.","answer_guide":{"answer":"예: 다 → 가 → 나 차례로 단열이 잘되었다. 나 장치는 뚜껑을 덮어 공기가 드나들며 열이 빠져나가는 것(대류)을 막고, 신문지를 여러 겹 감싸거나 스타이로폼을 대어 통을 따라 빠져나가는 열(전도)을 줄인다.","scoring_points":["덜 변한 차례로 바르게 썼는가","고칠 방법 두 가지를 썼는가","각 방법이 막는 열의 이동을 썼는가"]},"explanation":["덜 변한 차례예요.","틈과 겹을 봐요.","막는 방식을 써요."],"asset":{"type":"passage","lines":["같은 온도의 따뜻한 물을 세 장치에 넣고 30분 뒤 다시 쟀다.","가 — 뽁뽁이 두 겹, 뚜껑 덮음: 4 °C 낮아짐","나 — 신문지 한 겹, 뚜껑 없음: 15 °C 낮아짐","다 — 스타이로폼 상자, 뚜껑, 은박지: 2 °C 낮아짐","마지막 영상 — 인공 태양 연구 장치의 단열 이야기"],"title":"⑧ 마지막 날 — 장치 대회와 영상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_b#1','sci',5,2,'u3','','g5_2_sci_u3_review_b','unit_review','SC5-2-u3-C2',1,'sa','auto','햇빛반 캠프 일지 ①에서 온도 숫자 뒤에 붙인 단위 °C는 무엇이라고 읽나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u3-C2","difficulty":1,"kind":"sa","stem":"햇빛반 캠프 일지 ①에서 온도 숫자 뒤에 붙인 단위 °C는 무엇이라고 읽나요? 세 글자로 쓰세요.","answer":["섭씨도"],"explanation":["°C는 단위예요.","세 글자예요.","섭씨도예요."],"asset":{"type":"passage","lines":["캠프 첫날, 이름표에 열 변색 붙임딱지를 붙였다. 손을 대면 색이 바뀌었다.","텐트 안 공기 — 알코올 온도계: 6.5 °C","물통 속 물 — 탐침 온도계: 12.0 °C","나무 의자 표면 — 적외선 온도계: 3.8 °C","모둠장 은찬: 「느낌 말고 숫자로 적자.」"],"title":"① 첫날 — 이름표와 온도 재기"},"mis":"SC5-2-u3-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_b#2','sci',5,2,'u3','','g5_2_sci_u3_review_b','unit_review','SC5-2-u3-C4',1,'ox','auto','온도를 정확하게 알려면 손 느낌보다 온도계로 재는 것이 좋아요.',ARRAY['SC5-2-u3-X04']::text[],false,'{"seq":2,"concept":"SC5-2-u3-C4","difficulty":1,"kind":"ox","stem":"온도를 정확하게 알려면 손 느낌보다 온도계로 재는 것이 좋아요.","answer":"O","reason_options":[{"t":"손 느낌은 사람마다 달라 정확하지 않기 때문에","correct":true},{"t":"손 느낌이 온도계보다 늘 정확하기 때문에","mis":"SC5-2-u3-X04"}],"mis":"SC5-2-u3-X04","explanation":["느낌은 사람마다 달라요.","숫자는 같아요.","온도계가 정확해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_b#3','sci',5,2,'u3','','g5_2_sci_u3_review_b','unit_review','SC5-2-u3-C5',1,'mc','auto','햇빛반 캠프 일지 ②에서 우유 팩의 온도는 어떻게 변했나요?',ARRAY['SC5-2-u3-X09','SC5-2-u3-X10']::text[],false,'{"seq":3,"concept":"SC5-2-u3-C5","difficulty":1,"kind":"mc","stem":"햇빛반 캠프 일지 ②에서 우유 팩의 온도는 어떻게 변했나요?","options":[{"t":"점점 높아졌다","correct":true},{"t":"점점 낮아졌다","mis":"SC5-2-u3-X09"},{"t":"변하지 않았다","mis":"SC5-2-u3-X09"},{"t":"코코아보다 더 높아졌다","mis":"SC5-2-u3-X10"}],"explanation":["10 °C에서 시작해요.","31 °C까지 올라요.","높아졌어요."],"asset":{"type":"passage","lines":["따뜻한 코코아 컵 속에 차가운 우유 팩을 넣고 온도를 쟀다.","0분 — 코코아 50 °C · 우유 팩 10 °C","4분 — 코코아 40 °C · 우유 팩 22 °C","8분 — 코코아 34 °C · 우유 팩 28 °C","12분 — 코코아 31 °C · 우유 팩 31 °C"],"title":"② 첫날 저녁 — 코코아와 우유 팩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_b#4','sci',5,2,'u3','','g5_2_sci_u3_review_b','unit_review','SC5-2-u3-C7',1,'mc','auto','햇빛반 캠프 일지 ③에서 버터가 녹은 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X14','SC5-2-u3-X16']::text[],false,'{"seq":4,"concept":"SC5-2-u3-C7","difficulty":1,"kind":"mc","stem":"햇빛반 캠프 일지 ③에서 버터가 녹은 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"한가운데 → 가장자리","correct":true},{"t":"가장자리 → 한가운데","mis":"SC5-2-u3-X14"},{"t":"한꺼번에","mis":"SC5-2-u3-X14"},{"t":"녹지 않았다","mis":"SC5-2-u3-X16"}],"explanation":["불은 한가운데예요.","가까운 곳부터요.","가장자리가 나중이에요."],"asset":{"type":"passage","lines":["아침에 넓은 철판 한가운데 아래에만 불을 켜고 버터를 올렸다.","한가운데 버터가 먼저 녹고, 가장자리 버터는 나중에 녹았다.","요리사님은 쇠 주걱 대신 나무 주걱을 손에 쥐었다."],"title":"③ 둘째 날 아침 — 철판 구이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_b#5','sci',5,2,'u3','','g5_2_sci_u3_review_b','unit_review','SC5-2-u3-C13',1,'mc','auto','햇빛반 캠프 일지 ④에서 텐트 위쪽부터 따뜻해진 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X20','SC5-2-u3-X12','SC5-2-u3-X22']::text[],false,'{"seq":5,"concept":"SC5-2-u3-C13","difficulty":1,"kind":"mc","stem":"햇빛반 캠프 일지 ④에서 텐트 위쪽부터 따뜻해진 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"난로에 데워진 공기가 위로 올라가서","correct":true},{"t":"데워진 공기가 바닥으로 내려가서","mis":"SC5-2-u3-X20"},{"t":"난로의 냉기가 위로 가서","mis":"SC5-2-u3-X12"},{"t":"공기는 움직이지 않고 열만 가서","mis":"SC5-2-u3-X22"}],"explanation":["난로가 공기를 데워요.","데워진 공기는 올라가요.","위가 먼저예요."],"asset":{"type":"passage","lines":["냄비에 물을 붓고 바닥만 가열하니 물이 위아래로 돌았다.","텐트 안 바닥 가까이에 난로를 두었더니 텐트 위쪽부터 따뜻해졌다.","선생님: 「난로는 꼭 어른과 함께, 환기도 잊지 말아요.」"],"title":"④ 둘째 날 — 냄비 물과 텐트 난로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_b#6','sci',5,2,'u3','','g5_2_sci_u3_review_b','unit_review','SC5-2-u3-C15',1,'sa','auto','빛에 의해 열이 이동하는 방식을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"SC5-2-u3-C15","difficulty":1,"kind":"sa","stem":"빛에 의해 열이 이동하는 방식을 두 글자로 쓰세요.","answer":["복사"],"explanation":["빛이 열을 옮겨요.","두 글자예요.","복사예요."],"mis":"SC5-2-u3-X25"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_b#7','sci',5,2,'u3','','g5_2_sci_u3_review_b','unit_review','SC5-2-u3-C17',1,'sa','auto','보온병·아이스박스처럼 열의 이동을 막는 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SC5-2-u3-C17","difficulty":1,"kind":"sa","stem":"보온병·아이스박스처럼 열의 이동을 막는 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["단열"],"explanation":["열을 막아요.","두 글자예요.","단열이에요."],"mis":"SC5-2-u3-X30"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_b#8','sci',5,2,'u3','','g5_2_sci_u3_review_b','unit_review','SC5-2-u3-C21',1,'mc','auto','인공 태양 연구 장치가 단열하는 방법과 닮은 생활 물건은 어느 것인가요?',ARRAY['SC5-2-u3-X35']::text[],false,'{"seq":8,"concept":"SC5-2-u3-C21","difficulty":1,"kind":"mc","stem":"인공 태양 연구 장치가 단열하는 방법과 닮은 생활 물건은 어느 것인가요?","options":[{"t":"보온병","correct":true},{"t":"프라이팬","mis":"SC5-2-u3-X35"},{"t":"전기 주전자","mis":"SC5-2-u3-X35"},{"t":"금속 숟가락","mis":"SC5-2-u3-X35"}],"explanation":["이중벽이 있어요.","공기를 빼요.","보온병이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_b#9','sci',5,2,'u3','','g5_2_sci_u3_review_b','unit_review','SC5-2-u3-C2',2,'mc','auto','6.5 °C를 바르게 읽은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X05']::text[],false,'{"seq":9,"concept":"SC5-2-u3-C2","difficulty":2,"kind":"mc","stem":"6.5 °C를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"섭씨 육 점 오 도","correct":true},{"t":"육 점 오 도씨","mis":"SC5-2-u3-X05"},{"t":"육십오 도","mis":"SC5-2-u3-X05"},{"t":"섭씨 육 도 오","mis":"SC5-2-u3-X05"}],"explanation":["°C는 섭씨도예요.","점을 읽어요.","섭씨 육 점 오 도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_b#10','sci',5,2,'u3','','g5_2_sci_u3_review_b','unit_review','SC5-2-u3-C5',2,'mc','auto','햇빛반 캠프 일지 ②에서 우유 팩의 온도가 가장 많이 오른 때는 언제인가요?',ARRAY['SC5-2-u3-X13']::text[],false,'{"seq":10,"concept":"SC5-2-u3-C5","difficulty":2,"kind":"mc","stem":"햇빛반 캠프 일지 ②에서 우유 팩의 온도가 가장 많이 오른 때는 언제인가요?","options":[{"t":"0분과 4분 사이","correct":true},{"t":"4분과 8분 사이","mis":"SC5-2-u3-X13"},{"t":"8분과 12분 사이","mis":"SC5-2-u3-X13"},{"t":"어느 때나 같다","mis":"SC5-2-u3-X13"}],"explanation":["처음에 크게 올라요.","12 °C 올랐어요.","0분과 4분 사이예요."],"asset":{"type":"passage","lines":["따뜻한 코코아 컵 속에 차가운 우유 팩을 넣고 온도를 쟀다.","0분 — 코코아 50 °C · 우유 팩 10 °C","4분 — 코코아 40 °C · 우유 팩 22 °C","8분 — 코코아 34 °C · 우유 팩 28 °C","12분 — 코코아 31 °C · 우유 팩 31 °C"],"title":"② 첫날 저녁 — 코코아와 우유 팩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_b#11','sci',5,2,'u3','','g5_2_sci_u3_review_b','unit_review','SC5-2-u3-C6',2,'ox','auto','눈을 맨손으로 뭉치면 눈의 냉기가 손으로 들어와 손이 차가워져요.',ARRAY['SC5-2-u3-X12']::text[],false,'{"seq":11,"concept":"SC5-2-u3-C6","difficulty":2,"kind":"ox","stem":"눈을 맨손으로 뭉치면 눈의 냉기가 손으로 들어와 손이 차가워져요.","answer":"X","reason_options":[{"t":"손의 열이 눈으로 이동해 손의 온도가 낮아지기 때문에","correct":true},{"t":"차가운 기운은 손 쪽으로 옮겨 가기 때문에","mis":"SC5-2-u3-X12"}],"mis":"SC5-2-u3-X12","explanation":["손이 더 따뜻해요.","열이 눈으로 가요.","그래서 차가워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_b#12','sci',5,2,'u3','','g5_2_sci_u3_review_b','unit_review','SC5-2-u3-C9',2,'mc','auto','햇빛반 캠프 일지 ③에서 요리사님이 나무 주걱을 쥔 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X18','SC5-2-u3-X12','SC5-2-u3-X32']::text[],false,'{"seq":12,"concept":"SC5-2-u3-C9","difficulty":2,"kind":"mc","stem":"햇빛반 캠프 일지 ③에서 요리사님이 나무 주걱을 쥔 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나무는 열이 잘 이동하지 않아 손이 덜 뜨겁기 때문이다","correct":true},{"t":"나무가 열을 빨리 전해 요리가 잘되기 때문이다","mis":"SC5-2-u3-X18"},{"t":"쇠 주걱의 냉기가 손을 다치게 하기 때문이다","mis":"SC5-2-u3-X12"},{"t":"나무 주걱이 스스로 차가워지기 때문이다","mis":"SC5-2-u3-X32"}],"explanation":["철판은 뜨거워요.","나무는 열이 잘 안 가요.","손을 지켜요."],"asset":{"type":"passage","lines":["아침에 넓은 철판 한가운데 아래에만 불을 켜고 버터를 올렸다.","한가운데 버터가 먼저 녹고, 가장자리 버터는 나중에 녹았다.","요리사님은 쇠 주걱 대신 나무 주걱을 손에 쥐었다."],"title":"③ 둘째 날 아침 — 철판 구이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_b#13','sci',5,2,'u3','','g5_2_sci_u3_review_b','unit_review','SC5-2-u3-C12',2,'mc','auto','햇빛반 캠프 일지 ④의 냄비 물과 텐트 공기에서 공통으로 일어난 것은 어느 것인가요?',ARRAY['SC5-2-u3-X17','SC5-2-u3-X20','SC5-2-u3-X22']::text[],false,'{"seq":13,"concept":"SC5-2-u3-C12","difficulty":2,"kind":"mc","stem":"햇빛반 캠프 일지 ④의 냄비 물과 텐트 공기에서 공통으로 일어난 것은 어느 것인가요?","options":[{"t":"데워진 물질이 위로 올라가며 열이 이동했다","correct":true},{"t":"고체를 따라 열이 이동했다","mis":"SC5-2-u3-X17"},{"t":"데워진 물질이 아래로 내려갔다","mis":"SC5-2-u3-X20"},{"t":"물질은 가만히 있고 열만 이동했다","mis":"SC5-2-u3-X22"}],"explanation":["물도 공기도 움직여요.","데워지면 올라가요.","대류예요."],"asset":{"type":"passage","lines":["냄비에 물을 붓고 바닥만 가열하니 물이 위아래로 돌았다.","텐트 안 바닥 가까이에 난로를 두었더니 텐트 위쪽부터 따뜻해졌다.","선생님: 「난로는 꼭 어른과 함께, 환기도 잊지 말아요.」"],"title":"④ 둘째 날 — 냄비 물과 텐트 난로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_b#14','sci',5,2,'u3','','g5_2_sci_u3_review_b','unit_review','SC5-2-u3-C15',2,'mc','auto','햇빛반 캠프 일지 ⑤에서 모닥불 앞 얼굴은 뜨겁고 등은 차가운 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X12','SC5-2-u3-X26','SC5-2-u3-X27']::text[],false,'{"seq":14,"concept":"SC5-2-u3-C15","difficulty":2,"kind":"mc","stem":"햇빛반 캠프 일지 ⑤에서 모닥불 앞 얼굴은 뜨겁고 등은 차가운 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"불을 향한 얼굴 쪽만 불빛을 받아 복사로 열이 오기 때문이다","correct":true},{"t":"등 쪽으로 냉기가 오기 때문이다","mis":"SC5-2-u3-X12"},{"t":"얼굴이 불에 닿아 전도되기 때문이다","mis":"SC5-2-u3-X26"},{"t":"복사는 한 상황에서만 일어나기 때문이다","mis":"SC5-2-u3-X27"}],"explanation":["얼굴은 불을 향해요.","빛을 받아요.","복사예요."],"asset":{"type":"passage","lines":["같은 온도의 검은 장갑 두 짝 가운데 한 짝은 햇빛, 한 짝은 그늘에 두었다.","30분 뒤 햇빛에 둔 장갑이 더 따뜻했다.","밤에는 모닥불 앞에 앉았더니 얼굴은 뜨겁고 등은 차가웠다."],"title":"⑤ 둘째 날 오후와 밤 — 햇빛과 모닥불"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_b#15','sci',5,2,'u3','','g5_2_sci_u3_review_b','unit_review','SC5-2-u3-C16',2,'mc','auto','햇빛반 캠프 일지 ⑥에서 화덕 안 뜨거운 공기가 돌며 피자를 데우는 방식은 어느 것인가요?',ARRAY['SC5-2-u3-X17','SC5-2-u3-X26','SC5-2-u3-X28']::text[],false,'{"seq":15,"concept":"SC5-2-u3-C16","difficulty":2,"kind":"mc","stem":"햇빛반 캠프 일지 ⑥에서 화덕 안 뜨거운 공기가 돌며 피자를 데우는 방식은 어느 것인가요?","options":[{"t":"대류","correct":true},{"t":"전도","mis":"SC5-2-u3-X17"},{"t":"복사","mis":"SC5-2-u3-X26"},{"t":"증발","mis":"SC5-2-u3-X28"}],"explanation":["공기가 움직여요.","돌며 데워요.","대류예요."],"asset":{"type":"passage","lines":["돌로 만든 화덕에 장작을 피우고 피자를 넣었다.","피자 바닥은 뜨거운 돌판에 닿아 있었다.","화덕 안 뜨거운 공기가 돌았고, 벽과 불빛도 피자를 데웠다."],"title":"⑥ 셋째 날 낮 — 화덕 피자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_b#16','sci',5,2,'u3','','g5_2_sci_u3_review_b','unit_review','SC5-2-u3-C18',2,'mc','auto','겹겹이 입은 옷이 따뜻한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X32','SC5-2-u3-X12','SC5-2-u3-X30']::text[],false,'{"seq":16,"concept":"SC5-2-u3-C18","difficulty":2,"kind":"mc","stem":"겹겹이 입은 옷이 따뜻한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"옷 사이 공기층이 몸의 열이 빠져나가는 것을 막아서","correct":true},{"t":"옷이 스스로 열을 만들어서","mis":"SC5-2-u3-X32"},{"t":"옷이 바깥 냉기를 빨아들여서","mis":"SC5-2-u3-X12"},{"t":"옷을 겹치면 열이 더 잘 빠져나가서","mis":"SC5-2-u3-X30"}],"explanation":["옷 사이에 공기가 있어요.","열이 덜 나가요.","따뜻해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_b#17','sci',5,2,'u3','','g5_2_sci_u3_review_b','unit_review','SC5-2-u3-C3',3,'error','auto','햇빛반 캠프 일지 ①처럼 온도를 재며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u3-X06','SC5-2-u3-X07']::text[],false,'{"seq":17,"concept":"SC5-2-u3-C3","difficulty":3,"kind":"error","stem":"햇빛반 캠프 일지 ①처럼 온도를 재며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"재희 — 「적외선 온도계로 친구 눈을 겨누어 체온을 재 보자.」","correct":true,"mis_target":"SC5-2-u3-X06"},{"t":"은찬 — 「알코올 온도계는 눈높이에서 읽자.」","mis":"SC5-2-u3-X06"},{"t":"나래 — 「물통 속은 탐침 온도계로 재자.」","mis":"SC5-2-u3-X07"}],"explanation":["적외선은 눈을 피해요.","안전 수칙이에요.","재희의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["캠프 첫날, 이름표에 열 변색 붙임딱지를 붙였다. 손을 대면 색이 바뀌었다.","텐트 안 공기 — 알코올 온도계: 6.5 °C","물통 속 물 — 탐침 온도계: 12.0 °C","나무 의자 표면 — 적외선 온도계: 3.8 °C","모둠장 은찬: 「느낌 말고 숫자로 적자.」"],"title":"① 첫날 — 이름표와 온도 재기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_b#18','sci',5,2,'u3','','g5_2_sci_u3_review_b','unit_review','SC5-2-u3-C5',3,'mc','auto','햇빛반 캠프 일지 ②에서 4분과 8분 사이 코코아가 내려간 만큼과 우유 팩이 오른 만큼을 견주면 어느 것인가요?',ARRAY['SC5-2-u3-X13','SC5-2-u3-X09']::text[],false,'{"seq":18,"concept":"SC5-2-u3-C5","difficulty":3,"kind":"mc","stem":"햇빛반 캠프 일지 ②에서 4분과 8분 사이 코코아가 내려간 만큼과 우유 팩이 오른 만큼을 견주면 어느 것인가요?","options":[{"t":"코코아 6 °C 내려가고 우유 팩 6 °C 올랐다","correct":true},{"t":"코코아 10 °C 내려가고 우유 팩 12 °C 올랐다","mis":"SC5-2-u3-X13"},{"t":"코코아 3 °C 내려가고 우유 팩 3 °C 올랐다","mis":"SC5-2-u3-X13"},{"t":"코코아는 그대로이고 우유 팩만 올랐다","mis":"SC5-2-u3-X09"}],"explanation":["40에서 34로 내려가요.","22에서 28로 올라가요.","둘 다 6 °C예요."],"asset":{"type":"passage","lines":["따뜻한 코코아 컵 속에 차가운 우유 팩을 넣고 온도를 쟀다.","0분 — 코코아 50 °C · 우유 팩 10 °C","4분 — 코코아 40 °C · 우유 팩 22 °C","8분 — 코코아 34 °C · 우유 팩 28 °C","12분 — 코코아 31 °C · 우유 팩 31 °C"],"title":"② 첫날 저녁 — 코코아와 우유 팩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_b#19','sci',5,2,'u3','','g5_2_sci_u3_review_b','unit_review','SC5-2-u3-C12',3,'error','auto','햇빛반 캠프 일지 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u3-X22','SC5-2-u3-X20','SC5-2-u3-X17']::text[],false,'{"seq":19,"concept":"SC5-2-u3-C12","difficulty":3,"kind":"error","stem":"햇빛반 캠프 일지 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"소율 — 「냄비 물은 가만히 있고 열만 위로 올라가.」","correct":true,"mis_target":"SC5-2-u3-X22"},{"t":"하람 — 「바닥 물이 데워져 올라가고 위 물이 내려와.」","mis":"SC5-2-u3-X20"},{"t":"시안 — 「텐트 공기도 물처럼 돌며 데워져.」","mis":"SC5-2-u3-X17"}],"explanation":["물이 직접 움직여요.","대류예요.","소율의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["냄비에 물을 붓고 바닥만 가열하니 물이 위아래로 돌았다.","텐트 안 바닥 가까이에 난로를 두었더니 텐트 위쪽부터 따뜻해졌다.","선생님: 「난로는 꼭 어른과 함께, 환기도 잊지 말아요.」"],"title":"④ 둘째 날 — 냄비 물과 텐트 난로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_b#20','sci',5,2,'u3','','g5_2_sci_u3_review_b','unit_review','SC5-2-u3-C16',3,'error','auto','햇빛반 캠프 일지 ⑥을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u3-X27','SC5-2-u3-X28','SC5-2-u3-X26']::text[],false,'{"seq":20,"concept":"SC5-2-u3-C16","difficulty":3,"kind":"error","stem":"햇빛반 캠프 일지 ⑥을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"리온 — 「피자는 돌판에 닿아 있으니 전도 한 가지로만 익어.」","correct":true,"mis_target":"SC5-2-u3-X27"},{"t":"다은 — 「뜨거운 공기가 돌며 대류로도 데워.」","mis":"SC5-2-u3-X28"},{"t":"준혁 — 「벽과 불빛에서 복사로도 열이 와.」","mis":"SC5-2-u3-X26"}],"explanation":["세 방식이 함께예요.","한 가지가 아니에요.","리온의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["돌로 만든 화덕에 장작을 피우고 피자를 넣었다.","피자 바닥은 뜨거운 돌판에 닿아 있었다.","화덕 안 뜨거운 공기가 돌았고, 벽과 불빛도 피자를 데웠다."],"title":"⑥ 셋째 날 낮 — 화덕 피자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_b#21','sci',5,2,'u3','','g5_2_sci_u3_review_b','unit_review','SC5-2-u3-C20',3,'mc','auto','햇빛반 캠프 일지 ⑧에서 나 장치의 물이 가장 많이 식은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X32','SC5-2-u3-X33','SC5-2-u3-X34']::text[],false,'{"seq":21,"concept":"SC5-2-u3-C20","difficulty":3,"kind":"mc","stem":"햇빛반 캠프 일지 ⑧에서 나 장치의 물이 가장 많이 식은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"단열재가 얇고 뚜껑이 없어 열이 빠져나갈 길이 많았기 때문이다","correct":true},{"t":"신문지가 물을 차갑게 만들었기 때문이다","mis":"SC5-2-u3-X32"},{"t":"뚜껑이 없으면 열이 들어오기 때문이다","mis":"SC5-2-u3-X33"},{"t":"물을 가장 많이 넣었기 때문이다","mis":"SC5-2-u3-X34"}],"explanation":["한 겹뿐이에요.","뚜껑도 없어요.","열이 많이 나갔어요."],"asset":{"type":"passage","lines":["같은 온도의 따뜻한 물을 세 장치에 넣고 30분 뒤 다시 쟀다.","가 — 뽁뽁이 두 겹, 뚜껑 덮음: 4 °C 낮아짐","나 — 신문지 한 겹, 뚜껑 없음: 15 °C 낮아짐","다 — 스타이로폼 상자, 뚜껑, 은박지: 2 °C 낮아짐","마지막 영상 — 인공 태양 연구 장치의 단열 이야기"],"title":"⑧ 마지막 날 — 장치 대회와 영상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_b#22','sci',5,2,'u3','','g5_2_sci_u3_review_b','unit_review','SC5-2-u3-C21',3,'mc','auto','공기가 거의 없는 우주에서 태양 가까이 가는 우주선이 가장 크게 막아야 할 열의 이동 방식은 어느 것인가요?',ARRAY['SC5-2-u3-X36','SC5-2-u3-X35']::text[],false,'{"seq":22,"concept":"SC5-2-u3-C21","difficulty":3,"kind":"mc","stem":"공기가 거의 없는 우주에서 태양 가까이 가는 우주선이 가장 크게 막아야 할 열의 이동 방식은 어느 것인가요?","options":[{"t":"복사","correct":true},{"t":"대류","mis":"SC5-2-u3-X36"},{"t":"전도만","mis":"SC5-2-u3-X36"},{"t":"막을 필요가 없다","mis":"SC5-2-u3-X35"}],"explanation":["공기가 거의 없어요.","태양 열은 빛으로 와요.","복사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_b#23','sci',5,2,'u3','','g5_2_sci_u3_review_b','unit_review','SC5-2-u3-C6',4,'essay','teacher','「눈을 뭉치면 눈의 냉기가 손으로 들어온다.」는 말을 열의 이동으로 바르게 고치고, 눈은 어떻게 되는지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SC5-2-u3-C6","difficulty":4,"kind":"essay","stem":"「눈을 뭉치면 눈의 냉기가 손으로 들어온다.」는 말을 열의 이동으로 바르게 고치고, 눈은 어떻게 되는지 쓰세요.","answer_guide":{"answer":"예: 손이 눈보다 온도가 높아 손의 열이 눈으로 이동하므로 손의 온도가 낮아져 차갑게 느껴진다. 눈은 열을 받아 온도가 높아지며 녹는다.","scoring_points":["어느 쪽이 더 따뜻한지 썼는가","손에서 눈으로 열이 간다고 썼는가","눈이 열을 받아 녹는다고 썼는가"]},"explanation":["손이 더 따뜻해요.","열이 눈으로 가요.","눈이 녹아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_b#24','sci',5,2,'u3','','g5_2_sci_u3_review_b','unit_review','SC5-2-u3-C16',4,'essay','teacher','캠프에서 겪을 수 있는 일 가운데 전도와 복사가 함께 일어나는 장면을 하나 생각해 쓰고, 각각 어디에서 일어나는지 설명하세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-2-u3-C16","difficulty":4,"kind":"essay","stem":"캠프에서 겪을 수 있는 일 가운데 전도와 복사가 함께 일어나는 장면을 하나 생각해 쓰고, 각각 어디에서 일어나는지 설명하세요.","answer_guide":{"answer":"예: 모닥불 옆 쇠 꼬챙이에 마시멜로를 구울 때, 꼬챙이를 따라 손잡이 쪽으로 열이 오는 것은 전도이고, 불빛에 얼굴과 마시멜로가 따뜻해지는 것은 복사이다.","scoring_points":["장면을 구체적으로 썼는가","전도가 일어나는 곳을 썼는가","복사가 일어나는 곳을 썼는가"]},"explanation":["장면을 떠올려요.","고체를 따라가요.","빛으로 와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_b#25','sci',5,2,'u3','','g5_2_sci_u3_review_b','unit_review','SC5-2-u3-C19',4,'essay','teacher','캠프에서 산 따끈한 군고구마를 집까지 따뜻하게 가져가는 장치를 설계하세요. 단열재와 만드는 방법, 온도를 지키는지 확인하는 방법을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-2-u3-C19","difficulty":4,"kind":"essay","stem":"캠프에서 산 따끈한 군고구마를 집까지 따뜻하게 가져가는 장치를 설계하세요. 단열재와 만드는 방법, 온도를 지키는지 확인하는 방법을 쓰세요.","answer_guide":{"answer":"예: 뚜껑 있는 통 안쪽을 스타이로폼으로 대고 겉을 뽁뽁이로 두 겹 감싼 뒤 뚜껑 둘레를 테이프로 막는다. 군고구마를 넣고 10분마다 통 안 온도를 재어 오래 일정하게 유지되는지 확인한다.","scoring_points":["알맞은 단열재를 골랐는가","겹치고 틈을 막는 방법을 썼는가","시간 간격을 두고 온도를 재는 확인 방법을 썼는가"]},"explanation":["단열재를 골라요.","틈을 막아요.","시간마다 재요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_c#1','sci',5,2,'u3','','g5_2_sci_u3_review_c','unit_review','SC5-2-u3-C1',1,'ox','auto','열 변색 붙임딱지 이름표는 손을 떼고 시간이 지나면 처음 색으로 돌아와요.',ARRAY['SC5-2-u3-X02']::text[],false,'{"seq":1,"concept":"SC5-2-u3-C1","difficulty":1,"kind":"ox","stem":"열 변색 붙임딱지 이름표는 손을 떼고 시간이 지나면 처음 색으로 돌아와요.","answer":"O","reason_options":[{"t":"손의 따뜻함이 사라지기 때문에","correct":true},{"t":"한 번 바뀐 색은 그대로 남기 때문에","mis":"SC5-2-u3-X02"}],"mis":"SC5-2-u3-X02","explanation":["손을 떼요.","따뜻함이 사라져요.","처음 색으로 와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_c#2','sci',5,2,'u3','','g5_2_sci_u3_review_c','unit_review','SC5-2-u3-C3',1,'mc','auto','물통 속 물에 넣어 온도를 재기 알맞은 온도계는 어느 것인가요?',ARRAY['SC5-2-u3-X08']::text[],false,'{"seq":2,"concept":"SC5-2-u3-C3","difficulty":1,"kind":"mc","stem":"물통 속 물에 넣어 온도를 재기 알맞은 온도계는 어느 것인가요?","options":[{"t":"탐침 온도계","correct":true},{"t":"자","mis":"SC5-2-u3-X08"},{"t":"저울","mis":"SC5-2-u3-X08"},{"t":"나침반","mis":"SC5-2-u3-X08"}],"explanation":["물속에 넣어요.","탐침을 넣어요.","탐침 온도계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_c#3','sci',5,2,'u3','','g5_2_sci_u3_review_c','unit_review','SC5-2-u3-C6',1,'ox','auto','열은 온도가 높은 물체에서 온도가 낮은 물체로 이동해요.',ARRAY['SC5-2-u3-X11']::text[],false,'{"seq":3,"concept":"SC5-2-u3-C6","difficulty":1,"kind":"ox","stem":"열은 온도가 높은 물체에서 온도가 낮은 물체로 이동해요.","answer":"O","reason_options":[{"t":"온도가 다른 두 물체가 닿으면 높은 쪽에서 낮은 쪽으로 가기 때문에","correct":true},{"t":"온도가 낮은 쪽이 열을 내주기 때문에","mis":"SC5-2-u3-X11"}],"mis":"SC5-2-u3-X11","explanation":["온도를 견줘요.","높은 쪽에서 나가요.","낮은 쪽으로 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_c#4','sci',5,2,'u3','','g5_2_sci_u3_review_c','unit_review','SC5-2-u3-C9',1,'ox','auto','나무 주걱은 쇠 주걱보다 손이 덜 뜨거워요.',ARRAY['SC5-2-u3-X18']::text[],false,'{"seq":4,"concept":"SC5-2-u3-C9","difficulty":1,"kind":"ox","stem":"나무 주걱은 쇠 주걱보다 손이 덜 뜨거워요.","answer":"O","reason_options":[{"t":"나무는 열이 잘 이동하지 않기 때문에","correct":true},{"t":"나무가 열을 더 빨리 손으로 전하기 때문에","mis":"SC5-2-u3-X18"}],"mis":"SC5-2-u3-X18","explanation":["나무는 열이 잘 안 가요.","손으로 덜 와요.","덜 뜨거워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_c#5','sci',5,2,'u3','','g5_2_sci_u3_review_c','unit_review','SC5-2-u3-C12',1,'ox','auto','데워진 물은 위로 올라가고 차가운 물은 아래로 내려와요.',ARRAY['SC5-2-u3-X20']::text[],false,'{"seq":5,"concept":"SC5-2-u3-C12","difficulty":1,"kind":"ox","stem":"데워진 물은 위로 올라가고 차가운 물은 아래로 내려와요.","answer":"O","reason_options":[{"t":"대류로 물이 위아래로 돌기 때문에","correct":true},{"t":"데워진 물이 아래로 가라앉기 때문에","mis":"SC5-2-u3-X20"}],"mis":"SC5-2-u3-X20","explanation":["데워지면 올라가요.","차가우면 내려와요.","돌며 데워져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_c#6','sci',5,2,'u3','','g5_2_sci_u3_review_c','unit_review','SC5-2-u3-C14',1,'ox','auto','햇빛반 캠프 일지 ⑤에서 햇빛에 둔 장갑이 그늘 장갑보다 더 따뜻해졌어요.',ARRAY['SC5-2-u3-X24']::text[],false,'{"seq":6,"concept":"SC5-2-u3-C14","difficulty":1,"kind":"ox","stem":"햇빛반 캠프 일지 ⑤에서 햇빛에 둔 장갑이 그늘 장갑보다 더 따뜻해졌어요.","answer":"O","reason_options":[{"t":"햇빛을 받아 빛에 의해 열이 왔기 때문에","correct":true},{"t":"그늘 장갑이 냉기를 받았기 때문에","mis":"SC5-2-u3-X24"}],"mis":"SC5-2-u3-X24","explanation":["햇빛을 받았어요.","빛이 열을 옮겨요.","더 따뜻해요."],"asset":{"type":"passage","lines":["같은 온도의 검은 장갑 두 짝 가운데 한 짝은 햇빛, 한 짝은 그늘에 두었다.","30분 뒤 햇빛에 둔 장갑이 더 따뜻했다.","밤에는 모닥불 앞에 앉았더니 얼굴은 뜨겁고 등은 차가웠다."],"title":"⑤ 둘째 날 오후와 밤 — 햇빛과 모닥불"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_c#7','sci',5,2,'u3','','g5_2_sci_u3_review_c','unit_review','SC5-2-u3-C18',1,'ox','auto','두꺼운 침낭은 몸의 열이 빠져나가는 것을 막아 줘요.',ARRAY['SC5-2-u3-X32']::text[],false,'{"seq":7,"concept":"SC5-2-u3-C18","difficulty":1,"kind":"ox","stem":"두꺼운 침낭은 몸의 열이 빠져나가는 것을 막아 줘요.","answer":"O","reason_options":[{"t":"침낭이 열의 이동을 막는 단열을 하기 때문에","correct":true},{"t":"침낭이 스스로 열을 만들어 내기 때문에","mis":"SC5-2-u3-X32"}],"mis":"SC5-2-u3-X32","explanation":["몸이 더 따뜻해요.","열이 나가려 해요.","침낭이 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_c#8','sci',5,2,'u3','','g5_2_sci_u3_review_c','unit_review','SC5-2-u3-C21',1,'ox','auto','단열 기술은 첨단 과학 기술에서도 중요하게 쓰여요.',ARRAY['SC5-2-u3-X35']::text[],false,'{"seq":8,"concept":"SC5-2-u3-C21","difficulty":1,"kind":"ox","stem":"단열 기술은 첨단 과학 기술에서도 중요하게 쓰여요.","answer":"O","reason_options":[{"t":"인공 태양 연구 장치·우주선 같은 곳에서도 열을 막아야 하기 때문에","correct":true},{"t":"단열은 생활 물건에만 쓰이기 때문에","mis":"SC5-2-u3-X35"}],"mis":"SC5-2-u3-X35","explanation":["생활에도 써요.","첨단 기술에도 써요.","중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_c#9','sci',5,2,'u3','','g5_2_sci_u3_review_c','unit_review','SC5-2-u3-C4',2,'mc','auto','「텐트 안이 춥다」는 느낌 대신 6.5 °C라고 적으면 좋은 점은 어느 것인가요?',ARRAY['SC5-2-u3-X08','SC5-2-u3-X04']::text[],false,'{"seq":9,"concept":"SC5-2-u3-C4","difficulty":2,"kind":"mc","stem":"「텐트 안이 춥다」는 느낌 대신 6.5 °C라고 적으면 좋은 점은 어느 것인가요?","options":[{"t":"얼마나 추운지 누구에게나 같게 전할 수 있다","correct":true},{"t":"텐트가 덜 추워진다","mis":"SC5-2-u3-X08"},{"t":"느낌이 숫자보다 정확해진다","mis":"SC5-2-u3-X04"},{"t":"사람마다 다르게 알 수 있다","mis":"SC5-2-u3-X04"}],"explanation":["느낌은 달라요.","숫자는 같아요.","같게 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_c#10','sci',5,2,'u3','','g5_2_sci_u3_review_c','unit_review','SC5-2-u3-C5',2,'ox','auto','햇빛반 캠프 일지 ②에서 12분 뒤에도 그대로 두면 우유 팩이 코코아보다 뜨거워져요.',ARRAY['SC5-2-u3-X10']::text[],false,'{"seq":10,"concept":"SC5-2-u3-C5","difficulty":2,"kind":"ox","stem":"햇빛반 캠프 일지 ②에서 12분 뒤에도 그대로 두면 우유 팩이 코코아보다 뜨거워져요.","answer":"X","reason_options":[{"t":"두 온도가 같아지면 더 이상 열이 이동하지 않기 때문에","correct":true},{"t":"우유 팩이 계속 열을 받아 더 높아지기 때문에","mis":"SC5-2-u3-X10"}],"mis":"SC5-2-u3-X10","explanation":["31 °C로 같아요.","이동이 멈춰요.","뒤바뀌지 않아요."],"asset":{"type":"passage","lines":["따뜻한 코코아 컵 속에 차가운 우유 팩을 넣고 온도를 쟀다.","0분 — 코코아 50 °C · 우유 팩 10 °C","4분 — 코코아 40 °C · 우유 팩 22 °C","8분 — 코코아 34 °C · 우유 팩 28 °C","12분 — 코코아 31 °C · 우유 팩 31 °C"],"title":"② 첫날 저녁 — 코코아와 우유 팩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_c#11','sci',5,2,'u3','','g5_2_sci_u3_review_c','unit_review','SC5-2-u3-C6',2,'mc','auto','따뜻한 손으로 눈사람을 오래 만지면 눈사람이 녹는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X12','SC5-2-u3-X11','SC5-2-u3-X09']::text[],false,'{"seq":11,"concept":"SC5-2-u3-C6","difficulty":2,"kind":"mc","stem":"따뜻한 손으로 눈사람을 오래 만지면 눈사람이 녹는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"손의 열이 눈사람으로 이동해 눈사람의 온도가 높아지기 때문이다","correct":true},{"t":"눈사람의 냉기가 손으로 빠져나가기 때문이다","mis":"SC5-2-u3-X12"},{"t":"눈사람의 열이 손으로 오기 때문이다","mis":"SC5-2-u3-X11"},{"t":"손과 눈사람 모두 그대로이기 때문이다","mis":"SC5-2-u3-X09"}],"explanation":["손이 더 따뜻해요.","열이 눈사람으로 가요.","그래서 녹아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_c#12','sci',5,2,'u3','','g5_2_sci_u3_review_c','unit_review','SC5-2-u3-C8',2,'ox','auto','철판과 버터처럼 종류가 다른 고체끼리도 맞닿아 있으면 열이 이동해요.',ARRAY['SC5-2-u3-X16']::text[],false,'{"seq":12,"concept":"SC5-2-u3-C8","difficulty":2,"kind":"ox","stem":"철판과 버터처럼 종류가 다른 고체끼리도 맞닿아 있으면 열이 이동해요.","answer":"O","reason_options":[{"t":"맞닿아 있으면 온도가 높은 쪽에서 낮은 쪽으로 전도되기 때문에","correct":true},{"t":"같은 종류의 고체끼리만 열이 이동하기 때문에","mis":"SC5-2-u3-X16"}],"mis":"SC5-2-u3-X16","explanation":["철판과 버터가 닿아요.","열이 버터로 가요.","그래서 녹아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_c#13','sci',5,2,'u3','','g5_2_sci_u3_review_c','unit_review','SC5-2-u3-C13',2,'ox','auto','냉방기는 방의 높은 곳에 달면 방 전체가 고르게 시원해지기 쉬워요.',ARRAY['SC5-2-u3-X23']::text[],false,'{"seq":13,"concept":"SC5-2-u3-C13","difficulty":2,"kind":"ox","stem":"냉방기는 방의 높은 곳에 달면 방 전체가 고르게 시원해지기 쉬워요.","answer":"O","reason_options":[{"t":"차가운 공기가 아래로 내려오며 방 공기가 돌기 때문에","correct":true},{"t":"차가운 공기는 위로 올라가 천장에 머물기 때문에","mis":"SC5-2-u3-X23"}],"mis":"SC5-2-u3-X23","explanation":["차가운 공기는 내려와요.","방 공기가 돌아요.","높은 곳이 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_c#14','sci',5,2,'u3','','g5_2_sci_u3_review_c','unit_review','SC5-2-u3-C15',2,'ox','auto','해의 열은 물질이 닿지 않아도 빛에 의해 지구까지 와요.',ARRAY['SC5-2-u3-X25']::text[],false,'{"seq":14,"concept":"SC5-2-u3-C15","difficulty":2,"kind":"ox","stem":"해의 열은 물질이 닿지 않아도 빛에 의해 지구까지 와요.","answer":"O","reason_options":[{"t":"복사는 물질 없이도 빛에 의해 열이 이동하기 때문에","correct":true},{"t":"해와 지구 사이를 고체가 이어 전도하기 때문에","mis":"SC5-2-u3-X25"}],"mis":"SC5-2-u3-X25","explanation":["해는 아주 멀어요.","빛이 열을 옮겨요.","복사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_c#15','sci',5,2,'u3','','g5_2_sci_u3_review_c','unit_review','SC5-2-u3-C16',2,'ox','auto','화덕 피자처럼 한 상황에서 전도·대류·복사가 함께 일어날 수 있어요.',ARRAY['SC5-2-u3-X27']::text[],false,'{"seq":15,"concept":"SC5-2-u3-C16","difficulty":2,"kind":"ox","stem":"화덕 피자처럼 한 상황에서 전도·대류·복사가 함께 일어날 수 있어요.","answer":"O","reason_options":[{"t":"돌판·뜨거운 공기·벽과 불빛이 함께 피자를 데우기 때문에","correct":true},{"t":"한 상황에서는 한 방식만 일어나기 때문에","mis":"SC5-2-u3-X27"}],"mis":"SC5-2-u3-X27","explanation":["돌판은 전도예요.","공기는 대류예요.","불빛은 복사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_c#16','sci',5,2,'u3','','g5_2_sci_u3_review_c','unit_review','SC5-2-u3-C18',2,'ox','auto','양산은 햇빛의 복사로 오는 열을 막아 줘요.',ARRAY['SC5-2-u3-X31']::text[],false,'{"seq":16,"concept":"SC5-2-u3-C18","difficulty":2,"kind":"ox","stem":"양산은 햇빛의 복사로 오는 열을 막아 줘요.","answer":"O","reason_options":[{"t":"양산이 햇빛을 가리기 때문에","correct":true},{"t":"양산이 손잡이를 따라 오는 전도를 막기 때문에","mis":"SC5-2-u3-X31"}],"mis":"SC5-2-u3-X31","explanation":["양산은 햇빛을 가려요.","빛으로 오는 열이에요.","복사를 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_c#17','sci',5,2,'u3','','g5_2_sci_u3_review_c','unit_review','SC5-2-u3-C3',3,'mc','auto','반짝이는 금속 냄비 겉면을 적외선 온도계로 재면 온도가 이상하게 나오는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X08','SC5-2-u3-X07','SC5-2-u3-X04']::text[],false,'{"seq":17,"concept":"SC5-2-u3-C3","difficulty":3,"kind":"mc","stem":"반짝이는 금속 냄비 겉면을 적외선 온도계로 재면 온도가 이상하게 나오는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"금속이 빛을 반사해 적외선 온도계로 재기 어렵기 때문이다","correct":true},{"t":"금속은 온도가 없기 때문이다","mis":"SC5-2-u3-X08"},{"t":"적외선 온도계는 물속만 재기 때문이다","mis":"SC5-2-u3-X07"},{"t":"손으로 재야 정확하기 때문이다","mis":"SC5-2-u3-X04"}],"explanation":["금속은 반짝여요.","빛을 반사해요.","재기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_c#18','sci',5,2,'u3','','g5_2_sci_u3_review_c','unit_review','SC5-2-u3-C5',3,'error','auto','햇빛반 캠프 일지 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u3-X13','SC5-2-u3-X10','SC5-2-u3-X11']::text[],false,'{"seq":18,"concept":"SC5-2-u3-C5","difficulty":3,"kind":"error","stem":"햇빛반 캠프 일지 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하윤 — 「온도는 처음부터 끝까지 똑같은 빠르기로 변했어.」","correct":true,"mis_target":"SC5-2-u3-X13"},{"t":"지오 — 「12분에 두 온도가 같아졌어.」","mis":"SC5-2-u3-X10"},{"t":"세린 — 「코코아의 열이 우유 팩으로 갔어.」","mis":"SC5-2-u3-X11"}],"explanation":["처음엔 크게 변해요.","점점 작아져요.","하윤의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["따뜻한 코코아 컵 속에 차가운 우유 팩을 넣고 온도를 쟀다.","0분 — 코코아 50 °C · 우유 팩 10 °C","4분 — 코코아 40 °C · 우유 팩 22 °C","8분 — 코코아 34 °C · 우유 팩 28 °C","12분 — 코코아 31 °C · 우유 팩 31 °C"],"title":"② 첫날 저녁 — 코코아와 우유 팩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_c#19','sci',5,2,'u3','','g5_2_sci_u3_review_c','unit_review','SC5-2-u3-C12',3,'mc','auto','대류와 전도의 차이를 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-2-u3-X17','SC5-2-u3-X28','SC5-2-u3-X22']::text[],false,'{"seq":19,"concept":"SC5-2-u3-C12","difficulty":3,"kind":"mc","stem":"대류와 전도의 차이를 바르게 말한 것은 어느 것인가요?","options":[{"t":"대류는 물질이 직접 움직이고, 전도는 고체 물질을 따라 열이 이동한다","correct":true},{"t":"대류는 고체에서, 전도는 액체에서 일어난다","mis":"SC5-2-u3-X17"},{"t":"둘 다 빛에 의해 열이 이동한다","mis":"SC5-2-u3-X28"},{"t":"대류는 물질이 가만히 있고 열만 간다","mis":"SC5-2-u3-X22"}],"explanation":["대류는 움직여요.","전도는 고체를 따라요.","차이가 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_c#20','sci',5,2,'u3','','g5_2_sci_u3_review_c','unit_review','SC5-2-u3-C16',3,'ox','auto','라면을 끓일 때 냄비 바닥에서는 전도, 냄비 속 물에서는 대류가 일어나요.',ARRAY['SC5-2-u3-X28']::text[],false,'{"seq":20,"concept":"SC5-2-u3-C16","difficulty":3,"kind":"ox","stem":"라면을 끓일 때 냄비 바닥에서는 전도, 냄비 속 물에서는 대류가 일어나요.","answer":"O","reason_options":[{"t":"바닥은 고체를 따라, 물은 직접 움직이며 열이 이동하기 때문에","correct":true},{"t":"냄비와 물 모두 빛에 의해서만 데워지기 때문에","mis":"SC5-2-u3-X28"}],"mis":"SC5-2-u3-X28","explanation":["바닥은 고체예요.","물은 움직여요.","두 방식이 함께예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_c#21','sci',5,2,'u3','','g5_2_sci_u3_review_c','unit_review','SC5-2-u3-C20',3,'error','auto','햇빛반 캠프 일지 ⑧을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u3-X34','SC5-2-u3-X31']::text[],false,'{"seq":21,"concept":"SC5-2-u3-C20","difficulty":3,"kind":"error","stem":"햇빛반 캠프 일지 ⑧을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태윤 — 「나 장치가 온도가 가장 많이 변했으니 가장 잘 만든 거야.」","correct":true,"mis_target":"SC5-2-u3-X34"},{"t":"하은 — 「세 장치에 같은 온도의 물을 넣어서 견줄 수 있어.」","mis":"SC5-2-u3-X34"},{"t":"도윤 — 「다 장치의 은박지는 복사를 줄여.」","mis":"SC5-2-u3-X31"}],"explanation":["덜 변해야 잘된 거예요.","나는 많이 식었어요.","태윤의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["같은 온도의 따뜻한 물을 세 장치에 넣고 30분 뒤 다시 쟀다.","가 — 뽁뽁이 두 겹, 뚜껑 덮음: 4 °C 낮아짐","나 — 신문지 한 겹, 뚜껑 없음: 15 °C 낮아짐","다 — 스타이로폼 상자, 뚜껑, 은박지: 2 °C 낮아짐","마지막 영상 — 인공 태양 연구 장치의 단열 이야기"],"title":"⑧ 마지막 날 — 장치 대회와 영상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_c#22','sci',5,2,'u3','','g5_2_sci_u3_review_c','unit_review','SC5-2-u3-C22',3,'error','auto','단원을 마무리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u3-X29','SC5-2-u3-X11','SC5-2-u3-X30']::text[],false,'{"seq":22,"concept":"SC5-2-u3-C22","difficulty":3,"kind":"error","stem":"단원을 마무리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서아 — 「보온병은 이름처럼 따뜻한 것만 지켜.」","correct":true,"mis_target":"SC5-2-u3-X29"},{"t":"지호 — 「열은 높은 쪽에서 낮은 쪽으로 이동해.」","mis":"SC5-2-u3-X11"},{"t":"민서 — 「단열은 전도·대류·복사를 막는 거야.」","mis":"SC5-2-u3-X30"}],"explanation":["보온병은 열을 막아요.","차갑게도 지켜요.","서아의 말이 잘못됐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_c#23','sci',5,2,'u3','','g5_2_sci_u3_review_c','unit_review','SC5-2-u3-C6',4,'mc','auto','냉동실에서 꺼낸 얼음과자를 쟁반에 두었더니 녹았어요. 열이 얼음과자로 온 곳을 바르게 모은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X12','SC5-2-u3-X11','SC5-2-u3-X09']::text[],false,'{"seq":23,"concept":"SC5-2-u3-C6","difficulty":4,"kind":"mc","stem":"냉동실에서 꺼낸 얼음과자를 쟁반에 두었더니 녹았어요. 열이 얼음과자로 온 곳을 바르게 모은 것은 어느 것인가요?","options":[{"t":"얼음과자보다 온도가 높은 공기와 쟁반","correct":true},{"t":"얼음과자의 냉기가 공기로 빠져나갔을 뿐이다","mis":"SC5-2-u3-X12"},{"t":"얼음과자에서 공기와 쟁반으로 열이 갔다","mis":"SC5-2-u3-X11"},{"t":"쟁반만 변하고 얼음과자는 그대로이다","mis":"SC5-2-u3-X09"}],"explanation":["공기가 더 따뜻해요.","쟁반도 더 따뜻해요.","두 곳에서 와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_c#24','sci',5,2,'u3','','g5_2_sci_u3_review_c','unit_review','SC5-2-u3-C16',4,'mc','auto','모닥불에 냄비를 걸어 물을 끓이는 장면에서 전도·대류·복사를 하나씩 바르게 찾은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X28','SC5-2-u3-X27','SC5-2-u3-X17']::text[],false,'{"seq":24,"concept":"SC5-2-u3-C16","difficulty":4,"kind":"mc","stem":"모닥불에 냄비를 걸어 물을 끓이는 장면에서 전도·대류·복사를 하나씩 바르게 찾은 것은 어느 것인가요?","options":[{"t":"냄비 바닥 — 전도, 냄비 속 물 — 대류, 불을 쬐는 손 — 복사","correct":true},{"t":"냄비 바닥 — 대류, 냄비 속 물 — 복사, 불을 쬐는 손 — 전도","mis":"SC5-2-u3-X28"},{"t":"냄비 바닥 — 복사, 냄비 속 물 — 복사, 불을 쬐는 손 — 복사","mis":"SC5-2-u3-X27"},{"t":"냄비 바닥 — 전도, 냄비 속 물 — 전도, 불을 쬐는 손 — 대류","mis":"SC5-2-u3-X17"}],"explanation":["바닥은 고체예요.","물은 움직여요.","손은 빛을 받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_c#25','sci',5,2,'u3','','g5_2_sci_u3_review_c','unit_review','SC5-2-u3-C19',4,'mc','auto','얼음을 오래 녹지 않게 하는 장치로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X30','SC5-2-u3-X33','SC5-2-u3-X32']::text[],false,'{"seq":25,"concept":"SC5-2-u3-C19","difficulty":4,"kind":"mc","stem":"얼음을 오래 녹지 않게 하는 장치로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"스타이로폼 상자에 얼음을 넣고 뚜껑을 덮은 뒤 겉을 은박지로 감싼다","correct":true},{"t":"금속 그릇에 얼음을 담아 햇빛에 둔다","mis":"SC5-2-u3-X30"},{"t":"구멍 뚫린 상자에 넣어 바람이 잘 통하게 한다","mis":"SC5-2-u3-X33"},{"t":"얼음을 더 차갑게 만드는 솜으로만 덮는다","mis":"SC5-2-u3-X32"}],"explanation":["스타이로폼이 막아요.","뚜껑이 막아요.","은박지가 빛을 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#1','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C2',1,'mc','auto','「따뜻하다」, 「차갑다」를 숫자로 나타낸 것을 무엇이라고 하나요?',ARRAY['SC5-2-u3-X08']::text[],false,'{"seq":1,"concept":"SC5-2-u3-C2","difficulty":1,"kind":"mc","stem":"「따뜻하다」, 「차갑다」를 숫자로 나타낸 것을 무엇이라고 하나요?","options":[{"t":"온도","correct":true},{"t":"무게","mis":"SC5-2-u3-X08"},{"t":"길이","mis":"SC5-2-u3-X08"},{"t":"부피","mis":"SC5-2-u3-X08"}],"explanation":["따뜻한 정도예요.","숫자로 나타내요.","온도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#2','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C4',1,'mc','auto','햇빛반 캠프 일지 ①에서 모둠장이 「느낌 말고 숫자로 적자」고 한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X08','SC5-2-u3-X04']::text[],false,'{"seq":2,"concept":"SC5-2-u3-C4","difficulty":1,"kind":"mc","stem":"햇빛반 캠프 일지 ①에서 모둠장이 「느낌 말고 숫자로 적자」고 한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"숫자로 적으면 누구나 같게, 정확하게 알 수 있어서","correct":true},{"t":"숫자로 적으면 물체가 따뜻해져서","mis":"SC5-2-u3-X08"},{"t":"느낌이 숫자보다 늘 정확해서","mis":"SC5-2-u3-X04"},{"t":"숫자는 사람마다 다르게 읽혀서","mis":"SC5-2-u3-X04"}],"explanation":["느낌은 달라요.","숫자는 같아요.","정확해요."],"asset":{"type":"passage","lines":["캠프 첫날, 이름표에 열 변색 붙임딱지를 붙였다. 손을 대면 색이 바뀌었다.","텐트 안 공기 — 알코올 온도계: 6.5 °C","물통 속 물 — 탐침 온도계: 12.0 °C","나무 의자 표면 — 적외선 온도계: 3.8 °C","모둠장 은찬: 「느낌 말고 숫자로 적자.」"],"title":"① 첫날 — 이름표와 온도 재기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#3','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C5',1,'sa','auto','햇빛반 캠프 일지 ②에서 코코아와 우유 팩의 온도가 같아진 때는 몇 분인가요? 숫자만 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC5-2-u3-C5","difficulty":1,"kind":"sa","stem":"햇빛반 캠프 일지 ②에서 코코아와 우유 팩의 온도가 같아진 때는 몇 분인가요? 숫자만 쓰세요.","answer":["12"],"explanation":["두 온도를 견줘요.","31 °C로 같아요.","12분이에요."],"asset":{"type":"passage","lines":["따뜻한 코코아 컵 속에 차가운 우유 팩을 넣고 온도를 쟀다.","0분 — 코코아 50 °C · 우유 팩 10 °C","4분 — 코코아 40 °C · 우유 팩 22 °C","8분 — 코코아 34 °C · 우유 팩 28 °C","12분 — 코코아 31 °C · 우유 팩 31 °C"],"title":"② 첫날 저녁 — 코코아와 우유 팩"},"mis":"SC5-2-u3-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#4','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C9',1,'mc','auto','프라이팬 바닥을 금속으로 만드는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X18']::text[],false,'{"seq":4,"concept":"SC5-2-u3-C9","difficulty":1,"kind":"mc","stem":"프라이팬 바닥을 금속으로 만드는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"열이 잘 이동해 음식이 빨리 익게 하려고","correct":true},{"t":"열이 음식으로 가지 않게 하려고","mis":"SC5-2-u3-X18"},{"t":"손잡이를 차갑게 하려고","mis":"SC5-2-u3-X18"},{"t":"음식 색을 바꾸려고","mis":"SC5-2-u3-X18"}],"explanation":["금속은 열이 잘 가요.","바닥이 뜨거워요.","빨리 익어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
