INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#7','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C18',1,'mc','auto','단열을 이용하는 물건이 아닌 것은 어느 것인가요?',ARRAY['SC5-2-u3-X30']::text[],false,'{"seq":7,"concept":"SC5-2-u3-C18","difficulty":1,"kind":"mc","stem":"단열을 이용하는 물건이 아닌 것은 어느 것인가요?","options":[{"t":"금속 프라이팬","correct":true},{"t":"보온 도시락","mis":"SC5-2-u3-X30"},{"t":"아이스박스","mis":"SC5-2-u3-X30"},{"t":"겹쳐 입은 옷","mis":"SC5-2-u3-X30"}],"explanation":["프라이팬은 열을 전해요.","나머지는 막아요.","프라이팬이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#8','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C19',1,'mc','auto','캠프 장치 대회에서 단열재로 쓰기에 알맞은 재료는 어느 것인가요?',ARRAY['SC5-2-u3-X30']::text[],false,'{"seq":8,"concept":"SC5-2-u3-C19","difficulty":1,"kind":"mc","stem":"캠프 장치 대회에서 단열재로 쓰기에 알맞은 재료는 어느 것인가요?","options":[{"t":"솜","correct":true},{"t":"구리판","mis":"SC5-2-u3-X30"},{"t":"알루미늄 캔","mis":"SC5-2-u3-X30"},{"t":"금속 국자","mis":"SC5-2-u3-X30"}],"explanation":["솜은 열을 막아요.","금속은 열이 잘 가요.","솜이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#9','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C2',2,'ox','auto','햇빛반 캠프 일지 ①에서 물통 속 물이 텐트 안 공기보다 온도가 높아요.',ARRAY['SC5-2-u3-X04']::text[],false,'{"seq":9,"concept":"SC5-2-u3-C2","difficulty":2,"kind":"ox","stem":"햇빛반 캠프 일지 ①에서 물통 속 물이 텐트 안 공기보다 온도가 높아요.","answer":"O","reason_options":[{"t":"12.0 °C가 6.5 °C보다 크기 때문에","correct":true},{"t":"공기는 언제나 물보다 따뜻하기 때문에","mis":"SC5-2-u3-X04"}],"mis":"SC5-2-u3-X04","explanation":["숫자를 견줘요.","12.0이 더 커요.","물이 더 높아요."],"asset":{"type":"passage","lines":["캠프 첫날, 이름표에 열 변색 붙임딱지를 붙였다. 손을 대면 색이 바뀌었다.","텐트 안 공기 — 알코올 온도계: 6.5 °C","물통 속 물 — 탐침 온도계: 12.0 °C","나무 의자 표면 — 적외선 온도계: 3.8 °C","모둠장 은찬: 「느낌 말고 숫자로 적자.」"],"title":"① 첫날 — 이름표와 온도 재기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#10','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C5',2,'mc','auto','햇빛반 캠프 일지 ②의 결과를 바르게 정리한 것은 어느 것인가요?',ARRAY['SC5-2-u3-X09','SC5-2-u3-X10','SC5-2-u3-X13']::text[],false,'{"seq":10,"concept":"SC5-2-u3-C5","difficulty":2,"kind":"mc","stem":"햇빛반 캠프 일지 ②의 결과를 바르게 정리한 것은 어느 것인가요?","options":[{"t":"코코아는 낮아지고 우유 팩은 높아져 결국 같아졌다","correct":true},{"t":"코코아만 낮아지고 우유 팩은 그대로였다","mis":"SC5-2-u3-X09"},{"t":"두 온도는 끝까지 같아지지 않았다","mis":"SC5-2-u3-X10"},{"t":"변화는 처음과 끝이 같은 빠르기였다","mis":"SC5-2-u3-X13"}],"explanation":["둘 다 변했어요.","처음엔 크게요.","같아졌어요."],"asset":{"type":"passage","lines":["따뜻한 코코아 컵 속에 차가운 우유 팩을 넣고 온도를 쟀다.","0분 — 코코아 50 °C · 우유 팩 10 °C","4분 — 코코아 40 °C · 우유 팩 22 °C","8분 — 코코아 34 °C · 우유 팩 28 °C","12분 — 코코아 31 °C · 우유 팩 31 °C"],"title":"② 첫날 저녁 — 코코아와 우유 팩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#11','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C6',2,'match','auto','캠프 장면과 열이 이동하는 쪽을 이으세요.','{}'::text[],false,'{"seq":11,"concept":"SC5-2-u3-C6","difficulty":2,"kind":"match","stem":"캠프 장면과 열이 이동하는 쪽을 이으세요.","pairs":[{"l":"코코아 속 우유 팩","r":"코코아 → 우유 팩"},{"l":"맨손으로 뭉친 눈","r":"손 → 눈"},{"l":"햇빛반 찬 물통을 쥔 손","r":"손 → 물통"}],"mis":"SC5-2-u3-X11","explanation":["더 따뜻한 쪽을 찾아요.","그쪽에서 나가요.","낮은 쪽으로 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#12','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C8',2,'mc','auto','철판에 닿지 않은 고기 윗부분까지 익는 까닭이 되는 열의 이동 방식은 어느 것인가요?',ARRAY['SC5-2-u3-X26','SC5-2-u3-X17','SC5-2-u3-X28']::text[],false,'{"seq":12,"concept":"SC5-2-u3-C8","difficulty":2,"kind":"mc","stem":"철판에 닿지 않은 고기 윗부분까지 익는 까닭이 되는 열의 이동 방식은 어느 것인가요?","options":[{"t":"전도","correct":true},{"t":"복사","mis":"SC5-2-u3-X26"},{"t":"대류","mis":"SC5-2-u3-X17"},{"t":"응결","mis":"SC5-2-u3-X28"}],"explanation":["고기는 고체예요.","고기를 따라 올라가요.","전도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#13','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C11',2,'mc','auto','아크릴 통 안 촛불 실험에서 붙임딱지가 변하는 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X21']::text[],false,'{"seq":13,"concept":"SC5-2-u3-C11","difficulty":2,"kind":"mc","stem":"아크릴 통 안 촛불 실험에서 붙임딱지가 변하는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"위 → 가운데 → 아래","correct":true},{"t":"아래 → 가운데 → 위","mis":"SC5-2-u3-X21"},{"t":"세 곳이 한꺼번에","mis":"SC5-2-u3-X21"},{"t":"가운데 → 아래 → 위","mis":"SC5-2-u3-X21"}],"explanation":["데워진 공기는 올라가요.","위부터 따뜻해요.","아래가 마지막이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#14','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C14',2,'mc','auto','나무 그늘이 시원한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X12','SC5-2-u3-X25','SC5-2-u3-X24']::text[],false,'{"seq":14,"concept":"SC5-2-u3-C14","difficulty":2,"kind":"mc","stem":"나무 그늘이 시원한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나뭇잎이 햇빛을 가려 복사로 오는 열이 줄어서","correct":true},{"t":"나무가 냉기를 내뿜어서","mis":"SC5-2-u3-X12"},{"t":"그늘에는 공기가 없어서","mis":"SC5-2-u3-X25"},{"t":"그늘 땅이 스스로 열을 만들어서","mis":"SC5-2-u3-X24"}],"explanation":["나뭇잎이 가려요.","오는 열이 줄어요.","시원해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#15','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C16',2,'match','auto','화덕 피자가 열을 받는 곳과 방식을 이으세요.','{}'::text[],false,'{"seq":15,"concept":"SC5-2-u3-C16","difficulty":2,"kind":"match","stem":"화덕 피자가 열을 받는 곳과 방식을 이으세요.","pairs":[{"l":"뜨거운 돌판","r":"전도"},{"l":"도는 뜨거운 공기","r":"대류"},{"l":"벽과 불빛","r":"복사"}],"mis":"SC5-2-u3-X28","explanation":["돌판은 닿아요.","공기는 움직여요.","불빛은 빛이에요."],"asset":{"type":"passage","lines":["돌로 만든 화덕에 장작을 피우고 피자를 넣었다.","피자 바닥은 뜨거운 돌판에 닿아 있었다.","화덕 안 뜨거운 공기가 돌았고, 벽과 불빛도 피자를 데웠다."],"title":"⑥ 셋째 날 낮 — 화덕 피자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#16','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C18',2,'match','auto','물건과 막는 열의 이동 방식을 이으세요.','{}'::text[],false,'{"seq":16,"concept":"SC5-2-u3-C18","difficulty":2,"kind":"match","stem":"물건과 막는 열의 이동 방식을 이으세요.","pairs":[{"l":"나무 냄비 받침","r":"전도"},{"l":"문풍지","r":"대류"},{"l":"그늘막","r":"복사"}],"mis":"SC5-2-u3-X31","explanation":["받침은 닿는 열이에요.","문풍지는 공기 흐름이에요.","그늘막은 햇빛이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#17','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C3',3,'mc','auto','텐트 안 공기 온도를 하루 내내 같은 방법으로 보려고 해요. 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X04','SC5-2-u3-X07']::text[],false,'{"seq":17,"concept":"SC5-2-u3-C3","difficulty":3,"kind":"mc","stem":"텐트 안 공기 온도를 하루 내내 같은 방법으로 보려고 해요. 가장 알맞은 것은 어느 것인가요?","options":[{"t":"텐트 안에 알코올 온도계를 걸어 두고 눈높이에서 읽는다","correct":true},{"t":"공기를 손으로 느껴 적는다","mis":"SC5-2-u3-X04"},{"t":"적외선 온도계로 텐트 천만 잰다","mis":"SC5-2-u3-X07"},{"t":"탐침을 땅속에 꽂아 둔다","mis":"SC5-2-u3-X07"}],"explanation":["공기 온도예요.","걸어 둘 수 있어요.","알코올 온도계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#18','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C5',3,'ox','auto','50 °C 코코아와 10 °C 우유 팩의 온도는 50 °C보다 높아지거나 10 °C보다 낮아지지 않고 그 사이에서 같아져요.',ARRAY['SC5-2-u3-X10']::text[],false,'{"seq":18,"concept":"SC5-2-u3-C5","difficulty":3,"kind":"ox","stem":"50 °C 코코아와 10 °C 우유 팩의 온도는 50 °C보다 높아지거나 10 °C보다 낮아지지 않고 그 사이에서 같아져요.","answer":"O","reason_options":[{"t":"높은 쪽은 내려오고 낮은 쪽은 올라가 그 사이에서 만나기 때문에","correct":true},{"t":"우유 팩이 코코아보다 뜨거워질 수 있기 때문에","mis":"SC5-2-u3-X10"}],"mis":"SC5-2-u3-X10","explanation":["높은 쪽은 내려와요.","낮은 쪽은 올라가요.","사이에서 만나요."],"asset":{"type":"passage","lines":["따뜻한 코코아 컵 속에 차가운 우유 팩을 넣고 온도를 쟀다.","0분 — 코코아 50 °C · 우유 팩 10 °C","4분 — 코코아 40 °C · 우유 팩 22 °C","8분 — 코코아 34 °C · 우유 팩 28 °C","12분 — 코코아 31 °C · 우유 팩 31 °C"],"title":"② 첫날 저녁 — 코코아와 우유 팩"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#19','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C13',3,'mc','auto','캠프 식당 천장에 달린 냉방기를 켰어요. 식당에서 일어나는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X20','SC5-2-u3-X17','SC5-2-u3-X22']::text[],false,'{"seq":19,"concept":"SC5-2-u3-C13","difficulty":3,"kind":"mc","stem":"캠프 식당 천장에 달린 냉방기를 켰어요. 식당에서 일어나는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"차가운 공기가 내려오고 데워진 공기가 올라가며 식당 전체가 시원해진다","correct":true},{"t":"차가운 공기가 천장에만 머문다","mis":"SC5-2-u3-X20"},{"t":"냉방기의 냉기가 벽을 따라 전도된다","mis":"SC5-2-u3-X17"},{"t":"공기는 움직이지 않고 냉기만 퍼진다","mis":"SC5-2-u3-X22"}],"explanation":["차가운 공기는 내려와요.","데워진 공기는 올라가요.","공기가 돌아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#20','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C16',3,'mc','auto','요리 방법과 주로 이용하는 열의 이동 방식을 바르게 짝지은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X28']::text[],false,'{"seq":20,"concept":"SC5-2-u3-C16","difficulty":3,"kind":"mc","stem":"요리 방법과 주로 이용하는 열의 이동 방식을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"숯불 바비큐 — 복사","correct":true},{"t":"프라이팬 볶음 — 대류","mis":"SC5-2-u3-X28"},{"t":"찜기 만두 — 전도","mis":"SC5-2-u3-X28"},{"t":"국 끓이기 — 복사","mis":"SC5-2-u3-X28"}],"explanation":["숯불은 빛을 내요.","닿지 않아도 와요.","복사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#21','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C20',3,'ox','auto','햇빛반 캠프 일지 ⑧처럼 장치를 견줄 때 처음 온도와 재는 시간을 같게 한 것은 바른 방법이에요.',ARRAY['SC5-2-u3-X34']::text[],false,'{"seq":21,"concept":"SC5-2-u3-C20","difficulty":3,"kind":"ox","stem":"햇빛반 캠프 일지 ⑧처럼 장치를 견줄 때 처음 온도와 재는 시간을 같게 한 것은 바른 방법이에요.","answer":"O","reason_options":[{"t":"다른 조건이 같아야 장치의 차이만 견줄 수 있기 때문에","correct":true},{"t":"장치마다 조건을 모두 다르게 해야 하기 때문에","mis":"SC5-2-u3-X34"}],"mis":"SC5-2-u3-X34","explanation":["처음 온도가 같아요.","시간도 같아요.","바른 방법이에요."],"asset":{"type":"passage","lines":["같은 온도의 따뜻한 물을 세 장치에 넣고 30분 뒤 다시 쟀다.","가 — 뽁뽁이 두 겹, 뚜껑 덮음: 4 °C 낮아짐","나 — 신문지 한 겹, 뚜껑 없음: 15 °C 낮아짐","다 — 스타이로폼 상자, 뚜껑, 은박지: 2 °C 낮아짐","마지막 영상 — 인공 태양 연구 장치의 단열 이야기"],"title":"⑧ 마지막 날 — 장치 대회와 영상"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#22','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C22',3,'match','auto','열의 이동 방식과 일어나는 곳, 막는 물건을 알맞게 이으세요.','{}'::text[],false,'{"seq":22,"concept":"SC5-2-u3-C22","difficulty":3,"kind":"match","stem":"열의 이동 방식과 일어나는 곳, 막는 물건을 알맞게 이으세요.","pairs":[{"l":"전도 — 고체","r":"주방 장갑"},{"l":"대류 — 액체와 기체","r":"닫은 창문"},{"l":"복사 — 빛","r":"양산"}],"mis":"SC5-2-u3-X31","explanation":["장갑은 닿는 열을 막아요.","창문은 공기 흐름을 막아요.","양산은 햇빛을 막아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#23','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C6',4,'mc','auto','뜨거운 코코아 컵을 두 손으로 감싸 쥐었어요. 일어나는 일을 가장 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-2-u3-X12','SC5-2-u3-X11','SC5-2-u3-X09']::text[],false,'{"seq":23,"concept":"SC5-2-u3-C6","difficulty":4,"kind":"mc","stem":"뜨거운 코코아 컵을 두 손으로 감싸 쥐었어요. 일어나는 일을 가장 바르게 말한 것은 어느 것인가요?","options":[{"t":"컵의 열이 손으로 이동해 손은 따뜻해지고 코코아는 조금 식는다","correct":true},{"t":"손의 냉기가 컵으로 가서 코코아가 식는다","mis":"SC5-2-u3-X12"},{"t":"손의 열이 컵으로 가서 코코아가 더 뜨거워진다","mis":"SC5-2-u3-X11"},{"t":"손만 따뜻해지고 코코아의 온도는 그대로이다","mis":"SC5-2-u3-X09"}],"explanation":["컵이 더 뜨거워요.","열이 손으로 와요.","둘 다 변해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#24','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C16',4,'mc','auto','텐트 안 난로 옆에 쇠 국자를 두었어요. 일어나는 일을 열의 이동 방식과 가장 바르게 이은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X14','SC5-2-u3-X12','SC5-2-u3-X25']::text[],false,'{"seq":24,"concept":"SC5-2-u3-C16","difficulty":4,"kind":"mc","stem":"텐트 안 난로 옆에 쇠 국자를 두었어요. 일어나는 일을 열의 이동 방식과 가장 바르게 이은 것은 어느 것인가요?","options":[{"t":"난로 빛을 받은 국자가 데워지고(복사), 그 열이 국자 손잡이로 퍼진다(전도)","correct":true},{"t":"국자 손잡이가 먼저 뜨거워지고 그다음 국자 머리가 데워진다(대류)","mis":"SC5-2-u3-X14"},{"t":"국자의 냉기가 난로로 가서 국자가 데워진다(전도)","mis":"SC5-2-u3-X12"},{"t":"국자는 난로에 닿지 않아 데워지지 않는다","mis":"SC5-2-u3-X25"}],"explanation":["난로 빛을 받아요.","국자를 따라 퍼져요.","복사와 전도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_sci_u3_review_d#25','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C20',4,'mc','auto','두 모둠의 장치를 공정하게 견주는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X34','SC5-2-u3-X04']::text[],false,'{"seq":25,"concept":"SC5-2-u3-C20","difficulty":4,"kind":"mc","stem":"두 모둠의 장치를 공정하게 견주는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"같은 온도의 물을 같은 양만큼 넣고 같은 시간 뒤에 같은 온도계로 잰다","correct":true},{"t":"한 모둠은 따뜻한 물, 한 모둠은 차가운 물을 넣는다","mis":"SC5-2-u3-X34"},{"t":"장치의 색깔이 더 예쁜 쪽을 고른다","mis":"SC5-2-u3-X34"},{"t":"한 장치만 재고 다른 장치는 손으로 만져 본다","mis":"SC5-2-u3-X04"}],"explanation":["조건을 같게 해요.","같은 시간에 재요.","공정하게 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
